// ===== CLASS DATETIME + COUNTDOWN =====
function parseClassDT(dateStr,timeStr){
  if(!dateStr) return null;
  const d=new Date(dateStr); if(isNaN(d)) return null;
  let h=9,m=0;
  if(timeStr){
 const t=String(timeStr).toLowerCase().replace(/[:\.]?\s*(am|pm)/,' $1');
 const mm=t.match(/(\d{1,2})\s*[:\.]\s*(\d{2})?\s*(am|pm)?/);
 if(mm){ h=parseInt(mm[1]); m=mm[2]?parseInt(mm[2]):0; const ap=mm[3];
 if(ap==='pm'&&h<12)h+=12; if(ap==='am'&&h===12)h=0; }
  }
  d.setHours(h,m,0,0); return d;
}
let _cdTimer=null;
function startLiveCountdown(entries){
  clearInterval(_cdTimer);
  const banner=document.getElementById('s-live-banner'); if(!banner) return;
  const list=entries.map(e=>({...e,dt:parseClassDT(e.date,e.time)})).filter(e=>e.dt);
  function pick(){
 const now=new Date();
 // class considered "live" for 90 min after start
 const live=list.filter(e=>e.dt<=now && (now-e.dt)<90*60000).sort((a,b)=>b.dt-a.dt)[0];
 const next=list.filter(e=>e.dt>now).sort((a,b)=>a.dt-b.dt)[0];
 return {live,next};
  }
  function render(){
 const now=new Date(); const {live,next}=pick();
 if(live){
 banner.style.display='flex'; banner.className='live-banner now'; banner.style.background='';
 setIf(banner,`<div class="lb-left"><div class="lb-icon">${ic('calendar')}</div><div><span class="lb-tag"><span class="live-dot"></span>Live Now</span><h3>${esc(live.subject)}</h3><small>${esc(live.part||live.chapter||'')} ${live.time?'• '+esc(live.time):''}</small></div></div><button class="btn btn-primary btn-sm lb-join" onclick="openMVC()">${ic('play')} Join Class</button>`);
 return;
 }
 if(next){
 const diff=next.dt-now; const mins=diff/60000;
 banner.style.display='flex'; banner.style.background='';
 const dstr=next.dt.toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'});
 if(mins<=60){
 banner.className='live-banner soon';
 const tot=Math.floor(diff/1000), hh=Math.floor(tot/3600), mi=Math.floor((tot%3600)/60), ss=tot%60;
 setIf(banner,`<div class="lb-left"><div class="lb-icon">${ic('calendar')}</div><div><span class="lb-tag"><span class="live-dot"></span>Starting Soon</span><h3>${esc(next.subject)}</h3><small>${esc(next.part||next.chapter||'')} • ${dstr} ${next.time?'• '+esc(next.time):''}</small></div></div><div class="countdown">${hh>0?`<div class="cd-box"><div class="num">${hh}</div><div class="lbl">hrs</div></div>`:''}<div class="cd-box"><div class="num">${String(mi).padStart(2,'0')}</div><div class="lbl">min</div></div><div class="cd-box"><div class="num">${String(ss).padStart(2,'0')}</div><div class="lbl">sec</div></div></div>`);
 }else{
 banner.className='live-banner upcoming';
 setIf(banner,`<div class="lb-left"><div class="lb-icon">${ic('calendar')}</div><div><span class="lb-tag"><span class="live-dot"></span>Next Class</span><h3>${esc(next.subject)}</h3><small>${esc(next.part||next.chapter||'')} • ${dstr} ${next.time?'• '+esc(next.time):''}</small></div></div>`);
 }
 return;
 }
 banner.style.display='none';
  }
  render(); _cdTimer=setInterval(render,1000);
}
function setIf(el,html){ if(!el) return; if(el.__h===html) return; el.__h=html; el.innerHTML=html; }
function softSpin(el){ if(!el) return; const inPage=el.closest&&el.closest('.page'); if(inPage&&el.dataset.kept) return; el.innerHTML='<div class="spinner"></div>'; if(inPage) el.dataset.kept='1'; }
// ============ VOICE RECORDER (doubts) ============
const _vBlobs={}; let _vRec=null,_vKey=null;
function voiceUI(key){
  return `<div class="vc-wrap" id="vcw-${key}"><button type="button" class="vc-btn" id="vcb-${key}" onclick="voiceToggle('${key}')">${ic('play')} Record Voice</button><span id="vcs-${key}" style="font-size:.75rem;color:var(--text-muted)"></span></div>`;
}
async function voiceToggle(key){
  if(_vRec && _vKey===key){ _vRec.stop(); return; }
  if(_vRec){ toast('Another recording is in progress.',true); return; }
  try{
    const stream=await navigator.mediaDevices.getUserMedia({audio:true});
    const chunks=[]; const mr=new MediaRecorder(stream);
    _vRec=mr; _vKey=key;
    const btn=document.getElementById('vcb-'+key); btn.classList.add('rec'); btn.innerHTML='&#9632; Stop Recording';
    const st=document.getElementById('vcs-'+key); let sec=0; const tmr=setInterval(()=>{ sec++; if(st) st.textContent=sec+'s'; },1000);
    mr.ondataavailable=e=>{ if(e.data.size) chunks.push(e.data); };
    mr.onstop=()=>{
      clearInterval(tmr); stream.getTracks().forEach(t=>t.stop()); _vRec=null; _vKey=null;
      _vBlobs[key]=new Blob(chunks,{type:'audio/webm'});
      const url=URL.createObjectURL(_vBlobs[key]);
      document.getElementById('vcw-'+key).innerHTML=`<audio controls src="${url}"></audio><button type="button" class="vc-btn" onclick="voiceRemove('${key}')">${ic('trash')} Remove</button>`;
    };
    mr.start();
  }catch(e){ toast('Microphone access denied. Please allow the mic permission.',true); }
}
function voiceRemove(key){ delete _vBlobs[key]; const w=document.getElementById('vcw-'+key); if(w) w.outerHTML=voiceUI(key); }
// ============ CLAUDE-STYLE COMPOSER (doubts) ============
const _MICSVG='<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z"/><path d="M19 10v2a7 7 0 0 1-14 0v-2"/><line x1="12" y1="19" x2="12" y2="23"/><line x1="8" y1="23" x2="16" y2="23"/></svg>';
const _CAMSVG='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><circle cx="12" cy="13" r="4"/></svg>';
const _CLIPSVG='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48"/></svg>';
const _cmpState={}; let _cmpFocus=null;
function composerHTML(key,placeholder,onsend,sendLabel){
  _cmpState[key]={file:null,voice:null};
  return `<div class="cmp" id="cmp-${key}" ondragover="event.preventDefault();this.classList.add('dragging')" ondragleave="this.classList.remove('dragging')" ondrop="cmpDrop('${key}',event)">
    <div class="cmp-chips" id="cmpc-${key}"></div>
    <textarea class="cmp-ta" id="cmpt-${key}" rows="2" placeholder="${placeholder}" onfocus="_cmpFocus='${key}'" oninput="this.style.height='auto';this.style.height=Math.min(this.scrollHeight,170)+'px'"></textarea>
    <div class="cmp-bar">
      <div style="position:relative">
        <button type="button" class="cmp-ib" title="Add" onclick="cmpMenu('${key}',event)">+</button>
        <div class="cmp-menu" id="cmpm-${key}">
          <div class="cmp-mi" onclick="cmpPick('${key}',false)">${_CLIPSVG} Add files or photos</div>
          <div class="cmp-mi" onclick="cmpPick('${key}',true)">${_CAMSVG} Take a photo</div>
          <div class="cmp-hint">Tip: paste a screenshot here directly (Ctrl+V)</div>
        </div>
      </div>
      <div style="flex:1"></div>
      <button type="button" class="cmp-ib" id="cmpv-${key}" title="Record voice note" onclick="cmpVoice('${key}')">${_MICSVG}</button>
      <button type="button" class="btn btn-primary btn-sm" id="cmps-${key}" style="min-height:38px" onclick="${onsend}">${sendLabel||'Send'}</button>
    </div>
    <input type="file" id="cmpf-${key}" style="display:none" accept="image/*,application/pdf,.doc,.docx,.txt,.csv,.xls,.xlsx,.ppt,.pptx" onchange="cmpFileSel('${key}')">
    <input type="file" id="cmpcam-${key}" style="display:none" accept="image/*" capture="environment" onchange="cmpFileSel('${key}',1)">
  </div>`;
}
async function cmpDrop(key,e){
  e.preventDefault(); e.currentTarget.classList.remove('dragging');
  const dt=e.dataTransfer;
  const f=dt&&dt.files&&dt.files[0];
  if(f&&f.size>0){ if(await cmpSetFile(key,f)) toast('File added: '+f.name); return; }
  // webpage se drag: sirf URL milta hai — image ko khud fetch karne ki koshish
  let uri=''; try{ uri=dt.getData('text/uri-list')||dt.getData('text/plain')||''; }catch(err){}
  uri=(uri.split('\n')[0]||'').trim();
  if(/^https?:\/\//i.test(uri)){
    toast('Fetching the dragged image...');
    try{
      const ctl=new AbortController(); const t=setTimeout(()=>ctl.abort(),8000);
      const r=await fetch(uri,{signal:ctl.signal}); clearTimeout(t);
      if(!r.ok) throw 0;
      const b=await r.blob();
      if(!b.size||!(b.type||'').startsWith('image/')) throw 0;
      const name=(uri.split('/').pop()||'image').split('?')[0].slice(0,80)||'image.jpg';
      if(await cmpSetFile(key,new File([b],name,{type:b.type}))) toast('Image added: '+name);
      return;
    }catch(err){}
  }
  toast('Images cannot be dragged directly from a website. Please right-click the image \u2192 "Save image", then upload or drag it from your device.',true);
}
function cmpMenu(key,e){ e.stopPropagation(); document.querySelectorAll('.cmp-menu.open').forEach(m=>{ if(m.id!=='cmpm-'+key) m.classList.remove('open'); }); document.getElementById('cmpm-'+key).classList.toggle('open'); }
document.addEventListener('click',()=>document.querySelectorAll('.cmp-menu.open').forEach(m=>m.classList.remove('open')));
function cmpPick(key,cam){ document.getElementById((cam?'cmpcam-':'cmpf-')+key).click(); }
async function cmpFileSel(key,cam){
  const inp=document.getElementById((cam?'cmpcam-':'cmpf-')+key);
  if(inp.files&&inp.files.length){ await cmpSetFile(key,inp.files[0]); inp.value=''; }
}
async function cmpSetFile(key,f){
  if(!f||f.size===0){ toast('This file is empty or could not be read. Please save it to your device first, then upload.',true); return false; }
  if(f.size>MAXB){
    toast('Large file \u2014 compressing automatically\u2026');
    try{ const r=await smartCompress(f,m=>toast(m)); f=(r&&r.ok&&r.file)?r.file:null; }catch(e){ f=null; }
    if(!f){ toast('The file is still too large after compression. Please try a smaller file.',true); return false; }
    toast('Compressed. File added.');
  }
  if(!_cmpState[key]) _cmpState[key]={file:null,voice:null};
  _cmpState[key].file=f; cmpChips(key); return true;
}
function cmpChips(key){
  const st=_cmpState[key]; const c=document.getElementById('cmpc-'+key); if(!c) return;
  let h='';
  if(st.file) h+=`<span class="cmp-chip">${_CLIPSVG} <span style="max-width:170px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(st.file.name)}</span> <span style="color:var(--text-muted);font-weight:600">${(st.file.size/1024/1024).toFixed(1)}MB</span><button class="x" onclick="_cmpState['${key}'].file=null;cmpChips('${key}')">\u2715</button></span>`;
  if(st.voice) h+=`<span class="cmp-chip"><audio controls src="${URL.createObjectURL(st.voice)}"></audio><button class="x" onclick="_cmpState['${key}'].voice=null;cmpChips('${key}')">\u2715</button></span>`;
  if(st.recTimer!=null) h+=`<span class="cmp-chip"><span class="cmp-timer">\u25cf REC ${st.recSec||0}s \u2014 tap mic to stop</span></span>`;
  c.innerHTML=h;
}
async function cmpVoice(key){
  const st=_cmpState[key];
  if(_vRec&&_vKey===key){ _vRec.stop(); return; }
  if(_vRec){ toast('Another recording is in progress.',true); return; }
  try{
    const stream=await navigator.mediaDevices.getUserMedia({audio:true});
    const chunks=[]; const mr=new MediaRecorder(stream); _vRec=mr; _vKey=key;
    document.getElementById('cmpv-'+key).classList.add('rec');
    st.recSec=0; st.recTimer=setInterval(()=>{ st.recSec++; cmpChips(key); },1000); cmpChips(key);
    mr.ondataavailable=e=>{ if(e.data.size) chunks.push(e.data); };
    mr.onstop=()=>{
      clearInterval(st.recTimer); st.recTimer=null; stream.getTracks().forEach(t=>t.stop()); _vRec=null; _vKey=null;
      const btn=document.getElementById('cmpv-'+key); if(btn) btn.classList.remove('rec');
      st.voice=new Blob(chunks,{type:'audio/webm'}); cmpChips(key);
    };
    mr.start();
  }catch(e){ toast('Microphone access denied. Please allow the mic permission.',true); }
}
function blobToB64(blob){
  return new Promise((res,rej)=>{
    const r=new FileReader();
    const t=setTimeout(()=>rej(new Error('File read timed out.')),15000);
    r.onload=()=>{ clearTimeout(t); res((r.result||'').toString().split(',')[1]||''); };
    r.onerror=()=>{ clearTimeout(t); rej(new Error('This file could not be read. If you dragged it from a website, save it to your device first and then upload.')); };
    try{ r.readAsDataURL(blob); }catch(e){ clearTimeout(t); rej(new Error('This file could not be read.')); }
  });
}
async function playDoubtVoice(btn,url){
  try{
    btn.disabled=true;
    const r=await fetch(API+url,{headers:{Authorization:'Bearer '+TOKEN}});
    if(!r.ok) throw new Error('Voice note not found');
    const src=URL.createObjectURL(await r.blob());
    btn.outerHTML=`<audio controls autoplay src="${src}" style="height:38px;max-width:240px;vertical-align:middle"></audio>`;
  }catch(e){ btn.disabled=false; toast(e.message,true); }
}
async function viewDoubtFile(role,id,mime,name){
  try{
    const r=await fetch(API+'/api/'+role+'/doubt/'+id+'/image',{headers:{Authorization:'Bearer '+TOKEN}});
    if(!r.ok) throw new Error('Attachment not found');
    const blob=await r.blob(); const url=URL.createObjectURL(blob);
    if((mime||'').startsWith('image/')) openImageViewerSrc(url,_dlName(name,blob.type));
    else window.open(url,'_blank');
  }catch(e){ toast(e.message,true); }
}
/* v69 — doubt image attachments: fullscreen viewer + download + inline thumbs */
function _dlName(name,mime){
  let nm=(name||'').trim()||'attachment';
  if(!/\.[a-z0-9]{2,5}$/i.test(nm)){ const ext=((mime||'image/jpeg').split('/')[1]||'jpeg').split('+')[0]; nm+='.'+ext; }
  return nm;
}
function doubtAttachHtml(role,id,mime,name,isAns){
  if((mime||'').startsWith('image/')){
    const url='/api/'+role+'/doubt/'+id+(isAns?'/answer-file':'/image');
    return `<img class="doubt-thumb" data-url="${url}" data-name="${esc(name||'')}" alt="attachment photo" onclick="openImageViewer(this)">`;
  }
  return `<button class="btn btn-ghost btn-sm" onclick="${isAns?'viewAnswerFile':'viewDoubtFile'}('${role}',${id},'${esc(mime||'')}')">${ic('folder')} ${esc(name||'Attachment')}</button>`;
}
function loadDoubtThumbs(root){
  (root||document).querySelectorAll('img.doubt-thumb[data-url]:not(.loaded)').forEach(im=>{
    im.classList.add('loaded');
    fetch(API+im.getAttribute('data-url'),{headers:{Authorization:'Bearer '+TOKEN}})
      .then(r=>{ if(!r.ok) throw 0; return r.blob(); })
      .then(b=>{ im._blobUrl=URL.createObjectURL(b); im._dlName=_dlName(im.getAttribute('data-name'),b.type); im.src=im._blobUrl; })
      .catch(()=>{ const s=document.createElement('span'); s.className='doubt-thumb-fail'; s.textContent='Attachment could not be loaded'; im.replaceWith(s); });
  });
}
function openImageViewer(img){
  const src=img._blobUrl||'';
  if(!src){ toast('Photo is still loading — ek second rukiye.',true); return; }
  openImageViewerSrc(src,img._dlName||_dlName(img.getAttribute('data-name')));
}
function openImageViewerSrc(src,name){
  let ov=document.getElementById('imgviewer');
  if(!ov){
    ov=document.createElement('div'); ov.id='imgviewer'; ov.className='imgviewer';
    ov.innerHTML=`<div class="iv-bar"><span class="iv-name" id="iv-name"></span><span style="display:flex;gap:8px;flex:none"><a class="iv-btn" id="iv-dl" href="#" download>&#8681; Download</a><button class="iv-btn" onclick="closeImageViewer()">&#10005; Close</button></span></div><img id="iv-img" alt="attachment full view">`;
    document.body.appendChild(ov);
    ov.addEventListener('click',e=>{ if(e.target===ov) closeImageViewer(); });
    document.addEventListener('keydown',e=>{ if(e.key==='Escape') closeImageViewer(); });
  }
  document.getElementById('iv-img').src=src;
  document.getElementById('iv-name').textContent=name||'attachment';
  const dl=document.getElementById('iv-dl'); dl.href=src; dl.setAttribute('download',name||'attachment');
  ov.classList.add('on'); document.body.style.overflow='hidden';
}
function closeImageViewer(){
  const ov=document.getElementById('imgviewer');
  if(ov) ov.classList.remove('on');
  document.body.style.overflow='';
}
