let _matEntries=[], _matActiveSub='';
async function downloadMaterial(role,id,name){
  try{
    const r=await fetch(API+'/api/'+role+'/material/'+id+'/download',{headers:{Authorization:'Bearer '+TOKEN}});
    if(!r.ok) throw new Error('Download fail');
    const blob=await r.blob();
    if(!blob||!blob.size) throw new Error('empty');
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a'); a.href=url; a.download=name||'file.pdf'; document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),2000);
  }catch(e){
    // fallback: naye tab me kholo (?t= se auth)
    try{ window.open(API+'/api/'+role+'/material/'+id+'/download?t='+encodeURIComponent(TOKEN),'_blank','noopener'); }catch(e2){ toast('Download error',true); }
  }
}
function complianceCard(comp){
  const s=comp.score, col=comp.band==='green'?'#059669':comp.band==='yellow'?'#d97706':'#dc2626';
  const r=52, c=2*Math.PI*r, off=c*(1-s/100), b=comp.breakdown;
  const cbar=(label,x)=>`<div style="display:flex;justify-content:space-between;margin-bottom:3px"><span>${label}</span><span style="font-weight:700">${x.got}/${x.weight}</span></div><div class="eff-bar" style="margin-bottom:9px"><div class="eff-fill" style="width:${x.pct}%;background:${col}"></div></div>`;
  return `<div class="card gauge-card"><div class="card-body" style="text-align:center">
    <div style="font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text-muted);margin-bottom:6px">Compliance Score</div>
    <svg width="132" height="132" viewBox="0 0 140 140"><g transform="rotate(-90 70 70)"><circle cx="70" cy="70" r="${r}" fill="none" stroke="var(--border)" stroke-width="12"/><circle cx="70" cy="70" r="${r}" fill="none" stroke="${col}" stroke-width="12" stroke-linecap="round" stroke-dasharray="${c.toFixed(1)}" stroke-dashoffset="${off.toFixed(1)}"/></g><text x="70" y="64" text-anchor="middle" style="font-size:30px;font-weight:800;fill:var(--text)">${s}</text><text x="70" y="86" text-anchor="middle" style="font-size:11px;fill:var(--text-muted)">out of 100</text></svg>
    <div style="margin-top:6px;font-size:.76rem;text-align:left">${cbar('Class Completion',b.class_completion)}${cbar('DPP Upload',b.dpp_upload)}${cbar('Study Material',b.study_material)}${cbar('Test Creation',b.test_creation)}</div>
  </div></div>`;
}
function accountabilityBlock(comp,today){
  const pendingDpp=today.filter(c=>!c.dpp).length;
  const pendingNotes=today.filter(c=>!c.notes).length;
  const pendingTests=Math.max(0,(comp.stats.subject_count||0)-comp.stats.test_count);
  return `<div class="acct-row">${complianceCard(comp)}<div class="stats-grid" style="flex:1;margin:0">${statCard("Today's Classes",comp.stats.classes_today,'calendar','indigo',"navTo('teacher-app','today')")}${statCard('Completed Today',comp.stats.completed_today,'check','green')}${statCard('Pending DPP',pendingDpp,'clipboard','amber',"navTo('teacher-app','dpp')")}${statCard('Pending Notes',pendingNotes,'book','purple',"navTo('teacher-app','material')")}${statCard('Pending Tests',pendingTests,'edit','teal',"navTo('teacher-app','tests')")}</div></div>`;
}
function statusTag(s){ const m={Completed:'tag-done',Pending:'tag-pending',Missed:'tag-missed',Upcoming:'tag-upcoming',Live:'tag-live'}; return `<span class="tag ${m[s]||'tag-low'}">${s}</span>`; }
function tClassRow(c){
  const topic=c.completed?(c.topic_covered||c.chapter||'—'):(c.chapter||'—');
  const btn=c.completed?'<span style="color:var(--success);font-size:.8rem;font-weight:600">Done ✓</span>':`<button class="btn btn-success btn-sm" onclick="openClassReport(${c.id})">Mark Completed</button>`;
  return `<tr><td><strong>${esc(c.subject)}</strong></td><td>${esc(c.class_name||'—')}</td><td>${esc(c.time||'—')}</td><td>${esc(topic)}</td><td>${c.completed?'<span class="tag tag-done">Completed</span>':statusTag(c.live_status)}</td><td style="text-align:right">${btn}</td></tr>`;
}
async function _renderTodayClasses(targetId){
  const el=document.getElementById(targetId||'t-today-inner');
  try{
    const [all,comp]=await Promise.all([api('/api/teacher/my-classes'),api('/api/teacher/compliance')]);
    window._tClasses=all; const st=comp.stats;
    const todayStr=new Date().toLocaleDateString('en-CA');
    const cls=all.filter(c=>c.date===todayStr);
    // cards ab list ke SAME data se (pehle compliance.stats se alag count aata tha)
    const _tN=cls.length, _cN=cls.filter(c=>c.completed).length, _pN=cls.filter(c=>!c.completed).length;
    const _mN=all.filter(c=>!c.completed && c.date && c.date<todayStr).length;
    const cards=`<div class="stats-grid">${statCard("Today's Classes",_tN,'calendar','indigo',"navTo('teacher-app','today')")}${statCard('Completed',_cN,'check','green',"navTo('teacher-app','today')")}${statCard('Pending',_pN,'clipboard','amber',"navTo('teacher-app','today')")}${statCard('Missed',_mN,'help','red',"ttSwitchTab('plan')",_mN>0)}</div>`;
    const rows=cls.length?cls.map(tClassRow).join(''):`<tr><td colspan="6" style="text-align:center;color:var(--text-muted)">No classes scheduled today.</td></tr>`;
    const doneAll=all.filter(c=>c.completed).reverse();
    const doneRows=doneAll.map(c=>`<div class="qb-card"><div class="qb-info"><div class="qb-title">${esc(c.subject)} — ${esc(c.topic_covered||c.chapter||'')}</div><div class="qb-meta"><span class="tag tag-done">Completed</span><span>${esc(c.class_name||'')}</span><span>\u00b7 ${esc(c.date||'')}</span>${c.homework?'<span>\u00b7 HW: '+esc(c.homework)+'</span>':''}${c.dpp_given?'<span>\u00b7 DPP</span>':''}</div></div></div>`).join('');
    const doneCard=`<div class="card"><div class="card-header" style="cursor:pointer;display:flex;align-items:center;justify-content:space-between" onclick="_tToggleDone()"><h3 style="margin:0">Recently Completed (${doneAll.length})</h3><span id="t-done-chev" style="opacity:.6">\u25be</span></div><div class="card-body" id="t-done-body">${doneAll.length?`<div class="mat-scroll" style="max-height:330px;overflow:auto">${doneRows}</div>`:'<div class="empty-state"><p>No completed reports yet.</p></div>'}</div></div>`;
    el.innerHTML=`${cards}<div class="card"><div class="card-header"><h3>Today's Classes</h3></div><div class="card-body"><div class="table-wrap"><table><thead><tr><th>Subject</th><th>Batch</th><th>Time</th><th>Topic</th><th>Status</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></div></div>${doneCard}`;
  }catch(e){ el.innerHTML=errHtml(e); }
}
function _tToggleDone(){ var b=document.getElementById('t-done-body'), c=document.getElementById('t-done-chev'); if(b){ var h=b.style.display==='none'; b.style.display=h?'':'none'; if(c) c.textContent=h?'\u25be':'\u25b8'; } }
async function loadTCompletion(){
  const el=document.getElementById('t-completion-content');
  try{
    const cls=await api('/api/teacher/my-classes'); window._tClasses=cls;
    const pending=cls.filter(c=>!c.completed), done=cls.filter(c=>c.completed).reverse();
    const pendList=pending.length?pending.map(c=>`<div class="qb-card"><div class="qb-info"><div class="qb-title">${esc(c.subject)} — ${esc(c.chapter||'')}</div><div class="qb-meta">${statusTag(c.live_status)}<span>${esc(c.class_name||'')}</span><span>· ${esc(c.date||'')}</span></div></div><div class="qb-act"><button class="btn btn-success btn-sm" onclick="openClassReport(${c.id})">Submit Report</button></div></div>`).join(''):'<div class="empty-state"><p>No pending classes. All caught up!</p></div>';
    const doneList=done.length?done.slice(0,15).map(c=>`<div class="qb-card"><div class="qb-info"><div class="qb-title">${esc(c.subject)} — ${esc(c.topic_covered||c.chapter||'')}</div><div class="qb-meta"><span class="tag tag-done">Completed</span><span>${esc(c.class_name||'')}</span><span>· ${esc(c.date||'')}</span>${c.homework?'<span>· HW: '+esc(c.homework)+'</span>':''}${c.dpp_given?'<span>· DPP ✓</span>':''}</div></div></div>`).join(''):'<div class="empty-state"><p>No completed reports yet.</p></div>';
    el.innerHTML=`<div class="alert alert-info">Submit a class completion report. The class status becomes <strong>Completed</strong> and counts toward your compliance score.</div><div class="card"><div class="card-header"><h3>Pending Classes (${pending.length})</h3></div><div class="card-body">${pendList}</div></div><div class="card"><div class="card-header"><h3>Recently Completed</h3></div><div class="card-body">${doneList}</div></div>`;
  }catch(e){ el.innerHTML=errHtml(e); }
}
function openClassReport(id){
  const c=((window._tClasses||[]).concat(typeof _ttEntries!=='undefined'?_ttEntries:[])).find(x=>x.id===id)||{};
  // One form = class report + lecture report (class notes only — v98: no DPP, no verification question).
  _lecFiles={pdf:null};
  const sched=esc(c.time||c.time_text||'');
  showModal('Class Report',
    `<div class="alert alert-info"><strong>${esc(c.subject||'')}</strong>${c.chapter?' \u00b7 '+esc(c.chapter):''}${c.part?' \u00b7 '+esc(c.part):''}${sched?` \u00b7 Scheduled <strong>${sched}</strong>`:''}</div>
     <div class="cr-sec">1. Class Details</div>
     <div class="ex-grid2">
       <div><label class="ex-lbl">Topic Covered</label><input class="form-control" id="cr-topic" value="${esc(c.topic_covered||c.chapter||'')}"></div>
       <div><label class="ex-lbl">Homework Given</label><input class="form-control" id="cr-hw" placeholder="e.g. Exercise 5.1" value="${esc(c.homework||'')}"></div>
     </div>
     <div class="ex-grid2">
       <div><label class="ex-lbl">Actual Start Time</label><input class="form-control" id="cr-start" placeholder="e.g. 6:35 pm" value="${esc(c.start_time||c.time||'')}" oninput="crDelayHint()"></div>
       <div><label class="ex-lbl">End Time</label><input class="form-control" id="cr-end" placeholder="e.g. 7:30 pm" value="${esc(c.end_time||'')}"></div>
     </div>
     <input type="hidden" id="cr-sched" value="${sched}">
     <div id="cr-delay" class="cr-delay"></div>
     <label class="ex-lbl">Remarks (optional)</label>
     <textarea class="form-control" id="cr-remarks" rows="2" placeholder="Anything the admin should know">${esc(c.remarks||'')}</textarea>

     <div class="cr-sec">2. Lecture Report <span class="cr-sec-sub">students see this in their Lectures feed</span></div>
     <div><label class="ex-lbl">Class Notes <span class="req">*</span></label><div class="dz" id="dz-lec-pdf" onclick="document.getElementById('lec-pdf').click()"><span class="dz-ic">${ic('upload')}</span><span class="dz-t" id="lec-pdf-name">Drag &amp; drop the class notes PDF here</span><span class="dz-s">or click to browse \u00b7 PDF only \u2014 large files auto-compress</span></div><input type="file" id="lec-pdf" accept="application/pdf" style="display:none" onchange="_lecPickFile(this,'pdf')"></div>
     <div id="cr-status"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-success" id="cr-btn" onclick="submitClassReport(${id})">Submit &amp; Mark Done</button>`);
  crDelayHint(); _dzInit('lec-pdf');
}
function crDelayHint(){
  const box=document.getElementById('cr-delay'); if(!box) return;
  const d=_calcDelay(val('cr-sched'), val('cr-start'));
  if(d===null){ box.className='cr-delay'; box.innerHTML=''; return; }
  const band=d<=5?'ontime':(d<=15?'minor':'late');
  const txt=d<=0?`Started on time${d<0?` (${-d} min early)`:''}`:(d<=5?`Started ${d} min after the slot \u2014 on time`:`Started ${d} min late`);
  box.className='cr-delay on '+band;
  box.innerHTML=`<span class="cr-dot"></span>${esc(txt)}`;
}
function _calcDelay(sched,actual){
  const a=_timeKey(String(sched||'').split(/[-\u2013\u2014]/)[0]), b=_timeKey(actual);
  if(a===9999||b===9999) return null;
  return b-a;
}
async function submitClassReport(id){
  // required uploads (v98: no verification question, no DPP here)
  if(!_lecFiles.pdf){ toast('Notes PDF is required.',true); return; }
  const c=((window._tClasses||[]).concat(typeof _ttEntries!=='undefined'?_ttEntries:[])).find(x=>x.id===id)||{};
  const btn=document.getElementById('cr-btn'); btn.disabled=true; btn.textContent='Submitting...';
  try{
    // 1) class report -> marks the class Done (delay is derived from these times)
    await api('/api/teacher/class/'+id+'/complete','POST',{topic_covered:val('cr-topic'),start_time:val('cr-start'),end_time:val('cr-end'),homework:val('cr-hw'),dpp_given:false,remarks:val('cr-remarks')});
    // 2) lecture report -> summary + class notes, auto-linked to this class
    let pdf_b64=null;
    if(_lecFiles.pdf) pdf_b64=await _fileB64(_lecFiles.pdf);
    await _xhrJson('/api/teacher/lecture',{
      subject:c.subject, chapter:c.chapter||null, part:c.part||null,
      title:(c.chapter||'Lecture')+(c.part?(' \u2013 '+c.part):''),
      lecture_date:c.date||null, timetable_entry_id:id,
      homework:val('cr-hw')||null,
      pdf_b64, pdf_filename:_lecFiles.pdf?_lecFiles.pdf.name:null,
      questions:[]},pc=>{ btn.textContent='Uploading… '+pc+'%'; });
    toast('Class marked Done. Students can now see this report.');
    closeModal();
    const active=document.querySelector('#teacher-app .page.active');
    if(active&&active.id==='t-page-timetable') loadTTimetable();
    else loadTDashboard();
  }catch(e){ document.getElementById('cr-status').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`; btn.disabled=false; btn.textContent='Submit & Mark Done'; }
}
