async function loadSTeachers(){
  const el=document.getElementById('s-teachers-content');
  try{
    const ts=await api('/api/student/my-teachers');
    if(ts.length===0){ el.innerHTML=`<div class="card"><div class="card-body"><div class="empty-state"><div class="empty-icon"></div><p>No teacher assigned yet. Please select your subjects.</p></div></div></div>`; return; }
    let html=`<div class="alert alert-info">Teachers for your subjects. If you have a doubt, ask in the Doubts section.</div><div class="kyt-grid">`;
    ts.forEach(t=>{
      const pid=`kyt-${t.teacher_id}-${esc(t.subject).replace(/[^a-z0-9]/gi,'')}`;
      const full=`${esc(t.name)} ${esc(t.suffix||'')} \u00b7 ${esc(t.subject)}`;
      const ph=t.has_photo
        ? `<div class="kyt-photo zoomable" id="${pid}" onclick="viewKytPhoto('${pid}','${full.replace(/'/g,"")}')" title="Tap to view"></div>`
        : `<div class="kyt-photo">${esc(initials(t.name))}</div>`;
      html+=`<div class="kyt-card">${ph}<div class="kyt-name">${esc(t.name)} ${esc(t.suffix)}</div><div class="kyt-sub">${esc(t.subject)}</div></div>`;
    });
    html+=`</div>`;
    el.innerHTML=html;
    // load photos
    ts.filter(t=>t.has_photo).forEach(async t=>{
      try{ const r=await fetch(API+`/api/student/teacher/${t.teacher_id}/photo`,{headers:{Authorization:'Bearer '+TOKEN}});
        if(r.ok){ const u=URL.createObjectURL(await r.blob()); const key=`kyt-${t.teacher_id}-${t.subject.replace(/[^a-z0-9]/gi,'')}`;
          window._photoUrls=window._photoUrls||{}; window._photoUrls[key]=u;
          const d=document.getElementById(key); if(d){ d.style.backgroundImage=`url(${u})`; d.textContent=''; } } }catch(e){}
    });
  }catch(e){ el.innerHTML=errHtml(e); }
}
