let _slistRole='teacher', _slistSubject='';
let _slistCls='', _slistCode='';
let _slistSess='', _slistMed='';
async function openStudentsListModal(role,subject,cls,code){
  _slistRole=role; _slistSubject=subject||''; _slistCls=cls||''; _slistCode=code||'';
  _slistSess=''; _slistMed='';
  const ttl=(subject?subject+(_slistCode?' ('+_slistCode+')':'')+' — ':'')+(_slistCls&&_slistCls!=='?'?'Class '+_slistCls+' ':'')+'Students';
  showModal(ttl,
    `<div class="slist-search"><input class="form-control" id="slist-q" placeholder="Search by name or phone..." oninput="renderSlist()"></div>
     <div style="display:flex;gap:8px;margin-bottom:8px;flex-wrap:wrap">
       <select class="form-control" id="slist-sess" style="flex:1;min-width:140px" onchange="_slistSess=this.value;renderSlist()"><option value="">All Sessions</option></select>
       <select class="form-control" id="slist-med" style="flex:0 0 130px" onchange="_slistMed=this.value;renderSlist()"><option value="">All Mediums</option><option>Hindi</option><option>English</option></select>
     </div>
     <div class="slist-hint">Tap any student to see complete details.</div><div id="slist-wrap"><div class="spinner"></div></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
  await fetchSlist();
}
let _slistData=[];
async function fetchSlist(){
  const base=_slistRole==='teacher'?'/api/teacher/my-students-list':'/api/admin/students-list';
  const prm=[];
  if(_slistSubject) prm.push('subject='+encodeURIComponent(_slistSubject));
  if(_slistCls) prm.push('cls='+encodeURIComponent(_slistCls));
  const u=base+(prm.length?'?'+prm.join('&'):'');
  try{
    const r=await api(u); _slistData=r.students||[]; _slistData.forEach((x,i)=>x._i=i);
    // Session dropdown data se banao (sirf jo sessions actually hain)
    const ss=document.getElementById('slist-sess');
    if(ss){ const sess=[...new Set(_slistData.map(x=>x.exam_session).filter(Boolean))];
      ss.innerHTML='<option value="">All Sessions</option>'+sess.map(x=>`<option value="${esc(x)}">${esc(_sylSessName(x))}</option>`).join(''); }
    renderSlist();
  }
  catch(e){ document.getElementById('slist-wrap').innerHTML=errHtml(e); }
}
function _slistDetail(i){
  const s=_slistData[i]; if(!s) return;
  const subs=(s.all_subjects||s.subjects||[]).map(x=>`<span class="chip">${esc(x)}</span>`).join('');
  const row=(l,v)=>(v!==undefined&&v!==null&&v!=='')?`<div class="sdet-row"><span>${l}</span><b>${esc(String(v))}</b></div>`:'';
  const av=s.has_photo?`<div class="sdet-av" id="sdet-av"></div>`:`<div class="sdet-av">${esc(initials(s.name||'S'))}</div>`;
  showModal('Student Details',
    `<div class="sdet-head">${av}<div><div class="sdet-name">${esc(s.name||'Student')}</div><div class="sdet-meta">${s.class?'Class '+esc(s.class):''}${s.batch?' · '+esc(s.batch):''}</div></div></div>
     <div class="sdet-grid">${row('Phone',s.phone)}${row('User ID',s.user_id)}${row('Email',s.email)}${row('Medium',s.medium)}${row('Batch',s.batch)}${row('Section',s.class_name)}${row('NIOS Ref',s.nios_ref)}${row('Exam Session',s.exam_session)}${row('Stream',s.exam_stream)}${row('Goal',s.goal)}${row('Verified',s.is_verified?'Yes':'')}${row('Last Active',s.last_seen)}</div>
     <div class="sdet-subs"><div class="sdet-subs-lbl">SUBJECTS</div><div class="slist-chips">${subs||'<span style="color:var(--text-muted);font-size:.8rem">—</span>'}</div></div>`,
    `<button class="btn btn-ghost" onclick="openStudentsListModal(_slistRole,_slistSubject,_slistCls,_slistCode)">&larr; Back to List</button><button class="btn btn-primary btn-sm" onclick="closeModal()">Done</button>`);
  if(s.has_photo){ const pb=_slistRole==='teacher'?'/api/teacher/student/':'/api/admin/student/';
    fetch(API+pb+s.id+'/photo',{headers:{Authorization:'Bearer '+TOKEN}}).then(r=>r.ok?r.blob():null).then(bl=>{ if(!bl) return; const d=document.getElementById('sdet-av'); if(d){ d.style.backgroundImage=`url(${URL.createObjectURL(bl)})`; d.textContent=''; } }).catch(()=>{});
  }
}
function renderSlist(){
  const q=(val('slist-q')||'').toLowerCase();
  const wrap=document.getElementById('slist-wrap'); if(!wrap) return;
  let rows=_slistData.filter(s=>!q || (s.name||'').toLowerCase().includes(q) || (s.phone||'').includes(q));
  if(_slistSess) rows=rows.filter(s=>(s.exam_session||'')===_slistSess);
  if(_slistMed) rows=rows.filter(s=>(s.medium||'')===_slistMed);
  const hint=document.querySelector('.slist-hint');
  if(hint) hint.textContent=`${rows.length} student${rows.length===1?'':'s'}${(_slistSess||_slistMed)?' (filtered)':''} — tap for complete details.`;
  if(rows.length===0){ wrap.innerHTML=`<div class="empty-state"><p>No students found.</p></div>`; return; }
  wrap.innerHTML=rows.map(s=>{
    const chips=(s.subjects||[]).map(x=>`<span class="chip">${esc(x)}</span>`).join('');
    const avId=`sav-${s.id}`;
    const av=s.has_photo?`<div class="slist-av" id="${avId}"></div>`:`<div class="slist-av">${esc(initials(s.name||'S'))}</div>`;
    return `<div class="slist-row clickable" onclick="_slistDetail(${s._i})" title="View complete details">${av}<div class="slist-info"><div class="slist-name">${esc(s.name||'Student')}</div><div class="slist-meta">${esc(s.phone||'—')}${s.class?' · Class '+esc(s.class):''}</div><div class="slist-chips">${chips}</div></div><span class="slist-go">&rsaquo;</span></div>`;
  }).join('');
  // load photos
  const photoBase=_slistRole==='teacher'?'/api/teacher/student/':'/api/admin/student/';
  rows.filter(s=>s.has_photo).forEach(async s=>{
    try{ const r=await fetch(API+photoBase+s.id+'/photo',{headers:{Authorization:'Bearer '+TOKEN}});
      if(r.ok){ const u=URL.createObjectURL(await r.blob()); const d=document.getElementById('sav-'+s.id); if(d){ d.style.backgroundImage=`url(${u})`; d.textContent=''; } } }catch(e){}
  });
}

