// ===== TEACHER: CHANGE SLOT (subject time — aage ki saari classes shift) =====
function openSlotChange(){
  const list=_ttEntries||[];
  if(!list.length){ toast('No timetable entries found.',true); return; }
  const subs=[...new Set(list.map(x=>x.subject).filter(Boolean))].sort();
  const subOpts=subs.map(s=>{
    const times=[...new Set(list.filter(e=>e.subject===s&&e.time).map(e=>e.time))].join(', ');
    return `<option value="${esc(s)}">${esc(s)}${times?' - currently '+esc(times):''}</option>`;
  }).join('');
  showModal('Change Class Slot',
 `<div class="alert alert-info">All upcoming classes of the selected subject (from today onwards) will move to the new time. Completed and past classes are not touched. Students of this subject and the admin get a notification automatically.</div>
  <div class="form-group"><label>Subject</label><select class="form-control" id="cs-sub">${subOpts}</select></div>
  <div class="form-group"><label>New Time</label><input class="form-control" id="cs-time" placeholder="e.g. 9:30 AM" autocomplete="off"></div>`,
 `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" id="cs-btn" onclick="submitSlotChange()">Change Slot</button>`);
}
async function submitSlotChange(){
  const sub=val('cs-sub'), t=(val('cs-time')||'').trim();
  if(!/^\d{1,2}([:.]\d{2})?\s*(am|pm)$/i.test(t)){ toast('Please enter time like 9:30 AM',true); return; }
  const btn=document.getElementById('cs-btn'); btn.disabled=true; btn.textContent='Updating...';
  try{
    const r=await api('/api/teacher/change-slot','POST',{subject:sub,new_time:t.replace('.',':').toUpperCase()});
    closeModal(); toast(r.updated+' upcoming classes moved to '+r.new_time+'. Students have been notified.');
    loadTTimetable();
  }catch(e){ toast(e.message,true); btn.disabled=false; btn.textContent='Change Slot'; }
}
