let _ttWorkbook=null;
async function ttPickSheet(){
  const fi=document.getElementById('tt-excel-file');
  if(!fi.files.length) return;
  try{
 const data=await fi.files[0].arrayBuffer();
 _ttWorkbook=XLSX.read(data,{type:'array',cellDates:true});
 const sel=document.getElementById('ttx-sheet');
 sel.innerHTML=_ttWorkbook.SheetNames.map(n=>`<option>${esc(n)}</option>`).join('');
 document.getElementById('ttx-sheet-wrap').style.display=_ttWorkbook.SheetNames.length>1?'block':'none';
  }catch(e){ toast('File padhne mein error: '+e.message,true); }
}
// Parse one topic into {chapter, part} using carry-forward chapter tracking
function parseTopic(topic, state){
  const t=String(topic).trim();
  const m=t.match(/\(part[-\s]?(\d+)\)/i);
  if(m){
 const pnum=m[1];
 let name=t.replace(/chapter\s*\d+\s*[-–]\s*/i,'').replace(/\(part[-\s]?\d+\)/i,'').replace(/\s{2,}/g,' ').trim().replace(/^[-–+\s]+|[-–+\s]+$/g,'');
 if(/chapter\s*\d+/i.test(t)){
 let chap=t.replace(/\(part[-\s]?\d+\)/i,'').replace(/\s{2,}/g,' ').trim().replace(/^[-–+\s]+|[-–+\s]+$/g,'');
 state.chapter=chap;
 }
 const chapter=state.chapter||name;
 const part='Part '+pnum+(name?' - '+name:'');
 return {chapter,part};
  }
  return {chapter:t, part:null}; // standalone (Doubt/Test/etc) — don't change current chapter
}
function fmtDateCell(d){
  if(!d) return '';
  if(d instanceof Date && !isNaN(d)){
 return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  }
  return fmtDate(d);
}
async function processTTExcel(){
  const subject=val('ttx-subject'); const cls=val('ttx-class');
  if(!subject){ toast('Please enter a subject.',true); return; }
  const fi=document.getElementById('tt-excel-file');
  if(!fi.files.length){ toast('Please select a file.',true); return; }
  const btn=document.getElementById('tt-excel-btn'); btn.disabled=true; btn.textContent='Processing...';
  const status=document.getElementById('tt-excel-status');
  try{
 if(!_ttWorkbook){ const data=await fi.files[0].arrayBuffer(); _ttWorkbook=XLSX.read(data,{type:'array',cellDates:true}); }
 const sheetName=val('ttx-sheet')||_ttWorkbook.SheetNames[0];
 const ws=_ttWorkbook.Sheets[sheetName];
 const grid=XLSX.utils.sheet_to_json(ws,{header:1,raw:true});
 // find header row (contains 'date' and 'topics')
 let hdr=-1, cols={};
 for(let i=0;i<grid.length;i++){
 const cells=(grid[i]||[]).map(c=>String(c==null?'':c).trim().toLowerCase());
 if(cells.includes('date')&&cells.includes('topics')){ hdr=i; cells.forEach((c,j)=>{if(c)cols[c]=j;}); break; }
 }
 if(hdr<0){ toast('Header row not found (Date / Topics columns are required).',true); btn.disabled=false; btn.textContent='Upload'; return; }
 const dCol=cols['date'], dayCol=cols['days']!=null?cols['days']:cols['day'], tCol=cols['topics'];
 const state={chapter:''}; let ok=0, fail=0;
 for(let i=hdr+1;i<grid.length;i++){
 const row=grid[i]||[]; const topic=row[tCol];
 if(!topic||!String(topic).trim()) continue;
 const {chapter,part}=parseTopic(topic,state);
 const body={subject,class_name:cls,chapter,part,entry_date:fmtDateCell(row[dCol]),day:dayCol!=null?String(row[dayCol]||'').trim():''};
 try{ await api('/api/teacher/timetable-entry','POST',body); ok++; }catch(e){ fail++; }
 if(i%5===0) status.innerHTML=`<div class="alert alert-info">Processing...  ${ok} |  ${fail}</div>`;
 }
 status.innerHTML=`<div class="alert alert-success"> ${ok} entries added!${fail?`  ${fail} skip`:''}</div>`;
 toast(`${ok} entries added! `); loadTTimetable();
  }catch(e){ toast('Excel error: '+e.message,true); }
  btn.disabled=false; btn.textContent='Upload';
}
function fmtDate(d){
  if(!d) return '';
  d=String(d).trim();
  // try to normalize dd/mm/yyyy or dd-mm-yyyy to yyyy-mm-dd
  let m=d.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
  if(m) return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;
  m=d.match(/^(\d{4})[\/\-](\d{1,2})[\/\-](\d{1,2})$/);
  if(m) return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;
  return d;
}
