async function saveMarks(sid){
  const obt=val('mk-obt-'+sid), mx=val('mk-max-'+sid)||'20';
  if(obt===''){ toast('Please enter the obtained marks.',true); return; }
  if(Number(obt)>Number(mx)){ toast('Obtained marks cannot exceed the maximum.',true); return; }
  const marks=obt+'/'+mx;
  try{ await api(`/api/teacher/submission/${sid}/marks`,'POST',{marks}); toast('Marks saved. The student has been notified.'); }catch(e){ toast(e.message,true); }
}

let _matAnalytics=null;
async function _loadMatAnalytics(force){
  if(_matAnalytics&&!force) return _matAnalytics;
  try{ _matAnalytics=await api('/api/teacher/material-analytics'); }catch(e){ _matAnalytics=[]; }
  return _matAnalytics;
}
function _mStat(id){ return (_matAnalytics||[]).find(x=>x.id===id)||{students_viewed:0,downloads:0,approval_status:'approved'}; }
function approvalTag(s){ const cls={approved:'tag-done',pending:'tag-pending',rejected:'tag-missed'}, lbl={approved:'Approved',pending:'Pending Approval',rejected:'Rejected'}; return `<span class="tag ${cls[s]||'tag-low'}" style="font-size:.6rem">${lbl[s]||s}</span>`; }

// ============================================================
//  UNIFIED UPLOAD HUB — the single upload entry point.
//  Replaces the four old duplicate modals (Academic Upload Center,
//  Study-Material upload, Other-Material upload, Direct upload).
//  All of them posted to the same /api/teacher/material endpoint.
// ============================================================
const UPLOAD_TYPES={
  'Class Notes':      {mt:'notes'},
  // DPP yahan se HATA DIYA — ab DPP ka apna section hai (DPP packs wahi manage hote hain)
  'Test Paper':       {mt:'test'},
  'Assignment':       {mt:'other', cat:'Assignment'},
  'Question Bank':    {mt:'other', cat:'Question Bank'},
  'Solved PYQs':      {mt:'other', cat:'PYQ'},
  'Practical File':   {mt:'other', cat:'Practical File'},
  'Revision Notes':   {mt:'other', cat:'Revision Notes'},
  'Other (custom)':   {mt:'other', cat:''}
};
let _uhMap={};   // subject -> [chapters]

async function openUploadHub(prefill){
  prefill=prefill||{};
  try{
    const es=await api('/api/teacher/my-timetable');
    _uhMap={}; window._uhClsMap={};
    es.forEach(e=>{ if(e.type!=='event'&&e.chapter){ (_uhMap[e.subject]=_uhMap[e.subject]||[]); if(!_uhMap[e.subject].includes(e.chapter)) _uhMap[e.subject].push(e.chapter); }
      const _cd=((String(e.class_name||'').match(/\d+/)||[''])[0]); if(_cd){ (window._uhClsMap[e.subject]=window._uhClsMap[e.subject]||[]); if(!window._uhClsMap[e.subject].includes(_cd)) window._uhClsMap[e.subject].push(_cd); } });
  }catch(e){ _uhMap={}; window._uhClsMap={}; }
  let subs=Object.keys(_uhMap);
  if(!subs.length&&prefill.subject) subs=[prefill.subject];
  if(!subs.length) subs=['General'];
  const preLabel=prefill.typeLabel||Object.keys(UPLOAD_TYPES).find(k=>UPLOAD_TYPES[k].mt===prefill.type&&!UPLOAD_TYPES[k].cat)||'Class Notes';
  const typeOpts=Object.keys(UPLOAD_TYPES).map(t=>`<option ${t===preLabel?'selected':''}>${t}</option>`).join('');
  const subOpts=subs.map(s=>`<option ${prefill.subject===s?'selected':''}>${esc(s)}</option>`).join('');
  showModal('Upload Material',
    `<div class="alert alert-info">One place for every upload. Students get a bell notification as soon as you publish.</div>
     <div class="ex-grid2">
       <div><label class="ex-lbl">Type</label><select class="form-control" id="uh-type" onchange="uhTypeChange()">${typeOpts}</select></div>
       <div><label class="ex-lbl">Subject</label><select class="form-control" id="uh-sub" onchange="uhFillCh()">${subOpts}</select></div>
     </div>
     <div style="max-width:240px"><label class="ex-lbl">Class</label><select class="form-control" id="uh-cls"><option value="">Auto (from subject)</option><option value="10" ${prefill&&String(prefill.class_name||'').includes('10')?'selected':''}>Class 10</option><option value="12" ${prefill&&String(prefill.class_name||'').includes('12')?'selected':''}>Class 12</option></select></div>
     <div id="uh-cat-wrap" style="display:none"><label class="ex-lbl">Category</label><input class="form-control" id="uh-cat" placeholder="e.g. Formula Sheet / PYQ / Reference"></div>
     <div class="ex-grid2">
       <div><label class="ex-lbl">Chapter</label><input class="form-control" id="uh-ch" list="uh-ch-list" placeholder="Chapter (optional)" value="${esc(prefill.chapter||'')}"><datalist id="uh-ch-list"></datalist></div>
       <div><label class="ex-lbl">Title (optional)</label><input class="form-control" id="uh-title" placeholder="e.g. Chapter 5 Notes"></div>
     </div>
     <div id="uh-dur-wrap" style="display:none"><label class="ex-lbl">Test Duration (minutes)</label><input type="number" class="form-control" id="uh-dur" value="60"></div>
     <label class="ex-lbl">PDF File</label>${fileDropHTML('uh-file','uh-label')}
     <div id="uh-status"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" id="uh-btn" onclick="submitUploadHub()">Upload</button>`);
  uhFillCh(); uhTypeChange();
}
function uhFillCh(){
  const sub=val('uh-sub'); const dl=document.getElementById('uh-ch-list'); if(!dl) return;
  dl.innerHTML=(_uhMap[sub]||[]).map(c=>`<option value="${esc(c)}">`).join('');
  // v123: subject ki timetable sirf ek class ki ho to Class auto-select (dual-class pe teacher chune)
  const cs=document.getElementById('uh-cls');
  if(cs){ const cl=(window._uhClsMap||{})[sub]||[];
    if(cl.length===1) cs.value=cl[0];
    else if(cl.length&&cs.value&&!cl.includes(cs.value)) cs.value=''; }
}
function uhTypeChange(){
  const t=UPLOAD_TYPES[val('uh-type')]||{mt:'notes'};
  const cw=document.getElementById('uh-cat-wrap'), dw=document.getElementById('uh-dur-wrap');
  if(cw){ cw.style.display=(t.mt==='other')?'block':'none'; const ci=document.getElementById('uh-cat'); if(ci&&t.cat) ci.value=t.cat; }
  if(dw) dw.style.display=(t.mt==='test')?'block':'none';
}
async function submitUploadHub(){
  const fi=document.getElementById('uh-file');
  if(!fi.files.length){ toast('Please select a PDF.',true); return; }
  const t=UPLOAD_TYPES[val('uh-type')]||{mt:'notes'};
  if(t.mt==='other'&&!val('uh-cat').trim()){ toast('Please enter a category.',true); return; }
  let f=fi.files[0];
  if(f.size>MAXB||(f.type&&f.type.startsWith('image/'))){ toast('Compressing the file, please wait...'); const r=await smartCompress(f,m=>toast(m)); f=r.file; if(!r.ok){ toast('The file is still too large after compression. Please try a smaller file.',true); return; } }
  const btn=document.getElementById('uh-btn'); btn.disabled=true; btn.textContent='Uploading...';
  const st=document.getElementById('uh-status');
  const fd=new FormData();
  fd.append('file',f); fd.append('subject',val('uh-sub')); fd.append('chapter',val('uh-ch'));
  fd.append('material_type',t.mt); fd.append('title',val('uh-title'));
  fd.append('category',t.mt==='other'?val('uh-cat'):'');
  const _uhClsV=val('uh-cls'); if(_uhClsV) fd.append('class_name','Class '+_uhClsV); // v123: blank -> backend subject ke official class se resolve karega
  if(t.mt==='test') fd.append('duration_min',val('uh-dur')||60);
  try{
    await new Promise((resolve,reject)=>{
      const x=new XMLHttpRequest();
      x.open('POST',API+'/api/teacher/material');
      x.setRequestHeader('Authorization','Bearer '+TOKEN);
      x.upload.onprogress=e=>{ if(e.lengthComputable){ const p=Math.round(e.loaded/e.total*100); btn.textContent='Uploading '+p+'%'; if(st) st.innerHTML=`<div class="ex-prog on"><div class="ex-prog-track"><div class="ex-prog-fill" style="width:${p}%"></div></div></div>`; } };
      x.onload=()=>{ let j=null; try{ j=JSON.parse(x.responseText); }catch{} if(x.status>=200&&x.status<300) resolve(j); else reject(new Error((j&&j.detail)||('Error '+x.status))); };
      x.onerror=()=>reject(new Error('Network error')); x.timeout=180000; x.ontimeout=()=>reject(new Error('Upload timed out'));
      x.send(fd);
    });
    st.innerHTML=`<div class="alert alert-success">Uploaded successfully. Students have been notified.</div>`;
    toast('Uploaded successfully.');
    btn.textContent='Done'; btn.setAttribute('onclick','closeModal()'); btn.disabled=false;
    const act=document.querySelector('#teacher-app .page.active');
    if(act){ if(act.id==='t-page-material') loadTMaterial(); else if(act.id==='t-page-dpp') loadTDpp(); else if(act.id==='t-page-dashboard') loadTDashboard(); }
  }catch(e){ st.innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`; btn.disabled=false; btn.textContent='Upload'; }
}
function matAnalyticsCardHTML(types){
  let a=_matAnalytics||[];
  if(types) a=a.filter(m=>types.includes(m.type));
  if(!a.length) return '<div class="empty-state"><p>No uploads yet. Analytics will appear here once students view or download.</p></div>';
  return a.map(m=>`<div class="qb-card"><div class="qb-info"><div class="qb-title">${esc(m.title)} <span class="tchip">${esc((m.type||'').toUpperCase())}</span></div><div class="qb-meta"><span>${esc(m.subject)}</span><span>· ${esc(m.upload_date||'')}</span>${approvalTag(m.approval_status)}</div></div><div class="qb-act" style="gap:16px;font-size:.82rem;align-items:center">${ic('users')} <span title="Students viewed" style="font-weight:600">${m.students_viewed}</span>${ic('download')} <span title="Downloads" style="font-weight:600">${m.downloads}</span></div></div>`).join('');
}
async function loadTEngagement(){
  const wrap=document.getElementById('t-engagement'); if(!wrap) return;
  try{
    const eng=await api('/api/teacher/student-engagement');
    if(!eng.length){ wrap.innerHTML=''; return; }
    const rows=eng.map(s=>`<tr><td><strong>${esc(s.name)}</strong>${s.class_level?` <span class="chip eng-cls">Class ${esc(s.class_level)}</span>`:''}<div style="font-size:.72rem;color:var(--text-muted)">${esc((s.subjects||[]).join(', '))}</div></td><td>${s.dpp_completed}</td><td>${s.tests_completed}</td><td>${s.material_downloads}</td><td>${esc(s.last_active||'—')}</td></tr>`).join('');
    wrap.innerHTML=`<div class="card"><div class="card-header"><h3>Student Engagement</h3><span class="pager-info">DPP &amp; test completion · material downloads · last active</span></div><div class="card-body"><div class="table-wrap"><table><thead><tr><th>Student</th><th>DPP Done</th><th>Tests Done</th><th>Downloads</th><th>Last Active</th></tr></thead><tbody>${rows}</tbody></table></div></div></div>`;
  }catch(e){ wrap.innerHTML=''; }
}
async function loadTMaterial(){
  const el=document.getElementById('t-material-content');
  softSpin(el);
  try{
    el.innerHTML=`<div class="sm-head" style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap"><div><h2>Classes Material</h2><p style="display:none"> Add anything extra as a custom category.</p></div><button class="btn btn-primary btn-sm" onclick="openUploadHub({typeLabel:'Other (custom)'})">${ic('upload')} Upload Other Material</button></div><div id="t-mat-tree"></div>`;
    _renderMaterialTree('t-mat-tree','/api/teacher/materials-tree','/api/teacher');
  }catch(e){ el.innerHTML=errHtml(e); }
}

// Subject cards -> chapter/part table of every upload, with engagement.
// Used by BOTH the teacher and the admin portal (same renderer, same numbers).
let _mtData=null, _mtSub=null, _mtBase='/api/teacher', _mtLast=null;
async function _renderMaterialTree(wrapId, endpoint, apiBase, keepSub){
  const wrap=document.getElementById(wrapId); if(!wrap) return;
  softSpin(wrap);
  _mtBase=apiBase;
  _mtLast={wrapId:wrapId, endpoint:endpoint, apiBase:apiBase};
  try{
    const d=await api(endpoint);
    _mtData=d.subjects||[];
    if(!_mtData.length){ _mtSub=null; wrap.innerHTML='<div class="card"><div class="card-body"><div class="ws-empty"><div class="big">\ud83d\udcda</div><p>No material uploaded yet</p><small>Class notes appear here as soon as a class report is submitted.</small></div></div></div>'; return; }
    // v114: page pe har fresh entry me pehle subject CARDS; sirf delete-refresh
    // (_mtReload) par khula subject bana rehta hai (wo delete ho gaya ho to cards).
    if(!keepSub||!_mtData.find(s=>s.subject===_mtSub)) _mtSub=null;
    // v130: naye notes/dpp uploads ka NEW blink ab teacher ko bhi (pehle sirf admin).
    const _mtRole=apiBase.indexOf('admin')>=0?'admin':'teacher';
    window._mtNew=_matNewIds(_mtRole, _mtData.flatMap(s=>s.chapters.flatMap(c=>c.items)));
    _matBadge(_mtRole);
    _mtPaint(wrapId);
  }catch(e){ wrap.innerHTML=errHtml(e); }
}
function _mtReload(){ if(_mtLast) _renderMaterialTree(_mtLast.wrapId,_mtLast.endpoint,_mtLast.apiBase,true); }
function deleteMaterial(who,id,name){
  const nm=decodeURIComponent(name||'this file');
  showModal('Delete Material',
   `<div class="alert alert-danger">This permanently removes the file for everyone. Students will no longer see it, and this cannot be undone.</div>
    <div class="form-group"><label>File</label><div class="mt-delname">${esc(nm)}</div></div>`,
   `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-danger" id="mdel-btn" onclick="_doDeleteMaterial('${who}',${id})">Delete Permanently</button>`);
}
async function _doDeleteMaterial(who,id){
  const b=document.getElementById('mdel-btn'); if(b){ b.disabled=true; b.textContent='Deleting...'; }
  try{
    await api('/api/'+who+'/material/'+id,'DELETE');
    closeModal(); toast('Material deleted.');
    _mtReload();
  }catch(e){ toast(e.message,true); if(b){ b.disabled=false; b.textContent='Delete Permanently'; } }
}
function deleteMatCategory(who,cat){
  const sub=_mtData?_mtData.find(x=>x.subject===_mtSub):null; if(!sub) return;
  const label=decodeURIComponent(cat);
  const items=sub.chapters.flatMap(c=>c.items).filter(i=>{
    const k=_MT_CAT[i.type]?_MT_CAT[i.type].label:(i.category||'Other Material');
    return k===label;
  });
  if(!items.length){ toast('Nothing to delete here.',true); return; }
  window._mtDelIds=items.map(i=>i.id).filter(id=>id!=null);
  showModal('Delete All Files',
   `<div class="alert alert-danger">All <b>${items.length}</b> file${items.length>1?'s':''} under <b>${esc(label)}</b> in <b>${esc(sub.subject)}</b> will be permanently removed for everyone. This cannot be undone.</div>
    <div class="form-group"><label>Type DELETE to confirm</label><input class="form-control" id="mdelall-in" placeholder="DELETE" autocomplete="off"></div>`,
   `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-danger" id="mdelall-btn" onclick="_doDeleteMatCategory('${who}')">Delete All</button>`);
}
async function _doDeleteMatCategory(who){
  if((val('mdelall-in')||'').trim().toUpperCase()!=='DELETE'){ toast('Please type DELETE to confirm.',true); return; }
  const ids=window._mtDelIds||[];
  const b=document.getElementById('mdelall-btn'); if(b){ b.disabled=true; b.textContent='Deleting...'; }
  let ok=0,fail=0;
  for(const id of ids){
    try{ await api('/api/'+who+'/material/'+id,'DELETE'); ok++; }catch(e){ fail++; }
  }
  window._mtDelIds=null;
  closeModal();
  toast(ok+' file'+(ok===1?'':'s')+' deleted'+(fail?', '+fail+' could not be removed':'.'), fail>0);
  _mtReload();
}
// ---------- v114: New-upload tracking (Classes Material) ----------
// Pehli baar section khulne par maujood items "seen" baseline ban jaate hain (koi
// badge nahi); uske BAAD aane wale naye notes/dpp ids nav badge + subject card
// NEW pill + table row blink me dikhte hain. Row click karte hi blink hat jaata
// hai (localStorage me seen save). Tracking sirf student + admin ke liye.
function _matSeenLoad(role){ try{ const v=JSON.parse(localStorage.getItem('mvs_matseen_'+role)||'null'); return (v&&Array.isArray(v.ids))?v:null; }catch(e){ return null; } }
function _matSeenSave(role,ids){ try{ localStorage.setItem('mvs_matseen_'+role,JSON.stringify({ids:ids.slice(-900)})); }catch(e){} }
function _matNewIds(role,items){
  const ids=(items||[]).filter(i=>i&&(i.type==='notes'||i.type==='dpp')&&i.id!=null).map(i=>i.id);
  const st=_matSeenLoad(role);
  if(!st){ _matSeenSave(role,ids); return new Set(); }
  const seen=new Set(st.ids);
  return new Set(ids.filter(id=>!seen.has(id)));
}
function _matMarkSeen(role,ids){ const st=_matSeenLoad(role); const seen=new Set(st?st.ids:[]); (ids||[]).forEach(id=>seen.add(id)); _matSeenSave(role,[...seen]); }
function _matBadge(role){
  if(role!=='admin'&&role!=='student') return;
  const el=document.getElementById(role==='admin'?'a-mat-badge':'s-mat-badge'); if(!el) return;
  const s=(role==='admin'?window._mtNew:window._sMatNew); const c=s?s.size:0;
  if(c>0){ el.style.display='inline-block'; el.textContent=c>99?'99+':c; } else el.style.display='none';
}
function _matRowSeen(role,tr,id){
  if(!tr||!tr.classList.contains('mt-row-new')) return;
  tr.classList.remove('mt-row-new');
  const t=tr.querySelector('.mt-new-tag'); if(t) t.remove();
  const s=(role==='student'?window._sMatNew:window._mtNew); if(s) s.delete(id);
  _matMarkSeen(role,[id]);
  _matBadge(role);
}
// smart shortcut: ek click me saare naye uploads "read" — saari blinks/badges saaf
function _matAllRead(role){
  if(role==='admin'||role==='teacher'){
    _matMarkSeen(role,(_mtData||[]).flatMap(s=>s.chapters.flatMap(c=>c.items)).map(i=>i.id));
    if(window._mtNew) window._mtNew.clear();
  }else{
    _matMarkSeen('student',(window._sMats||[]).map(m=>m.id));
    if(window._sMatNew) window._sMatNew.clear();
  }
  _matBadge(role);
  const sel=role==='admin'?'#a-mat-tree':(role==='teacher'?'#t-mat-tree':'#s-materials-content');
  document.querySelectorAll(sel+' .mt-row-new').forEach(tr=>tr.classList.remove('mt-row-new'));
  document.querySelectorAll(sel+' .mt-new-tag, '+sel+' .sm-new-pill, '+sel+' .mt-new-head').forEach(x=>x.remove());
}
function _mtPick(wrapId,sub){ _mtSub=decodeURIComponent(sub); _mtPaint(wrapId); }
function _mtBack(wrapId){ _mtSub=null; _mtPaint(wrapId); }
function _mtToggle(el){ const c=el.closest('.mat-cat'); c.classList.toggle('closed'); }
const _MT_CAT={notes:{label:'Class Notes',icon:'book',badge:'sc-indigo'},dpp:{label:'DPP',icon:'clipboard',badge:'sc-green'},test:{label:'Tests',icon:'edit',badge:'sc-purple'}};
function _chapNum(s){ const m=String(s||'').match(/(\d+)/); return m?parseInt(m[1],10):-1; }
function _partNum(s){ const m=String(s||'').match(/(\d+)/); return m?parseInt(m[1],10):-1; }
function _mtPaint(wrapId){
  const wrap=document.getElementById(wrapId); if(!wrap||!_mtData) return;
  // ---- subject cards (same look as the student portal)
  if(!_mtSub){
    const cards=_mtData.map(s=>{
      const items=s.chapters.flatMap(c=>c.items);
      const n=t=>items.filter(i=>i.type===t).length;
      const nOther=items.filter(i=>!['notes','dpp','test'].includes(i.type)).length;
      let b='';
      if(n('notes')) b+=`<span class="sm-badge sm-notes">${n('notes')} Class Notes</span>`;
      if(n('dpp')) b+=`<span class="sm-badge sm-dpp">${n('dpp')} DPP</span>`;
      if(n('test')) b+=`<span class="sm-badge sm-test">${n('test')} Tests</span>`;
      if(nOther) b+=`<span class="sm-badge sm-other">${nOther} Other</span>`;
      const v=items.reduce((a,i)=>a+i.views,0), d=items.reduce((a,i)=>a+i.downloads,0);
      const nNew=items.filter(i=>window._mtNew&&window._mtNew.has(i.id)).length;
      return `<div class="sm-card" onclick="_mtPick('${wrapId}','${encodeURIComponent(s.subject)}')">${nNew?`<span class="sm-new-pill">${nNew} NEW</span>`:''}<div class="sm-icon">${ic('book')}</div><div class="sm-body"><div class="sm-title">${esc(s.subject)}</div><div class="sm-badges">${b||'<span class="sm-badge">No files</span>'}</div><div class="ms-meta">${v} views \u00b7 ${d} downloads</div></div><span class="sm-arrow">\u203a</span></div>`;
    }).join('');
    const newN=((window._mtNew&&window._mtNew.size)||0);
    const _mtRole=_mtBase.indexOf('admin')>=0?'admin':'teacher';
    wrap.innerHTML=`${newN?`<div class="sm-head" style="display:flex;align-items:center"><span class="mt-new-head">${newN} new upload${newN>1?'s':''} since your last visit <button class="mt-new-clear" onclick="_matAllRead('${_mtRole}')">Mark all read</button></span></div>`:''}<div class="sm-grid">${cards}</div>`;
    return;
  }
  // ---- one subject: a separate collapsible table per category
  const sub=_mtData.find(s=>s.subject===_mtSub); if(!sub){ _mtSub=null; _mtPaint(wrapId); return; }
  const items=sub.chapters.flatMap(c=>c.items.map(i=>({...i, chapter:c.chapter})));
  const byCat={};
  items.forEach(i=>{ const k=_MT_CAT[i.type]?_MT_CAT[i.type].label:(i.category||'Other Material'); (byCat[k]=byCat[k]||[]).push(i); });
  const order=['Class Notes','DPP','Tests'];
  const keys=Object.keys(byCat).sort((a,b)=>{ const ia=order.indexOf(a),ib=order.indexOf(b); return (ia<0?99:ia)-(ib<0?99:ib)||a.localeCompare(b); });
  const who=_mtBase.indexOf('admin')>=0?'admin':'teacher';
  let html=`<div class="sm-head" style="display:flex;align-items:center;gap:14px"><button class="btn btn-ghost btn-sm" onclick="_mtBack('${wrapId}')">\u2190 Back</button><div><h2 style="margin:0;font-size:1.4rem">${esc(sub.subject)}</h2><p style="margin:0">Class Notes, DPP &amp; other material</p></div></div><div class="card"><div class="card-body">`;
  keys.forEach(cat=>{
    const meta=Object.values(_MT_CAT).find(m=>m.label===cat)||{icon:'folder',badge:'sc-amber'};
    const rows=byCat[cat].slice().sort((a,b)=>{
      const an=(window._mtNew&&a.id!=null&&window._mtNew.has(a.id))?1:0;
      const bn=(window._mtNew&&b.id!=null&&window._mtNew.has(b.id))?1:0;
      if(an!==bn) return bn-an;                                   // NEW (unopened) sabse upar
      const na=_chapNum(a.chapter), nb=_chapNum(b.chapter);
      if(nb!==na) return nb-na;                                   // chapter number DESCENDING
      const pa=_partNum(a.part), pb=_partNum(b.part);
      if(pb!==pa) return pb-pa;                                   // part number DESCENDING
      return String(b.part||'').localeCompare(String(a.part||'')); // fallback: part desc
    }).map(i=>{
      const fname=(i.filename||((i.title||cat)+'.pdf')).replace(/'/g,'');
      const isNew=window._mtNew&&i.id!=null&&window._mtNew.has(i.id);
      const isDpp=i.dpp_pack_id!=null;
      const eng=isDpp
        ? `<td><span class="mt-eng" style="cursor:default">${ic('users')} ${i.views}</span></td><td><span class="mt-eng" style="cursor:default">${ic('download')} ${i.downloads}</span></td>`
        : `<td><button class="mt-eng" title="Students who viewed" onclick="openMatAudience(${i.id},'view')">${ic('users')} ${i.views}</button></td><td><button class="mt-eng" title="Students who downloaded" onclick="openMatAudience(${i.id},'download')">${ic('download')} ${i.downloads}</button></td>`;
      const acts=isDpp
        ? `<button class="btn btn-primary btn-sm" onclick="event.stopPropagation();dppLangPick(${i.dpp_pack_id},'download')">${ic('download')} Download</button>`
        : `<button class="btn btn-primary btn-sm" onclick="downloadMaterial('${who}',${i.id},'${esc(fname)}')">${ic('download')} Download</button><button class="btn btn-danger btn-sm" title="Delete this file permanently" onclick="deleteMaterial('${who}',${i.id},'${encodeURIComponent(i.filename||i.title||'')}')">${ic('trash')}</button>`;
      return `<tr class="${isNew?'mt-row-new':''}" onclick="_matRowSeen('${who}',this,${i.id})">
      <td class="mat-ch">${esc(i.chapter||'\u2014')}${isNew?'<span class="mt-new-tag">NEW</span>':''}${isDpp?'<span class="mt-new-tag" style="background:#0891b2">DPP</span>':''}</td>
      <td>${i.part?esc(i.part):'<span class="mt-dim">Whole chapter</span>'}</td>
      <td><div class="mat-file">${ic('book')}${esc(i.filename||i.title||'')}</div></td>
      <td class="mt-dim">${esc(i.date)}</td>
      ${eng}
      <td class="mat-dl-cell"><div class="mat-acts">${acts}</div></td>
    </tr>`;}).join('');
    html+=`<div class="mat-cat"><div class="mat-cat-head" onclick="_mtToggle(this)"><div class="mc-badge ${meta.badge}">${ic(meta.icon)}</div>${esc(cat)}<span class="mc-count">${byCat[cat].length} file${byCat[cat].length>1?'s':''}</span><button class="btn btn-danger btn-sm mc-del" title="Delete every file in this category" onclick="event.stopPropagation();deleteMatCategory('${who}','${encodeURIComponent(cat)}')">${ic('trash')} Delete All</button><span class="mc-chev">\u203a</span></div><div class="mat-twrap"><table class="mat-table"><thead><tr><th>Chapter</th><th>Class / Part</th><th>File</th><th>Uploaded</th><th>Views</th><th>Downloads</th><th style="text-align:right">Actions</th></tr></thead><tbody>${rows}</tbody></table></div></div>`;
  });
  html+=`</div></div>`;
  wrap.innerHTML=html;
}

async function openExamAudience(eid,which){
  showModal('Student Engagement','<div id="ma-body"><div class="spinner"></div></div>','<button class="btn btn-ghost" onclick="closeModal()">Close</button>');
  try{
    const d=await api('/api/teacher/exam/'+eid+'/audience');
    _paintAudience(d,which);
  }catch(e){ document.getElementById('ma-body').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`; }
}
function _paintAudience(d,which){
  const list=(which==='download'?d.downloaders:d.viewers)||[];
  const m=d.material||{};
  const title=`${esc(m.title||'')}${m.part?' \u00b7 '+esc(m.part):''}`;
  const rows=list.length?list.map(s=>`<div class="ma-row"><div class="ma-av">${esc((s.name||'S').charAt(0))}</div><div class="ma-main"><div class="ma-name">${esc(s.name)}</div><div class="ma-at">${esc(s.at)}</div></div></div>`).join('')
    :`<div class="ws-empty"><p>No students yet</p><small>${which==='download'?'Nobody has downloaded this yet.':'Nobody has opened this yet.'}</small></div>`;
  document.getElementById('ma-body').innerHTML=`<div class="alert alert-info">${title}</div><div class="ma-head">${which==='download'?'Downloaded by':'Viewed by'} <b>${list.length}</b> student${list.length===1?'':'s'}</div><div class="ma-list">${rows}</div>`;
}

