function dppLangPick(pid,action){
  const pk=(window._dppPacks||[]).find(x=>x.id===pid); if(!pk) return;
  // Uploaded PDF pack -> language nahi, par Question Paper vs Solution ka choice do
  if(pk.source!=='created'){
    showModal((action==='view'?'View':'Download')+' \u2014 '+esc(pk.title||'DPP'),
      `<div class="pm-grid">
        <button class="pm-opt" onclick="closeModal();dppPdfGo(${pid},'${action}','q','')"><span class="pm-ic">${ic('file')}</span><span class="pm-tx"><b>Question Paper</b><small>Questions PDF</small></span></button>
        <button class="pm-opt" onclick="closeModal();dppPdfGo(${pid},'${action}','s','')"><span class="pm-ic">${ic('check')}</span><span class="pm-tx"><b>Solution</b><small>Solutions PDF (with answers)</small></span></button>
      </div>`,
      `<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
    return;
  }
  const meds=(pk.medium==='Hindi')?['hindi']:['english','hindi'];
  window._dppLang=meds[0];
  showModal((action==='view'?'View':'Download')+' — '+esc(pk.title||'DPP'),
    `<div style="padding:4px 2px">
      <div style="font-size:.82rem;font-weight:700;color:var(--text-muted);margin-bottom:8px">1. LANGUAGE SELECT KARO</div>
      <div style="display:flex;gap:8px;margin-bottom:18px" id="dpp-lang-row">
        ${meds.map(m=>`<button class="btn ${m===meds[0]?'btn-primary':'btn-ghost'} btn-sm" data-lang="${m}" onclick="window._dppLang='${m}';document.querySelectorAll('#dpp-lang-row .btn').forEach(b=>{b.classList.remove('btn-primary');b.classList.add('btn-ghost')});this.classList.remove('btn-ghost');this.classList.add('btn-primary')">${m==='hindi'?'हिंदी':'English'}</button>`).join('')}
      </div>
      <div style="font-size:.82rem;font-weight:700;color:var(--text-muted);margin-bottom:8px">2. KAUNSA PAPER?</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <button class="btn btn-primary btn-sm" onclick="closeModal();dppPdfGo(${pid},'${action}','q',window._dppLang||'english')">${ic('file')} Questions Paper</button>
        <button class="btn btn-ghost btn-sm" onclick="closeModal();dppPdfGo(${pid},'${action}','s',window._dppLang||'english')">${ic('check')} Solutions Paper</button>
      </div>
    </div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
}
// ---------- DPP premium View/Download hub (test-section jaisa) ----------
function _dppMeds(pk){ return (pk&&pk.medium==='Hindi')?['hindi']:(pk&&pk.medium==='English')?['english']:['english','hindi','both']; }
function _dppHubHTML(pid,kind,action,created,goFn){
  // medium selection step (sirf created packs ke liye)
  const pk=(window._sDppPacks||[]).find(x=>x.id===pid)||(window._dppPacks||[]).find(x=>x.id===pid)||(window._sMatDppPacks||[]).find(x=>x.id===pid)||{};
  if(!created){ closeModal(); window[goFn](pid,action,kind,''); return; }
  const meds=_dppMeds(pk);
  const _MED={
    english:{ic:'A', t:'English', s:(kind==='s'?'Solutions':'Question paper')+' in English'},
    hindi:{ic:'अ', t:'हिंदी', s:(kind==='s'?'हल':'प्रश्न पत्र')+' हिंदी में'},
    both:{ic:'Aअ', t:'English + हिंदी', s:'दोनों माध्यम — bilingual'}
  };
  showModal('Select Medium',
   `<div class="pm-grid">`+meds.map(m=>{const o=_MED[m]||_MED.english;
     return `<button class="pm-opt" onclick="closeModal();${goFn}(${pid},'${action}','${kind}','${m}')"><span class="pm-ic">${o.ic}</span><span class="pm-tx"><b>${o.t}</b><small>${o.s}</small></span></button>`;}).join('')+`</div>`,
   `<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
}
function _dppHub(pid,kind,goFn,cacheName){
  const pk=((window[cacheName]||[]).find(x=>x.id===pid))||{};
  const created=pk.source==='created';
  const kName=kind==='s'?'Solutions':'Question Paper';
  showModal(kName+(pk.title?' — '+esc(pk.title):''),
   `<div class="pm-grid">`
   +`<button class="pm-opt" onclick="_dppHubHTML(${pid},'${kind}','view',${created?1:0},'${goFn}')"><span class="pm-ic">V</span><span class="pm-tx"><b>View ${kind==='s'?'Solutions':'Paper'}</b><small>Read right here on the portal${created?' — choose a medium':''}</small></span></button>`
   +`<button class="pm-opt" onclick="_dppHubHTML(${pid},'${kind}','download',${created?1:0},'${goFn}')"><span class="pm-ic">D</span><span class="pm-tx"><b>Download PDF</b><small>Premium formatted PDF${created?' — choose a medium':''}</small></span></button>`
   +`</div>`,
   `<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
}
// View/Download hub step HATA DIYA — Download click pe seedha medium puchho, phir turant download
function sDppHub(pid,kind){ const pk=(window._sDppPacks||window._sMatDppPacks||[]).find(x=>x.id===pid)||{}; _dppHubHTML(pid,kind,'download',pk.source==='created'?1:0,'sDppGo'); }
function tDppHub(pid,kind){ const pk=(window._dppPacks||[]).find(x=>x.id===pid)||{}; _dppHubHTML(pid,kind,'download',pk.source==='created'?1:0,'dppPdfGo'); }
// Bulletproof PDF fetch: 4 tak retry, har attempt pe 2 min timeout (AbortController),
// empty/partial file reject. Slow Railway pe connection toot-toot ke bhi eventually mil jaati hai.
async function _dlPdfBlob(url){
  let lastErr;
  for(let attempt=0; attempt<4; attempt++){
    const ctrl=new AbortController();
    const to=setTimeout(()=>ctrl.abort(), 120000);
    try{
      const r=await fetch(url,{headers:{Authorization:'Bearer '+TOKEN}, signal:ctrl.signal});
      clearTimeout(to);
      if(!r.ok) throw new Error('HTTP '+r.status);
      const bl=await r.blob();
      if(!bl || bl.size<200) throw new Error('empty');
      return bl;
    }catch(e){
      clearTimeout(to); lastErr=e;
      if(attempt<3){
        if(attempt===0) toast('PDF aa rahi hai — server thoda slow hai, ho jaayega…');
        await new Promise(r=>setTimeout(r, 2500*(attempt+1)));
      }
    }
  }
  throw lastErr||new Error('download failed');
}
// student PDF fetch (view ya download) — medium ke saath
async function sDppGo(pid,action,kind,med){
  try{
    const bl=await _dlPdfBlob(API+`/api/student/dpp-packs/${pid}/file?kind=${kind}&med=${med||''}`);
    const u=URL.createObjectURL(bl);
    const fname=(kind==='s'?'DPP-solutions':'DPP-questions')+'-'+(med||'paper')+'.pdf';
    if(action==='view') pdfViewerModal(u,(kind==='s'?'Solutions':'Questions')+(med==='hindi'?' — हिंदी':(med==='both'?' — English + हिंदी':' — English')),fname);
    else{ const a=document.createElement('a'); a.href=u; a.download=fname; document.body.appendChild(a); a.click(); a.remove(); _dppTrack(pid,'download'); toast('Downloaded.'); }
    setTimeout(()=>URL.revokeObjectURL(u),300000);
  }catch(e){
    toast('PDF abhi nahi aa paayi — server busy hai. 1 min baad dobara try karo.',true);
  }
}
function pdfViewerModal(u,title,fname){
  showModal(esc(title||'PDF'), `<div id="pvm-view"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
  { const _mm=document.querySelector('#modal .modal'); if(_mm)_mm.classList.add('cx'); }
  _pdfView(document.getElementById('pvm-view'), u, {title:title||'PDF', downloadName:fname||'document.pdf', src:u});
}
async function dppPdfGo(pid,action,kind,med){
  toast('PDF '+(med==='hindi'?'(Hindi ':'(English ')+(kind==='s'?'solutions)':'questions)')+' aa rahi hai…');
  try{
    const bl=await _dlPdfBlob(API+`/api/teacher/dpp-packs/${pid}/pdf?kind=${kind}&medium=${med||''}`);
    const u=URL.createObjectURL(bl);
    const fname=(kind==='s'?'DPP-solutions':'DPP-questions')+'-'+(med||'english')+'.pdf';
    if(action==='view'){
      pdfViewerModal(u,(kind==='s'?'Solutions':'Questions')+' — '+(med==='hindi'?'हिंदी':'English'),fname);
    }else{
      const a=document.createElement('a'); a.href=u; a.download=fname; document.body.appendChild(a); a.click(); a.remove(); toast('Downloaded.');
    }
    setTimeout(()=>URL.revokeObjectURL(u),300000);
  }catch(e){
    toast('PDF abhi nahi aa paayi — server busy hai. 1 min baad dobara try karo.',true);
  }
}
// ---------- submissions (results) — Checking / Checked + Remarks (no marks) ----------
async function dppDelete(pid,title){
  if(!confirm(`Delete "${title||'this DPP'}"?\n\nIski saari student submissions bhi delete ho jayengi. Ye action undo nahi hoga.`)) return;
  try{ await api('/api/teacher/dpp-packs/'+pid,'DELETE'); toast('DPP deleted.'); loadTDpp(); }
  catch(e){ toast(e.message||'Delete failed',true); }
}
