// ---------- bulletproof rich formatter: markdown + LaTeX (Kimi/Claude/Gemini paste-safe) ----------
// _texFix: AI-paste ki common LaTeX galtiyan theek karta hai (\text K, dangling _^, \cir...)
function _texFix(t){
  let s=String(t||'');
  s=s.replace(/\\text\s*([^\s{][^}]*)/g,'\\text{$1}');
  s=s.replace(/\\(mathrm|mathbf|mathit)\s*([^\s{])/g,'\\mathrm{$2}');
  s=s.replace(/\^\{\}/g,'').replace(/_\{\}/g,'');
  s=s.replace(/[_^]\s*(?=[\s$])/g,'');
  s=s.replace(/\\cir(?!c|[a-zA-Z])/g,'^\\circ');
  s=s.replace(/\\left\s*(?=[^([{|$])/g,'').replace(/\\right\s*(?=[^)\]}|$])/g,'');
  return s;
}
// _texPlain: last-resort readable plain text (kabhi red error NAHI)
function _texPlain(t){
  let s=String(t||'');
  s=s.replace(/\\frac\{([^{}]*)\}\{([^{}]*)\}/g,'($1)/($2)');
  s=s.replace(/\\sqrt\{([^{}]*)\}/g,'\u221a($1)');
  s=s.replace(/\\times/g,'\u00d7').replace(/\\div/g,'\u00f7').replace(/\\pm/g,'\u00b1');
  s=s.replace(/\\pi/g,'\u03c0').replace(/\\theta/g,'\u03b8').replace(/\\Delta/g,'\u0394').replace(/\\sigma/g,'\u03c3');
  s=s.replace(/\\circ|\\degree/g,'\u00b0');
  s=s.replace(/\^\{([^{}]*)\}/g,'^$1').replace(/_\{([^{}]*)\}/g,'_$1');
  s=s.replace(/\^([A-Za-z0-9]+)/g,'^$1').replace(/_([A-Za-z0-9]+)/g,'_$1');
  s=s.replace(/\\text\{([^{}]*)\}/g,'$1').replace(/\\(?:mathrm|mathbf|mathit)\{([^{}]*)\}/g,'$1');
  s=s.replace(/\\[a-zA-Z]+/g,'').replace(/[{}]/g,'');
  return s.trim();
}
