const _UNI_GR={'α':'alpha','β':'beta','γ':'gamma','δ':'delta','ε':'epsilon','ζ':'zeta','η':'eta','θ':'theta','ι':'iota','κ':'kappa','λ':'lambda','μ':'mu','ν':'nu','ξ':'xi','π':'pi','ρ':'rho','σ':'sigma','τ':'tau','υ':'upsilon','φ':'phi','χ':'chi','ψ':'psi','ω':'omega','Δ':'Delta','Σ':'Sigma','Π':'Pi','Ω':'Omega','Φ':'Phi','Λ':'Lambda','Θ':'Theta','Ψ':'Psi','Γ':'Gamma','Ξ':'Xi'};
const _UNI_OP={'×':'\\times','÷':'\\div','±':'\\pm','∓':'\\mp','≠':'\\neq','≤':'\\leq','≥':'\\geq','≈':'\\approx','∞':'\\infty','∝':'\\propto','∫':'\\int','∑':'\\sum','∏':'\\prod','∂':'\\partial','∇':'\\nabla','∈':'\\in','∉':'\\notin','⊂':'\\subset','∪':'\\cup','∩':'\\cap','∀':'\\forall','∃':'\\exists','∠':'\\angle','⊥':'\\perp','∥':'\\parallel','≅':'\\cong','∼':'\\sim','△':'\\triangle','∴':'\\therefore','∵':'\\because','·':'\\cdot','∘':'\\circ','†':'\\dagger','−':'-'};
const _UNI_AR={'→':'\\to','⟶':'\\longrightarrow','←':'\\leftarrow','⟵':'\\longleftarrow','↔':'\\leftrightarrow','⇒':'\\Rightarrow','⇐':'\\Leftarrow','⇔':'\\Leftrightarrow','↑':'\\uparrow','↓':'\\downarrow','↦':'\\mapsto','⇌':'\\rightleftharpoons','⇋':'\\rightleftharpoons'};
