  s=s.replace(/[α-ωΑ-Ω]/g,(c,off,str)=>_UNI_GR[c]?_sp('\\'+_UNI_GR[c],str,off):c);
  s=s.replace(/[→⟶←⟵↔⇒⇐⇔↑↓↦⇌⇋]/g,(c,off,str)=>_sp(_UNI_AR[c]||c,str,off));
  s=s.replace(/[×÷±∓≠≤≥≈∞∝∫∑∏∂∇∈∉⊂∪∩∀∃∠⊥∥≅∼△∴∵·∘†]/g,(c,off,str)=>_sp(_UNI_OP[c]||c,str,off));
  s=s.replace(/″/g,(m,off,str)=>_sp('^{\\prime\\prime}',str,off)).replace(/′/g,(m,off,str)=>_sp('^\\prime',str,off));
  s=s.replace(/([0-9A-Za-z)\}])\s*[°º˚]/g,(m,b,off,str)=>b+'^\\circ'+((str[off+m.length]&&/[A-Za-z]/.test(str[off+m.length]))?' ':'')).replace(/[°º˚]/g,(m,off,str)=>_sp('^\\circ',str,off));
  s=s.replace(/√\s*\(([^()]*(?:\([^()]*\)[^()]*)*)\)/g,'\\sqrt{$1}');
  s=s.replace(/√\s*\[([^\[\]]*)\]\s*\(([^()]*(?:\([^()]*\)[^()]*)*)\)/g,'\\sqrt[$1]{$2}');
