    p=p.replace(/(?<![\d\/{}\\])(\d{1,6})\s*\/\s*\(([^()]*)\)/g,'\\frac{$1}{$2}');
    p=p.replace(/(?<![\d\/{}\\])(\d{1,6})\s*\/\s*(\d{1,6})(?![\d\/])/g,'\\frac{$1}{$2}');
    p=p.replace(/\)(\d{1,2})(?![\d.])/g,')^{$1}');
    p=p.replace(/(?<=[A-Z][a-z])(\d{1,2})(?![\d.])/g,'_{$1}');
