const _autoFmtBusy={};
async function _autoFmtField(t, viaPaste){
  if(!t||!t.id||_autoFmtBusy[t.id]) return;
  const before=t.value||'';
  if(!before.trim()) return;
  let healed=_mathHeal(before);
  if(!/\$|\\[a-zA-Z]+/.test(healed)){
    try{ const sf=(spFormatMatch(healed,null)||spSmartFormat(healed)); if(sf) healed=sf; }catch(e){}
  }
  healed=healed.replace(/[ \t]*\n?[ \t]*(?:^|\n)[ \t]*(?:\*\*)?\s*(?:or|OR|Or|oR)\s*(?:\*\*)?[ \t]*(?=\n|$)/g,'\n\nOR\n').replace(/\n{3,}/g,'\n\n');
  let aiUsed=false;
  await _loadAiFmtCfg();                       // v122: Admin ka subject-wise AI toggle
  const _aiSubj=_aiOnFor(_curExSubject());
  const _aiWanted = _aiSubj===true ? !!viaPaste : (_aiSubj===null ? (viaPaste && _needsAIFrag(healed)) : false);
  if(_aiWanted && sessionStorage.getItem('mvs_fmtai')!=='0'){
    _autoFmtBusy[t.id]=1;
    t.classList.add('ai-busy'); // v119: paste hote hi gold glow — AI chal raha hai, instant feedback
    try{
      const r=await Promise.race([api('/api/teacher/format-text-ai','POST',{text:healed}),
        new Promise((_,rj)=>setTimeout(()=>rj(new Error('timeout')),25000))]);
      if(r&&r.text&&String(r.text).trim()){ healed=String(r.text); aiUsed=true; }
      else sessionStorage.setItem('mvs_fmtai','0');
    }catch(e){ if((e&&e.status)||/timeout|503|404|unavailable/i.test(String(e&&e.message||e))) sessionStorage.setItem('mvs_fmtai','0'); }
    finally{ delete _autoFmtBusy[t.id]; t.classList.remove('ai-busy'); }
  }
  if(healed!==before){
    t.value=healed;
    t.dispatchEvent(new Event('input',{bubbles:true}));
    if(aiUsed) toast('Auto-formatted with AI — review the preview.');
  }
}
document.addEventListener('paste',e=>{
  const t=e.target;
  if(!t||(t.tagName!=='TEXTAREA'&&t.tagName!=='INPUT')) return;
  const of=t.getAttribute&&t.getAttribute('onfocus');
  if(!(of&&of.indexOf('_lastField')>=0)) return;
  // clipboard me image ho -> seedha AI OCR (PYQ screenshot paste karo, koi button nahi)
  const items=(e.clipboardData&&e.clipboardData.items)||[];
  for(let k=0;k<items.length;k++){
    if(items[k].type&&items[k].type.indexOf('image')===0){
      const f=items[k].getAsFile();
      if(f){ e.preventDefault(); if(t.id) _ocrTo(t.id, f, null); else toast('Click inside the box first, then paste the screenshot.',true); return; }
    }
  }
  setTimeout(()=>_autoFmtField(t,true),60);
},true);
document.addEventListener('focusout',e=>{
  const t=e.target;
  if(!t||(t.tagName!=='TEXTAREA'&&t.tagName!=='INPUT')) return;
  const of=t.getAttribute&&t.getAttribute('onfocus');
  if(!(of&&of.indexOf('_lastField')>=0)) return;
  _autoFmtField(t,false);
},true);
