    if(/\\(frac|dfrac|tfrac|cfrac|sqrt|text\s*\{|binom|ce\{|boxed|int|sum|prod|lim|vec|hat|overline|underline|mathbb|overbrace|underbrace)\b/.test(gg)) return stash(gg,_promoteDisp(gg));
    const stripped=gg.replace(/\\[a-zA-Z]+\{([^{}]*)\}/g,'$1').replace(/\\[a-zA-Z]+/g,' ');
    const words=(stripped.match(/[\p{L}\p{M}]{2,}/gu)||[]).length;
