function spDetectSubject(t){
  t=(t||'').toLowerCase();
  if(/physic|भौतिक/.test(t))return 'physics';
  if(/chem|रसायन/.test(t))return 'chemistry';
  if(/math|गणित/.test(t))return 'maths';
  if(/bio|जीव विज्ञान/.test(t))return 'biology';
  if(/politic|civics|राजनीति|नागरिक/.test(t))return 'political';
  if(/history|इतिहास/.test(t))return 'history';
  if(/geograph|भूगोल/.test(t))return 'geography';
  if(/econom|business|account|अर्थशास्त्र|व्यवसाय|लेखा/.test(t))return 'economics';
  if(/computer|data entry|information technology|कंप्यूटर|सूचना/.test(t))return 'computer';
  return 'general';
}
function spGlossPairs(sub){
  const g=Object.assign({},spGloss.general,spGloss[sub]||{});
  return Object.keys(g).sort((a,b)=>b.length-a.length).map(k=>[k,g[k]]);
}
const spTRMATH=/\$[^$]+\$|\\\([^)]*\\\)|\\\[[^\]]*\\\]/g;
function spTrEsc(s){ return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); }
async function spTrChunk(text){
  try{
    const ctl=new AbortController(); const to=setTimeout(()=>ctl.abort(),9000);
    const r=await fetch('https://translate.googleapis.com/translate_a/single?client=gtx&sl=en&tl=hi&dt=t&q='+encodeURIComponent(text),{signal:ctl.signal});
    clearTimeout(to);
    if(r.ok){ const d=await r.json(); if(d&&d[0]){ const out=d[0].map(sg=>(sg&&sg[0])||'').join(''); if(out&&out.trim())return out; } }
  }catch(e){}
  try{
    const ctl=new AbortController(); const to=setTimeout(()=>ctl.abort(),9000);
    const r=await fetch('https://api.mymemory.translated.net/get?q='+encodeURIComponent(text.slice(0,450))+'&langpair=en|hi',{signal:ctl.signal});
    clearTimeout(to);
    if(r.ok){ const d=await r.json(); const out=d&&d.responseData&&d.responseData.translatedText; if(out&&out.trim()&&!/QUERY LENGTH LIMIT|MYMEMORY WARNING|INVALID/i.test(out))return out; }
  }catch(e){}
  return null;
}
async function spTrEngine(text){
  if(text.length<=1100) return spTrChunk(text);
  const parts=text.split(/(?<=[.!?\n])\s+/).filter(x=>x.trim());
  const chunks=[]; let cur='';
  for(const p of parts){ if((cur+' '+p).length>900){ if(cur)chunks.push(cur); cur=p; } else cur=cur?cur+' '+p:p; }
  if(cur)chunks.push(cur);
  const outs=[];
  for(const c of chunks){ const t=await spTrChunk(c); if(t==null)return null; outs.push(t); }
  return outs.join(' ');
}
function spMaskFormulas(str, store){
  // Maths terms / formulas engine ko bhejne hi nahi chahiye - jaise likhe hain
  // waise hi rehne chahiye. Mathish tokens (=, ^, \\, unicode powers/fractions,
  // letter-digit mix jaise kx2, H2O) mask ho jaate hain; formula-context me
  // chhote 1-3 letter tokens (mgh, KE, cos) bhi. Asli English words (4+ letters)
  // hamesha translate hote hain.
  const MATHCH=/[=^\\\u221a\u00d7\u00f7\u00b1\u0394\u00bd\u00bc\u00be\u00b9\u00b2\u00b3\u2070\u2074-\u2079\u2080-\u2089]/;
  str=String(str);
  // Option labels (A) (B) a) b) — engine inhe "ए)" me transliterate kar deta tha
  str=str.replace(/(^|[\s(\n])([A-Ea-e])\)(?=\s)/g,(m,pre,L)=>{ store.push(L+')'); return pre+'\u27E6'+(9000+store.length-1)+'\u27E7'; });
  // Number+unit pairs (8 kg, 100 N, 3 m/s², 500 J, 36 km/h…) — units kabhi translate nahi hote
  str=str.replace(/\d+(?:[.,]\d+)?\s*(?:N|J|W|Pa|Hz|kWh|eV|V|Ω|C|K|kg|mg|km|cm|mm|mL|mol|m\/s²|m\/s2|m\/s|km\/h|g|m|s|min|h|L|A|°C|°F|%)(?=[\s.,;:!?)\n]|$)/g,m=>{ store.push(m); return '\u27E6'+(9000+store.length-1)+'\u27E7'; });
  // Akela unit-symbol bhi — sirf math symbol ya digit ke turant baad ("= 24 N", "F/N")
  str=str.replace(/(?<=[=+\-×÷/\d])(N|J|W|Pa|Hz|V|Ω|eV|kWh)(?=[\s.,;:!?)\n]|$)/g,m=>{ store.push(m); return '\u27E6'+(9000+store.length-1)+'\u27E7'; });
  const toks=str.split(/(\s+)/);
  const isMathTok=tok=>{
    const bare=tok.replace(/\\[a-zA-Z]+/g,'');
    return MATHCH.test(tok) || /\d[A-Za-z]|[A-Za-z]\d/.test(bare);
  };
  const hasMath=toks.some(t=>t.trim()&&isMathTok(t)&&!/[A-Za-z]{4,}/.test(t.replace(/\\[a-zA-Z]+/g,'')));
  return toks.map(tok=>{
    if(!tok.trim()) return tok;
    const bare=tok.replace(/\\[a-zA-Z]+/g,'');
    const longWord=/[A-Za-z]{4,}/.test(bare);
    const mask = (isMathTok(tok)&&!longWord) || (hasMath&&/^[A-Za-z]{1,3}[.,;:]?$/.test(bare)&&bare.replace(/[.,;:]/g,'').length<=3&&!/^(the|and|for|are|not|all|its|has|was|is|of|to|in|on|at|by|an|a|or|as|if|it|be|do|no|so|we|he)$/i.test(bare.replace(/[.,;:]/g,'')));
    if(mask){ store.push(tok); return '\u27E6'+(9000+store.length-1)+'\u27E7'; }
    return tok;
  }).join('');
}
function spUnmaskFormulas(str, store){
  // Placeholder digits-only hai (9000+) taaki koi bhi engine use word samajh
  // ke translate na kare; math ⟦n⟧ chhote indices use karta hai, collision nahi
  return String(str).replace(/\u27E6\s*(9\d{3,})\s*\u27E7/g,(m,n)=>{ const i=+n-9000; return store[i]!=null?store[i]:m; });
}
async function spTranslateArrayTexts(block, subject){
  // Match-the-following table ($\begin{array}) poora ka poora math ban ke mask ho
  // jata tha, isliye Hindi translate ke baad bhi cells English rehte the. Ab
  // andar ke \text{...} chunks translate hote hain - (a)/(i) markers aur poora
  // LaTeX structure (&, \\, \hline) waise ka waisa rehta hai.
  const re=/\\text\{([^{}]*)\}/g;
  const found=[]; let m;
  while((m=re.exec(block))) found.push(m[1]);
  const uniq=[...new Set(found.filter(t=>/[A-Za-z]{2,}/.test(t)))];
  if(!uniq.length) return block;
  const map={};
  for(const t of uniq){
    const hm=t.match(/^\(\s*[A-Za-z0-9]{1,4}\s*\)\s*/);
    const head=hm?hm[0]:'', body=t.slice(head.length);
    // Formula-only cell (½kx², mgh, W=KE...): koi 4+ letter English word nahi,
    // to poori cell waise hi chhod do - translate karne ki koshish hi nahi
    if(!/[A-Za-z]{4,}/.test(body.replace(/\\[a-zA-Z]+/g,''))) continue;
    const fx=[];
    const masked=spMaskFormulas(body, fx);
    let tr=await spTranslate(masked, subject);
    if(tr&&tr!==masked){ tr=spUnmaskFormulas(tr, fx); map[t]=head+tr; }
  }
  if(!Object.keys(map).length) return block;
  return block.replace(/\\text\{([^{}]*)\}/g,(mm,inner)=> map[inner]!=null ? '\\text{'+map[inner]+'}' : mm);
}
async function spTranslate(text,subject){
  text=(text==null?'':String(text)).trim();
  if(!text)return text;
  if(!/[A-Za-z]/.test(text))return text;   // already Hindi / numeric only
  if(text.indexOf('\\begin{array}')>=0){
    const blocks=text.match(spTRMATH)||[];
    for(const b of blocks){
      if(b.indexOf('\\begin{array}')>=0){
        const nb=await spTranslateArrayTexts(b, subject);
        if(nb!==b) text=text.replace(b, nb);
      }
    }
  }
  const math=[],gl=[],fx=[];
  let s=text.replace(spTRMATH,m=>{ math.push(m); return '\u27E6'+(math.length-1)+'\u27E7'; });
  s=spMaskFormulas(s, fx);   // bina $ wale formulas (½kx², W=KE, mgh) bhi protected
  const pairs=spGlossPairs(subject||'general');
  for(const [en,hi] of pairs){
    const rx=new RegExp('(^|[^\\w\u0900-\u097F])'+spTrEsc(en)+'(?![\\w\u0900-\u097F])','gi');
    s=s.replace(rx,(m,pre)=>{ gl.push(hi); return pre+'\u27E6G'+(gl.length-1)+'\u27E7'; });
  }
  let out;
  if(!/[A-Za-z]/.test(s.replace(/\u27E6G?\d+\u27E7/g,''))){ out=s; }   // only math/glossary tokens — nothing to send
  else { out=await spTrEngine(s); if(out==null)return null; }
  out=spUnmaskFormulas(out, fx);
  out=out.replace(/\u27E6\s*G\s*(\d+)\s*\u27E7/g,(m,n)=>(gl[+n]!=null?gl[+n]:m));
  out=out.replace(/\u27E6\s*(\d+)\s*\u27E7/g,(m,n)=>(math[+n]!=null?math[+n]:m));
  return out;
}
/* ---- exam-form integration ---- */
function spExamSubject(){
  const a=(typeof val==='function'?val('ex-sub'):'')||'';
  const b=(typeof val==='function'?val('ex-title'):'')||'';
  return spDetectSubject(a+' '+b);
}
async function examTranslate(i,btn,silent){
  const q=_examQs[i]; if(!q)return 0;
  const sub=spExamSubject();
  let n=0,att=0;
  const put=async(get,set)=>{ const v=get(); if(!(v&&String(v).trim()))return; att++; const t=await spTranslate(v,sub); if(t){ set(t); n++; } };
  if(!((q.q_hi||'').trim())) await put(()=>q.q,v=>{q.q_hi=v;});
  if(Array.isArray(q.opts)){ q.opts_hi=q.opts_hi||[]; for(let j=0;j<q.opts.length;j++){ if(!((q.opts_hi[j]||'').trim())) await put(()=>q.opts[j],v=>{q.opts_hi[j]=v;}); } }
  if(!((q.expl_hi||'').trim())) await put(()=>q.expl,v=>{q.expl_hi=v;});
  if(!((q.model_hi||'').trim())) await put(()=>q.model,v=>{q.model_hi=v;});
  if(!silent){
    if(n){ q._tab='hi'; renderExamQs(); toast('Hindi translation done (free) — please review once'); }
    else if(att) toast('Translation service unreachable right now — try again in a moment',true);
    else toast('Nothing to translate — English empty or Hindi already filled');
  }
  return n;
}
async function examTranslateAll(btn){
  if(_examMedium!=='Bilingual'){ toast('Set Medium to Bilingual first — Hindi fields appear then',true); return; }
  if(btn.disabled)return;
  btn.disabled=true; const old=btn.textContent; let done=0;
  for(let i=0;i<_examQs.length;i++){
    btn.textContent='Translating '+(i+1)+'/'+_examQs.length+'\u2026';
    done+=await examTranslate(i,null,true);
    await new Promise(r=>setTimeout(r,120));
  }
  btn.disabled=false; btn.textContent=old; renderExamQs();
  toast(done?('Translated '+done+' field(s) to Hindi.'):'Nothing translated — Hindi already filled or English empty.');
}
/* ---- PDF medium chooser ---- */
function examPdfChoose(id,mode){
  const lbl=(mode==='solutions')?'Question Paper + Solutions':'Question Paper';
  showModal('Download PDF — '+lbl,
  `<div class="pm-grid">`
  +`<button class="pm-opt" onclick="closeModal();examPdfPremium(${id},'${mode}','en')"><span class="pm-ic">A</span><span class="pm-tx"><b>English</b><small>Full paper in English medium</small></span></button>`
  +`<button class="pm-opt" onclick="closeModal();examPdfPremium(${id},'${mode}','hi')"><span class="pm-ic">\u0905</span><span class="pm-tx"><b>\u0939\u093f\u0902\u0926\u0940</b><small>\u092a\u0942\u0930\u093e \u092a\u094d\u0930\u0936\u094d\u0928\u092a\u0924\u094d\u0930 \u0939\u093f\u0902\u0926\u0940 \u092e\u0947\u0902 \u2014 \u0905\u0928\u0941\u0935\u093e\u0926 \u0905\u092a\u0928\u0947 \u0906\u0906\u092a, free</small></span></button>`
  +`<button class="pm-opt" onclick="closeModal();examPdfPremium(${id},'${mode}','both')"><span class="pm-ic">A\u0905</span><span class="pm-tx"><b>English + \u0939\u093f\u0902\u0926\u0940</b><small>Bilingual \u2014 \u0926\u094b\u0928\u094b\u0902 \u092e\u093e\u0927\u094d\u092f\u092e \u090f\u0915 \u0938\u093e\u0925</small></span></button>`
  +`</div>`);
}

/* ================= EXAM SCHEDULING + TRACKING HELPERS =================
   Schedule travels inside the chapter field as an invisible marker ⟦S:ISO⟧ so it works
   even before the backend adds a scheduled_at column; if the column exists it wins. */
function spSchedOf(e){
  if(!e)return null;
  const raw=(e.scheduled_at==null?'':String(e.scheduled_at));
  const m=String(e.chapter||'').match(/\u27E6S:([^\u27E7]+)\u27E7/);
  const iso=(raw&&raw!=='null'&&raw!=='None'&&raw!=='undefined')?raw:(m?m[1]:'');
  if(!iso)return null;
  const d=new Date(iso);
  return isNaN(d.getTime())?null:d;
}
function spCleanCh(ch){ return String(ch||'').replace(/\s*\u27E6S:[^\u27E7]*\u27E7/g,'').trim(); }
function spSchedFmt(d){ return d.toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',hour12:true}); }
function spSchedLocal(d){ const p=n=>String(n).padStart(2,'0'); return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+'T'+p(d.getHours())+':'+p(d.getMinutes()); }
/* live countdown engine — ticks every element carrying data-cd="<epoch ms>" */
let _examCdTimer=null;
function spCdStart(){
  if(_examCdTimer)return;
  _examCdTimer=setInterval(()=>{
    const els=document.querySelectorAll('[data-cd]');
    const now=Date.now();
    els.forEach(el=>{
      const t=+el.getAttribute('data-cd');
      let s=Math.max(0,Math.floor((t-now)/1000));
      const d=Math.floor(s/86400); s%=86400;
      const h=String(Math.floor(s/3600)).padStart(2,'0');
      const m=String(Math.floor((s%3600)/60)).padStart(2,'0');
      const ss=String(s%60).padStart(2,'0');
      el.textContent=(t-now<=0)?'LIVE now — refresh the page':(d>0?(d+'d '+(+h)+'h '+m+'m'):((+h)+'h '+m+'m '+ss+'s'));
    });
  },1000);
}
/* student: next upcoming scheduled test (shared by banner + dedupe + reminder) */
async function _sUpcomingExam(){
  try{
    const exs=await api('/api/student/exams');
    const fut=exs.map(e=>({e,sch:spSchedOf(e)}))
      .filter(x=>x.sch&&x.sch.getTime()>Date.now()&&x.e.status!=='graded'&&x.e.status!=='grading')
      .sort((a,b)=>a.sch.getTime()-b.sch.getTime());
    return fut.length?fut[0]:null;
  }catch(e){ return null; }
}
/* 1-day-left reminder: local notification + bell badge (once per test) */
function _sTestReminder(e,sch){
  try{
    if(sch.getTime()-Date.now()>24*3600*1000) return;
    const key='mvs_rem_'+e.id+'_'+sch.toDateString();
    if(localStorage.getItem(key)) return;
    localStorage.setItem(key,'1');
    const list=JSON.parse(localStorage.getItem('mvs_local_notifs')||'[]');
    list.unshift({title:'Test reminder: '+(e.title||'Test'),
      message:(e.subject?e.subject+' \u00b7 ':'')+'This test is scheduled for '+spSchedFmt(sch)+' \u2014 less than a day to go. All the best with your preparation!',
      created_at:new Date().toISOString(),is_read:false});
    localStorage.setItem('mvs_local_notifs',JSON.stringify(list.slice(0,20)));
    const b=document.getElementById('s-notif-badge'); if(b){ b.style.display='flex'; b.textContent='!'; }
    toast('Reminder: "'+(e.title||'Test')+'" \u2014 less than a day to go!');
  }catch(err){}
}
/* student dashboard: "upcoming scheduled test" banner with live countdown */
function _sSchedBanner(el,up){
  try{
    el.querySelectorAll('.tx-cdbanner').forEach(x=>x.remove());   // never duplicate the banner
    if(!up||!up.sch)return;
    const e=up.e,sch=up.sch;
    const ban=document.createElement('div');
    ban.innerHTML='<div class="tx-cdbanner"><div><div class="tx-cdb-t">Upcoming scheduled test</div><div class="tx-cdb-s">'+esc(e.title||'')+(e.subject?' \u00b7 '+esc(e.subject):'')+' \u00b7 '+spSchedFmt(sch)+'</div></div><div class="tx-cdchip lg">Starts in <b data-cd="'+sch.getTime()+'">\u2026</b></div></div>';
    el.prepend(ban.firstChild);
    spCdStart();
    _sTestReminder(e,sch);
  }catch(e){}
}
/* teacher: edit title / chapter / duration / schedule */
async function examEdit(id){
  try{
    toast('Loading test\u2026');
    const d=await api('/api/teacher/exam/'+id+'/attempts');
    const ex=d.exam||{};
    const sch=spSchedOf(ex);
    showModal('Edit Test',
      `<div class="form-group"><label>Title</label><input class="form-control" id="ee-title" value="${esc(ex.title||'')}"></div>`
      +`<div class="form-group"><label>Chapter</label><input class="form-control" id="ee-ch" value="${esc(spCleanCh(ex.chapter||''))}"></div>`
      +`<div style="display:flex;gap:12px;flex-wrap:wrap"><div class="form-group" style="width:150px"><label>Duration (min)</label><input type="number" min="0" class="form-control" id="ee-dur" value="${ex.duration_min||''}" placeholder="No limit"></div>`
      +`<div class="form-group" style="flex:1;min-width:210px"><label>Schedule (students start only after this)</label><input type="datetime-local" class="form-control" id="ee-sched" value="${sch?spSchedLocal(sch):''}"></div></div>`
      +`<div class="alert alert-info">A scheduled test appears to students with a countdown — it can only be started after the scheduled time. Leave the time empty to keep the test always open.</div>`,
      `<button class="btn btn-primary" onclick="examEditSave(${id})">Save Changes</button>`);
  }catch(e){ toast(e.message,true); }
}
async function examEditSave(id){
  const sch=(val('ee-sched')||'').trim();
  const chRaw=(val('ee-ch')||'').trim();
  const body={title:val('ee-title'),chapter:(sch?(chRaw+' \u27E6S:'+sch+'\u27E7'):chRaw),duration_min:(parseInt(val('ee-dur'))||0),scheduled_at:sch||null};
  try{
    await api('/api/teacher/exam/'+id,'PATCH',body);
    closeModal(); toast('Test updated successfully.'); loadTTests();
  }catch(e){
    if(/not found|404/i.test(e.message||'')){ window._pendingEdit={id:id,body:body}; examPatchFailModal(); }
    else toast('Could not save the update: '+e.message,true);
  }
}
