/* ---- edit fallback: backend PATCH missing -> friendly chooser + recreate ---- */
function examPatchFailModal(){
  showModal('Could Not Save the Update',
  `<div class="ws-empty"><div class="big">${ic('help')}</div>
   <p><b>The Edit (PATCH) endpoint is not deployed on the server yet</b></p>
   <small>This is a <b>one-time setup</b>: paste the code from <b>mvs_backend_exam_update.py</b> at the end of the backend file <code>admin_routes.py</code> and redeploy — Edit will then always save directly.<br><br><b>For now:</b> I can save your changes as a <b>new updated test</b> — I will also try to remove the old test from the list.<br><span style="color:#b45309">Note: if this test already has student submissions, do not recreate it — old submissions will not carry over to the new copy.</span></small></div>`,
  `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="examRecreate()">Save as New Updated Test</button>`);
}
async function examRecreate(){
  const p=window._pendingEdit; if(!p){ closeModal(); return; }
  closeModal(); toast('Saving updated copy\u2026');
  try{
    let body=p.body;
    if(!body.questions){
      const d=await api('/api/teacher/exam/'+p.id+'/attempts');
      const ex=d.exam||{}; const isM=ex.test_type==='mcq';
      body.subject=body.subject||ex.subject; body.test_type=body.test_type||ex.test_type; body.medium=body.medium||ex.medium||'English';
      body.questions=(d.questions||[]).map(q=> isM?{question_text:q.question_text||'',question_text_hi:q.question_text_hi||q.question_hi||'',options:q.options||[],options_hi:q.options_hi||[],correct_option:(q.correct_option!=null?q.correct_option:(q.correct_index!=null?(q.options||[])[q.correct_index]:undefined)),explanation:q.explanation||q.expl||'',explanation_hi:q.explanation_hi||q.expl_hi||'',max_marks:q.max_marks||1,image_b64:q.image_b64||null}:{question_text:q.question_text||'',question_text_hi:q.question_text_hi||q.question_hi||'',model_answer:q.model_answer||q.model||'',model_answer_hi:q.model_answer_hi||q.model_hi||'',max_marks:q.max_marks||5,image_b64:q.image_b64||null,alt_image_b64:q.alt_image_b64||null,model_answer_image:q.model_answer_image||null});
    }
    await api('/api/teacher/exam','POST',body);
    let removed=false;
    try{ await api('/api/teacher/exam/'+p.id,'DELETE'); removed=true; }
    catch(e){ try{ await api('/api/teacher/material/'+p.id,'DELETE'); removed=true; }catch(e2){} }
    window._editExamId=null; window._pendingEdit=null;
    toast(removed?'Updated test saved — the old test was removed.':'Updated test saved. The old card may still appear in the list until the backend snippet is deployed — after that this is fully automatic.');
    loadTTests();
  }catch(e){ toast('Save failed: '+e.message,true); }
}
