/* map saved exam questions back into the create-form structure (for editing) */
function _examFormQs(qs,isM){
  return (qs||[]).map(q=>{
    if(isM){
      let ci=-1;
      if(q.correct_index!=null)ci=q.correct_index;
      else if(q.correct!=null)ci=q.correct;
      else if(q.correct_option!=null&&Array.isArray(q.options))ci=q.options.findIndex(o=>String(o).trim()===String(q.correct_option).trim());
      return {q:q.question_text||'',q_hi:q.question_text_hi||q.question_hi||'',
        opts:(Array.isArray(q.options)&&q.options.length?q.options.slice():['','','','']),
        opts_hi:(Array.isArray(q.options_hi)?q.options_hi.slice():[]),
        correct:ci>=0?ci:0,marks:q.max_marks||1,
        expl:q.explanation||q.expl||'',expl_hi:q.explanation_hi||q.expl_hi||'',
        image_b64:q.image_b64||null,alt_image_b64:q.alt_image_b64||null,_ipart:'a',_tab:'en'};
    }
    return {q:q.question_text||'',q_hi:q.question_text_hi||q.question_hi||'',
      model:q.model_answer||q.model||'',model_hi:q.model_answer_hi||q.model_hi||'',
      marks:q.max_marks||5,image_b64:q.image_b64||null,alt_image_b64:q.alt_image_b64||null,_ipart:'a',
      model_answer_image:q.model_answer_image||null,
      qtype:'general',_tab:'en'};
  });
}
