async function loadTPerformance(){
  const el=document.getElementById('t-performance-content');
  try{
    const [pf,comp]=await Promise.all([api('/api/teacher/performance'),api('/api/teacher/compliance')]);
    const cAcc=comp.band==='green'?'green':comp.band==='yellow'?'amber':'red';
    const cards=`<div class="stats-grid">${statCard('Classes Assigned',pf.classes_assigned,'calendar','indigo')}${statCard('Classes Completed',pf.classes_completed,'check','green')}${statCard('DPP Uploaded',pf.dpp_uploaded,'clipboard','amber')}${statCard('Materials Uploaded',pf.materials_uploaded,'book','purple')}${statCard('Tests Created',pf.tests_created,'edit','teal')}${statCard('Compliance %',comp.score,'check',cAcc)}</div>`;
    const max=Math.max(1,...pf.monthly.map(m=>m.count));
    const bars=pf.monthly.map(m=>{ const h=Math.round(m.count/max*100); return `<div class="bar-col"><div class="bar-val">${m.count}</div><div class="bar" style="height:${Math.max(4,h)}%"></div><div class="bar-lbl">${monthName(m.month)}</div></div>`; }).join('');
    const chart=`<div class="card"><div class="card-header"><h3>Monthly Classes Completed</h3></div><div class="card-body"><div class="bar-chart">${bars}</div></div></div>`;
    const tl=pf.recent.length?pf.recent.map(a=>`<div class="act-item"><div class="act-dot ${esc(a.type)}"></div><div><div class="act-text">${esc(a.text)}</div><div class="act-time">${esc(a.at)}</div></div></div>`).join(''):'<div class="empty-state"><p>No recent activity.</p></div>';
    const timeline=`<div class="card"><div class="card-header"><h3>Recent Activity</h3></div><div class="card-body"><div class="act-list">${tl}</div></div></div>`;
    el.innerHTML=`<div id="t-rankboard-wrap"></div>`+cards+`<div class="grid-2">${chart}${timeline}</div><div id="t-reports-wrap"></div>`;
    loadTRankBoard();
    _renderClassReports('t-reports-wrap','/api/teacher/class-reports');
  }catch(e){ el.innerHTML=errHtml(e); }
}

// Class reports + punctuality/hours analytics. Shared by the teacher Performance
// page and the admin Teacher Reports page (same renderer, same numbers).
async function _renderClassReports(wrapId, endpoint, showTeacher){
  const wrap=document.getElementById(wrapId); if(!wrap) return;
  softSpin(wrap);
  try{
    const d=await api(endpoint);
    const s=d.summary||{};
    const otCls=s.on_time_pct==null?'':(s.on_time_pct>=80?'good':(s.on_time_pct>=60?'warn':'bad'));
    const avCls=s.avg_delay==null?'':(s.avg_delay<=5?'good':(s.avg_delay<=15?'warn':'bad'));
    const stats=`<div class="rp-stats">
      <div class="rp-stat"><div class="rp-num">${s.week_hours??0}h</div><div class="rp-lbl">This Week</div></div>
      <div class="rp-stat"><div class="rp-num">${s.month_hours??0}h</div><div class="rp-lbl">This Month</div></div>
      <div class="rp-stat"><div class="rp-num ${otCls}">${s.on_time_pct==null?'\u2014':s.on_time_pct+'%'}</div><div class="rp-lbl">On Time</div></div>
      <div class="rp-stat"><div class="rp-num ${avCls}">${s.avg_delay==null?'\u2014':s.avg_delay+'m'}</div><div class="rp-lbl">Avg Delay</div></div>
    </div>`;
    const subs=(s.by_subject||[]).map(x=>`<div class="rp-sub-row"><span class="rp-sub-name">${esc(x.subject)}</span><span class="rp-hrs">${x.classes} classes \u00b7 <b>${(x.week_min/60).toFixed(1)}h</b> week \u00b7 <b>${(x.month_min/60).toFixed(1)}h</b> month</span></div>`).join('');
    const subCard=subs?`<div class="card"><div class="card-header"><h3>Teaching Hours by Subject</h3></div><div class="card-body">${subs}</div></div>`:'';
    const LBL={ontime:'On time',minor:'Slightly late',late:'Late',unknown:'\u2014'};
    const rows=(d.rows||[]).map(r=>{
      const dm=r.delay_min;
      const badge=`<span class="rp-badge ${r.delay_band}">${dm==null?LBL.unknown:(dm<=5?LBL.ontime:('+'+dm+' min'))}</span>`;
      const who=showTeacher&&r.teacher_name?` \u00b7 ${esc(r.teacher_name)}`:'';
      return `<div class="rp-row">${badge}<div class="rp-main"><div class="rp-title">${esc(r.subject)}${r.chapter?' \u00b7 '+esc(r.chapter):''}${r.part?' \u00b7 '+esc(r.part):''}</div><div class="rp-meta">${esc(r.date||'')}${who} \u00b7 slot ${esc(r.scheduled||'\u2014')} \u00b7 started ${esc(r.start_time||'\u2014')}</div></div><span class="rp-dur">${r.duration_min?Math.round(r.duration_min)+' min':'\u2014'}</span></div>`;
    }).join('');
    const list=`<div class="card"><div class="card-header"><h3>Class Reports</h3><span class="tc-count">${(d.rows||[]).length}</span></div><div class="card-body">${rows||'<div class="ws-empty"><p>No class reports yet</p><small>Reports appear here when a class is marked Done.</small></div>'}</div></div>`;
    wrap.innerHTML=stats+subCard+list;
  }catch(e){ wrap.innerHTML=errHtml(e); }
}
let _tdSub=null;
// ===== v93: doubt thread helpers (teacher / student / admin sab likh sakte hain) =====
function dbtRespHTML(r){
  const cls=r.role==='admin'?'adm':(r.role==='student'?'stu':'tch');
  const tag=r.role==='admin'?'MVS Foundation':(r.role==='student'?'Student':'Teacher');
  const ini=esc(initials(r.author_name||(r.role==='admin'?'MVS':'?')));
  const when=r.created_at?fmtDT(r.created_at):'';
  // v112: admin ka reply official MVS logo tile ke saath; teacher ka reply uski
  // real profile photo ke saath (photo na ho to initials hi rehte hain)
  const ava=r.role==='admin'
    ? `<div class="dbt-resp-ava mvs-ava">M</div>`
    : (r.role==='teacher'&&r.author_tid
      ? `<div class="dbt-resp-ava dbt-resp-photo" id="dbtrava-${r.id}" data-tid="${r.author_tid}">${ini}</div>`
      : `<div class="dbt-resp-ava">${ini}</div>`);
  return `<div class="dbt-resp ${cls}">${ava}<div class="dbt-resp-b"><div class="dbt-resp-h"><span class="dbt-resp-n">${esc(r.author_name||tag)}</span><span class="dbt-resp-tag">${tag}</span>${r.mine?'<span style="font-size:.62rem;color:var(--text-muted);font-weight:700">(You)</span>':''}</div><div class="dbt-resp-t">${_fmtRich(r.body||'')}</div>${when?`<div class="dbt-resp-w">${when}</div>`:''}</div></div>`;
}
// v112: thread avatars me teacher photos load karo (viewer role ke hisaab se endpoint)
function _dbtLoadAvas(role){
  const base=role==='teacher'?'/api/teacher/teacher/':(role==='student'?'/api/student/teacher/':'/api/admin/teacher/');
  document.querySelectorAll('.dbt-resp-photo[data-tid]').forEach(el=>{
    _loadPhotoInto(el.id, base+el.getAttribute('data-tid')+'/photo');
  });
}
function dbtThreadHTML(d){
  const rs=d.responses||[]; if(!rs.length) return '';
  return `<div class="dbt-thread">${rs.map(dbtRespHTML).join('')}</div>`;
}
function dbtReplyRow(role,id,ph){
  const iid='dbtr-'+role+'-'+id;
  return `<div class="dbt-replyrow"><input class="form-control" id="${iid}" placeholder="${ph||'Write a reply...'}" onkeydown="if(event.key==='Enter')dbtRespond('${role}',${id},'${iid}')"><button class="btn btn-primary btn-sm" onclick="dbtRespond('${role}',${id},'${iid}')">Send</button></div>`;
}
async function openStudentDoubts(sid,encName){
  const name=decodeURIComponent(encName||'')||'Student';
  if(!sid){ toast('Student not linked.',true); return; }
  showModal(esc(name)+' \u2014 Doubt History','<div class="spinner"></div>','<button class="btn btn-ghost" onclick="closeModal()">Close</button>');
  try{
    const d=await api('/api/teacher/student-doubts?student_id='+sid);
    const body=document.getElementById('modal-body');
    if(!d.doubts||!d.doubts.length){ body.innerHTML='<div class="vv-empty">Is student ne abhi tak koi doubt nahi poochha.</div>'; return; }
    body.innerHTML=`<div style="font-size:.75rem;color:var(--text-muted);margin-bottom:12px">${d.total} doubt${d.total>1?'s':''} \u00b7 newest first</div>`+
      d.doubts.map(x=>`<div class="sh-card">
        <div class="sh-head"><span class="sh-sub">${esc(x.subject||'General')}${x.topic?' \u00b7 '+esc(x.topic):''}</span><span class="dbt-pill ${x.status==='resolved'?'res':'open'}" style="font-size:.62rem">${x.status==='resolved'?'\u2713 Resolved':'Pending'}</span></div>
        <div class="sh-q">${_fmtRich(x.question||'')}</div>
        ${x.answer?`<div class="sh-a"><b>Answer:</b> ${_fmtRich(x.answer)}</div>`:'<div class="sh-noans">Not answered yet</div>'}
        <div class="sh-meta">${esc(fmtDT(x.created_at))}${x.owner?' \u00b7 '+esc(x.owner):''}${x.mine?' \u00b7 <b>you</b>':''}</div>
      </div>`).join('');
  }catch(e){ document.getElementById('modal-body').innerHTML=errHtml(e); }
}
async function dbtRespond(role,id,iid){
  const inp=document.getElementById(iid); const body=(inp?inp.value:'').trim();
  if(!body){ toast('Please write a reply first.',true); return; }
  try{
    await api('/api/'+role+'/doubts/'+id+'/respond','POST',{body});
    toast('Reply added.');
    if(role==='teacher') loadTDoubts(); else if(role==='student') loadSDoubts(); else loadADoubts();
  }catch(e){ toast(e.message,true); }
}
async function tAssignDoubt(id){
  const sel=document.getElementById('dbt-as-'+id);
  const target=sel?sel.value:'';
  if(!target){ toast('Choose who should take this doubt.',true); return; }
  const name=(sel.options[sel.selectedIndex]||{}).text||'';
  if(!confirm('Reassign this doubt to '+name+'?\n\nFrom your side this doubt will be treated as handed over — resolving it becomes their responsibility.')) return;
  try{
    const r=await api('/api/teacher/doubts/'+id+'/assign','POST',{target:target==='admin'?'admin':parseInt(target,10)});
    toast(r.message||'Doubt assigned.'); loadTDoubts();
  }catch(e){ toast(e.message,true); }
}
function tAssignRow(d){
  const tg=window._tDoubtTargets||{teachers:[],admin:true};
  if(!tg.teachers.length&&!tg.admin) return '';
  const opts=tg.teachers.map(t=>`<option value="${t.id}">${esc(t.name)}${(t.subjects||[]).length?' — '+esc(t.subjects.join(', ')):''}</option>`).join('')
    +(tg.admin?`<option value="admin">MVS Foundation (Admin)</option>`:'');
  return `<div class="dbt-assign-row"><span style="font-size:.74rem;font-weight:800;color:#4f46e5;white-space:nowrap">Can't answer?</span><select class="form-control" id="dbt-as-${d.id}"><option value="" selected disabled>Reassign this doubt to…</option>${opts}</select><button class="btn btn-warning btn-sm" onclick="tAssignDoubt(${d.id})">Assign</button></div>`;
}

async function loadTDoubts(){
  const el=document.getElementById('t-doubts-content');
  try{
 const doubts=await api('/api/teacher/doubts');
 let ds={pending:0,resolved:0,avg_response_minutes:null}; try{ ds=await api('/api/teacher/doubt-stats'); }catch(e){}
 try{ window._tDoubtTargets=await api('/api/teacher/doubts-assign-targets'); }catch(e){ window._tDoubtTargets={teachers:[],admin:false}; }
 window._tDoubts=doubts; window._tDoubtStats=ds;
 const b=document.getElementById('t-doubt-badge'); if(b){ b.textContent=ds.pending||0; b.style.display=(ds.pending||0)>0?'':'none'; }
 tRenderDoubts();
  }catch(e){ el.innerHTML=errHtml(e); }
}
function tRenderDoubts(){
  const el=document.getElementById('t-doubts-content');
  const doubts=window._tDoubts||[]; const ds=window._tDoubtStats||{pending:0,resolved:0,avg_response_minutes:null};
  const avgTxt=ds.avg_response_minutes==null?'\u2014':(ds.avg_response_minutes>=60?(Math.floor(ds.avg_response_minutes/60)+'h '+(ds.avg_response_minutes%60)+'m'):ds.avg_response_minutes+' min');
  let html=`<div class="stats-grid">${statCard('Pending Doubts',ds.pending,'help','amber')}${statCard('Resolved Doubts',ds.resolved,'check','green')}${statCard('Avg Response Time',avgTxt,'clipboard','indigo')}</div>`;
  if(_tdSub===null){
    // ---- SUBJECT CARDS VIEW ----
    html+=toppersHTML(doubts,'ttop',false);
    const bySub={}; doubts.forEach(d=>{ const k=d.subject||'Other'; (bySub[k]=bySub[k]||{total:0,pending:0}); bySub[k].total++; if((d.status!=='resolved'||d.needs_attention)&&!d.assigned_away) bySub[k].pending++; });
    const subs=Object.keys(bySub).sort();
    if(!subs.length) html+=`<div class="card"><div class="card-body"><div class="empty-state"><div class="empty-icon"></div><p>No doubts yet.</p></div></div></div>`;
    else html+=`<div class="xm-grid">`+subs.map(sub=>{
      const g=bySub[sub];
      return `<div class="xm-card" onclick="tPickDoubtSub('${esc(sub).replace(/'/g,"\\'")}')"><div class="xm-ic">${ic('help')}</div><div class="xm-info"><div class="xm-title">${esc(sub)}</div><div class="xm-chips"><span class="xm-chip">${g.total} total</span>${g.pending?`<span class="xm-pend">${g.pending} pending</span>`:`<span class="xm-chip" style="background:rgba(5,150,105,.14);color:var(--success)">All clear</span>`}</div></div><div class="xm-arw">\u203a</div></div>`;
    }).join('')+`</div>`;
    el.innerHTML=html; return;
  }
  // ---- SUBJECT DRILL VIEW (sectioned: Pending upar, Resolved neeche, Reassigned alag) ----
  const list=doubts.filter(d=>(d.subject||'Other')===_tdSub);
  const away=list.filter(d=>d.assigned_away);
  const pend=list.filter(d=>(d.status!=='resolved'||d.needs_attention)&&!d.assigned_away), done=list.filter(d=>d.status==='resolved'&&!d.assigned_away&&!d.needs_attention);
  html+=`<div style="display:flex;align-items:center;gap:12px;margin-bottom:6px;flex-wrap:wrap"><button class="btn btn-ghost btn-sm" onclick="_tdSub=null;tRenderDoubts()">\u2190 All Subjects</button><h3 style="margin:0">${esc(_tdSub)} <span style="color:var(--text-muted);font-weight:600;font-size:.85rem">(${list.length})</span></h3></div><div class="hide-scroll doubt-drill">`;
  const mediaOf=d=>`${d.has_voice?`<button class="btn btn-ghost btn-sm" onclick="playDoubtVoice(this,'/api/teacher/doubt/${d.id}/voice')">${ic('play')} Voice Note</button>`:''}${d.has_image?doubtAttachHtml('teacher',d.id,d.attach_mime,d.attach_name,false):''}`;
  const headOf=(d,pill)=>`<div class="dbt-head"><div style="min-width:0"><div class="dbt-name dbt-name-link" title="View all doubts by this student" onclick="event.stopPropagation();openStudentDoubts(${d.student_id||0},'${encodeURIComponent(d.student_name||'Student')}')">${esc(d.student_name||'Student')}</div><div class="dbt-meta">${esc(d.subject)}${d.topic?' \u2014 '+esc(d.topic):''}${d.created_at?' \u00b7 '+esc(fmtDT(d.created_at)):''}</div></div><div class="dbt-badges">${pill}</div></div>`;
  let rows='';
  if(pend.length){
    rows+=`<div class="dbt-sec">Pending (${pend.length})</div>`;
    rows+=pend.map(d=>{
      const media=mediaOf(d);
      const amedia=`${d.has_answer_voice?`<button class="btn btn-ghost btn-sm" onclick="playDoubtVoice(this,'/api/teacher/doubt/${d.id}/answer-voice')">${ic('play')} Your Voice Answer</button>`:''}${d.has_answer_file?doubtAttachHtml('teacher',d.id,d.answer_attach_mime,d.answer_attach_name,true):''}`;
      return `<div class="dbt-card pend">${headOf(d,(d.needs_attention&&d.status==='resolved')?'<span class="dbt-pill open">New Follow-up</span>':'<span class="dbt-pill open">Pending</span>')}<div class="dbt-q" id="tdq-${d.id}">${_fmtRich(d.question||'')}</div>${media?`<div class="dbt-media">${media}</div>`:''}${d.answer?`<div class="dbt-a"><b>Your answer:</b> <span id="tda-${d.id}">${_fmtRich(d.answer)}</span></div>`:''}${amedia?`<div class="dbt-media">${amedia}</div>`:''}${dbtThreadHTML(d)}<div style="margin-top:12px">${composerHTML('ta'+d.id,'Write your answer\u2026 or send a voice note / file','resolveDoubt('+d.id+')','Resolve')}</div>${tAssignRow(d)}</div>`;
    }).join('');
  }
  if(done.length){
    rows+=`<div class="dbt-sec">Resolved (${done.length})</div>`;
    rows+=done.map(d=>{
      const media=mediaOf(d);
      const amedia=`${d.has_answer_voice?`<button class="btn btn-ghost btn-sm" onclick="playDoubtVoice(this,'/api/teacher/doubt/${d.id}/answer-voice')">${ic('play')} Your Voice Answer</button>`:''}${d.has_answer_file?doubtAttachHtml('teacher',d.id,d.answer_attach_mime,d.answer_attach_name,true):''}`;
      return `<div class="dbt-card res">${headOf(d,'<span class="dbt-pill res">\u2713 Resolved</span>')}<div class="dbt-q" id="tdq-${d.id}">${_fmtRich(d.question||'')}</div>${media?`<div class="dbt-media">${media}</div>`:''}${d.answer?`<div class="dbt-a"><b>Your answer:</b> <span id="tda-${d.id}">${_fmtRich(d.answer)}</span></div>`:''}${amedia?`<div class="dbt-media">${amedia}</div>`:''}${dbtThreadHTML(d)}<div style="margin-top:10px"><button class="btn btn-danger btn-sm" title="Delete your response — the doubt moves back to Pending" onclick="tDelDoubtAnswer(${d.id})">${ic('trash')} Delete Response</button></div></div>`;
    }).join('');
  }
  if(away.length){
    rows+=`<div class="dbt-sec">Reassigned — Handed Over (${away.length})</div>`;
    rows+=away.map(d=>{
      const owner=d.assigned_to_name||'the new owner';
      const st=(d.status==='resolved')?'<span class="dbt-pill res">\u2713 Resolved</span>':'<span class="dbt-pill open">Pending</span>';
      return `<div class="dbt-away">${headOf(d,`<span class="dbt-pill away">Reassigned \u2192 ${esc(owner)}</span>`)}<div class="dbt-q" id="tdq-${d.id}">${_fmtRich(d.question||'')}</div>${dbtThreadHTML(d)}<div style="font-size:.72rem;color:var(--text-muted);margin-top:8px">Handed over by you ${st} — resolving this doubt is now <b>${esc(owner)}</b>'s responsibility.</div></div>`;
    }).join('');
  }
  html+=(rows||`<div class="empty-state"><p>No doubts in this subject.</p></div>`)+`</div>`;
  el.innerHTML=html;
  loadDoubtThumbs(el);   // v69 — image attachments ke inline previews
  _dbtLoadAvas('teacher');   // v112 — thread me teacher photos
  // KaTeX math render ($..$) — DPP questions ke formulas sahi dikhenge
  list.forEach(d=>{
    const q=document.getElementById(`tdq-${d.id}`); if(q) renderMath(q);
    const a=document.getElementById(`tda-${d.id}`); if(a) renderMath(a);
  });
}
function tPickDoubtSub(sub){ _tdSub=sub; tRenderDoubts(); }
async function tDelDoubtAnswer(id){
  if(!confirm('Delete your response?\n\nThe doubt will move back to Pending and the student will no longer see your answer.')) return;
  try{ await api('/api/teacher/doubt/'+id+'/answer','DELETE'); toast('Response deleted — doubt is pending again.'); loadTDoubts(); }
  catch(e){ toast(e.message||'Delete failed',true); }
}
async function viewDoubtImage(id){ viewDoubtFile('teacher',id,'image/jpeg'); }
async function resolveDoubt(id){
  const key='ta'+id; const st=_cmpState[key]||{};
  const answer=(document.getElementById('cmpt-'+key)||{}).value?.trim()||'';
  if(!answer&&!st.voice&&!st.file){ toast('Please write an answer, record a voice answer or attach a file.',true); return; }
  const btn=document.getElementById('cmps-'+key); if(btn){ btn.disabled=true; btn.textContent='Sending...'; }
  try{
    let ab=null, fb=null, fmime=null, fname=null;
    if(st.voice) ab=await blobToB64(st.voice);
    if(st.file){
      let f=st.file;
      if((f.type||'').startsWith('image/')){
        try{ const _r=await Promise.race([smartCompress(f,()=>{}),new Promise(r=>setTimeout(()=>r(null),12000))]); if(_r&&_r.ok&&_r.file) f=_r.file; }catch(e){}
      }
      if(f.size>15*1024*1024){ toast('Answer attachment is larger than 15MB.',true); if(btn){btn.disabled=false;btn.textContent='Resolve';} return; }
      fb=await blobToB64(f); fmime=f.type||'application/octet-stream'; fname=f.name||'attachment';
    }
    await api(`/api/teacher/doubts/${id}/resolve`,'PATCH',{answer:answer||'(voice answer)',answer_image_link:null,answer_audio_b64:ab,answer_attach_b64:fb,answer_attach_mime:fmime,answer_attach_name:fname});
    delete _cmpState[key];
    toast('Doubt resolved.'); loadTDoubts();
  }catch(e){ toast(e.message,true); if(btn){btn.disabled=false;btn.textContent='Resolve';} }
}
function viewAnswerFile(role,id,mime,name){
  fetch(API+'/api/'+role+'/doubt/'+id+'/answer-file',{headers:{Authorization:'Bearer '+TOKEN}}).then(r=>{ if(!r.ok) throw 0; return r.blob(); }).then(b=>{
    const url=URL.createObjectURL(b);
    if((mime||'').startsWith('image/')) openImageViewerSrc(url,_dlName(name,b.type));
    else window.open(url,'_blank');
  }).catch(()=>toast('Attachment not found.',true));
}
function toppersHTML(doubts,idPrefix,withPhone){
  const by={};
  doubts.forEach(d=>{ const k=(d.student_name||'Student')+(withPhone&&d.student_phone?('|'+d.student_phone):''); (by[k]=by[k]||{name:d.student_name||'Student',phone:d.student_phone||'',total:0,pending:0}); by[k].total++; if(d.status!=='resolved') by[k].pending++; });
  const rows=Object.values(by).sort((a,b)=>b.total-a.total).slice(0,15);
  if(!rows.length) return '';
  const inner=rows.map((r,i)=>`<div class="topper-row"><div class="rank-b ${i<3?'rank-'+(i+1):''}">${i+1}</div><div class="topper-name">${esc(r.name)}${withPhone&&r.phone?`<div class="topper-sub">${esc(r.phone)}</div>`:''}</div><span class="xm-chip">${r.total} doubts</span>${r.pending?`<span class="xm-pend">${r.pending} pending</span>`:''}</div>`).join('');
  return `<div class="card" style="margin-bottom:16px"><div class="card-header" style="cursor:pointer" onclick="const b=document.getElementById('${idPrefix}-tops');const c=document.getElementById('${idPrefix}-chev');const o=b.style.display!=='none';b.style.display=o?'none':'block';c.classList.toggle('open',!o)"><h3 style="display:flex;align-items:center;gap:10px">${ic('users')} Most Active Students <span style="font-size:.72rem;color:var(--text-muted);font-weight:600">(by doubts asked \u2014 tap to view)</span></h3><span class="chev" id="${idPrefix}-chev">\u25bc</span></div><div class="card-body hide-scroll" id="${idPrefix}-tops" style="display:none;max-height:295px">${inner}</div></div>`;
}

async function loadTReschedule(){
  const el=document.getElementById('t-reschedule-content');
  try{
 const rs=await api('/api/teacher/reschedule');
 let html=`<div class="card"><div class="card-header"><h3> Reschedule History</h3></div><div class="card-body"><div class="table-wrap"><table><thead><tr><th>Original</th><th>New</th><th>Reason</th><th>Status</th></tr></thead><tbody>`;
 if(rs.length===0) html+=`<tr><td colspan="4" style="text-align:center;color:var(--text-muted)">No reschedules</td></tr>`;
 rs.forEach(r=>{ const st=r.status==='approved'?'tag-done':(r.status==='rejected'?'tag-reschedule':'tag-pending'); html+=`<tr><td>${r.original_date} ${r.original_time}</td><td>${r.new_date} ${r.new_time}</td><td>${esc(r.reason)}</td><td><span class="tag ${st}">${r.status}</span></td></tr>`; });
 html+=`</tbody></table></div></div></div>`;
 el.innerHTML=html;
  }catch(e){ el.innerHTML=errHtml(e); }
}

// ===== v93: teacher notifications — Sent by Me (views tracking) =====
async function loadTNotif(){
  const el=document.getElementById('t-notif-content');
  softSpin(el);
  let log=[]; try{ log=await api('/api/teacher/notify-log'); }catch(e){}
  await loadNotif('/api/teacher/notifications','t-notif-content');
  if(log.length){
    const sentHtml=`<div class="card" style="margin-bottom:16px"><div class="card-header"><h3> Sent by Me <span style="font-size:.72rem;color:var(--text-muted);font-weight:600">— tap Views to see exactly who read it</span></h3></div><div class="card-body">`+
      log.map(b=>`<div class="ntlog-row"><div class="ntlog-ic"></div><div style="min-width:0;flex:1"><div style="font-weight:800;font-size:.88rem">${esc(b.title)}</div><div style="font-size:.74rem;color:var(--text-muted);margin-top:2px">${esc(b.label)} \u00b7 ${b.sent} recipient${b.sent===1?'':'s'}${b.created_at?' \u00b7 '+new Date(b.created_at).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):''}</div></div><div class="ntlog-views" onclick="openNtViews('${b.batch_key}')" title="See who viewed"><div class="nv-n">${b.viewed}/${b.sent}</div><div class="nv-t">Views</div></div></div>`).join('')+`</div></div>`;
    el.insertAdjacentHTML('afterbegin',sentHtml);
  }
}
async function openNtViews(batch){
  showModal(' Notification Views','<div class="spinner"></div>','');
  let d; try{ d=await api('/api/teacher/notify-log/'+batch); }catch(e){ showModal(' Notification Views',errHtml(e)); return; }
  const recips=d.recipients||[];
  const seen=recips.filter(r=>r.read).length, total=recips.length;
  const rows=recips.map(r=>`<div class="ntv-row"><div class="ntv-ava">${esc(initials(r.name))}</div><div style="min-width:0;font-weight:700;font-size:.86rem">${esc(r.name)}</div>${r.read?`<div class="ntv-seen">\u2713 Viewed${r.read_at?' \u00b7 '+new Date(r.read_at).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):''}</div>`:'<div class="ntv-pend">Not viewed yet</div>'}</div>`).join('');
  showModal(' Notification Views',
   `<div class="ntf-scope"><div class="ns-n">${seen}/${total}</div><div class="ns-t"><b>${esc(d.title||'Notification')}</b><br>${esc(d.label||'')} \u2014 ${seen} of ${total} student${total===1?'':'s'} have viewed it.</div></div><div class="hide-scroll" style="max-height:320px;overflow:auto">${rows||'<div class="empty-state"><p>No recipients.</p></div>'}</div>`,
   `<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
}

