/* ===== v94: restricted sub-admin access (frontend) ===== */
window._adminMe=null;
async function fetchAdminMe(){
  try{
    const me=await api('/api/admin/me');
    window._adminMe=(me&&typeof me==='object'&&!Array.isArray(me)&&me.full_access===false)?me:{full_access:true};
  }catch(e){ window._adminMe={full_access:true}; }
  applyAdminAccess();
}
function adminAllowed(page){
  const me=window._adminMe;
  if(!me||me.full_access) return true;
  const secs=me.sections||[];
  if(page==='dpptracker') return secs.includes('tests')||secs.includes('dpptracker');
  return secs.includes(page);
}
function applyAdminAccess(){
  document.querySelectorAll('#admin-app .nav-item').forEach(n=>{ n.style.display=''; });
  document.querySelectorAll('#admin-app .nav-section').forEach(s=>{ s.style.display=''; });
  const me=window._adminMe;
  if(!me||me.full_access) return;
  document.querySelectorAll('#admin-app .nav-item').forEach(n=>{
    const oc=n.getAttribute('onclick')||'';
    const m=oc.match(/aPage\('([^']+)'/);
    if(m){ if(!adminAllowed(m[1])) n.style.display='none'; return; }
    if(oc.includes('openAdminNotify')&&!adminAllowed('notify')) n.style.display='none';
  });
  document.querySelectorAll('#admin-app .nav-section').forEach(s=>{
    let vis=false, el=s.nextElementSibling;
    while(el&&el.classList.contains('nav-item')){
      if(el.style.display!=='none'){ vis=true; break; }
      el=el.nextElementSibling;
    }
    s.style.display=vis?'':'none';
  });
}
function openAdmin(){
  try{_saveSession();}catch(e){}
  document.getElementById('admin-app').classList.add('active');
  try{ initAdminDppTracker(); }catch(e){}
  try{ initNavCollapse(); }catch(e){}
  try{ initNavAccordion(); }catch(e){}   // ek fail ho to bhi accordion chale (sections band)
  [400,1200].forEach(function(d){ setTimeout(function(){ try{ document.querySelectorAll('.app .sidebar-nav').forEach(function(nav){ if(typeof _accGroupClose==='function') _accGroupClose(nav,false); }); }catch(e){} }, d); });
  setTimeout(function(){ try{ _preloadAdmin(); }catch(e){} }, 800);
  document.getElementById('a-name').textContent=NAME;
  document.getElementById('a-avatar').textContent=initials(NAME);
  document.querySelectorAll('#admin-app .nav-item').forEach(n=>n.classList.remove('active'));
  document.querySelector('#admin-app .nav-item').classList.add('active');
  window._adminMe=null;
  fetchAdminMe();
  aPage('dashboard',null);
  startHeartbeat();
  notifPopupOnOpen('admin');
  startDoubtBadge('admin');
  startAdminLivePoll();
}
async function loadACompliance(){
  const el=document.getElementById('a-compliance-content');
  softSpin(el);
  try{
    const d=await api('/api/admin/class-compliance');
    const t=d.totals||{};
    const cards=`<div class="stats-grid">${statCard('Missed Classes',t.missed||0,'shield',(t.missed?'red':'green'))}${statCard('Late Starts',t.late||0,'refresh',(t.late?'amber':'green'))}${statCard('Teachers At Risk',t.at_risk||0,'users',(t.at_risk?'red':'green'))}</div>`;
    const teachers=(d.teachers||[]).map(x=>{
      const band=x.on_time_pct==null?'unknown':(x.on_time_pct>=80?'ontime':(x.on_time_pct>=60?'minor':'late'));
      const warn=x.at_risk?`<button class="btn btn-danger btn-sm" onclick="warnTeacher(${x.teacher_id},'${esc(x.name).replace(/'/g,'')}')">${ic('bell')} Send Reminder</button>`:'';
      return `<div class="rp-row"><span class="rp-badge ${band}">${x.on_time_pct==null?'\u2014':x.on_time_pct+'% on time'}</span><div class="rp-main"><div class="rp-title">${esc(x.name)}${x.at_risk?' <span class="dp-tag pending">At risk</span>':''}</div><div class="rp-meta">${esc((x.subjects||[]).join(', '))} \u00b7 ${x.classes_done} done \u00b7 <b>${x.missed}</b> missed \u00b7 <b>${x.late_this_month}</b> late this month${x.avg_delay!=null?' \u00b7 avg +'+x.avg_delay+'m':''}</div></div>${warn}</div>`;
    }).join('');
    const missed=(d.missed||[]).map(m=>`<div class="rp-row"><span class="rp-badge late">Missed</span><div class="rp-main"><div class="rp-title">${esc(m.subject)}${m.chapter?' \u00b7 '+esc(m.chapter):''}${m.part?' \u00b7 '+esc(m.part):''}</div><div class="rp-meta">${esc(m.teacher_name)} \u00b7 ${esc(m.date)} (${m.days_ago}d ago) \u00b7 slot ${esc(m.slot||'\u2014')}</div></div></div>`).join('');
    const late=(d.late||[]).map(m=>`<div class="rp-row"><span class="rp-badge ${m.band}">+${m.delay_min} min</span><div class="rp-main"><div class="rp-title">${esc(m.subject)}${m.chapter?' \u00b7 '+esc(m.chapter):''}</div><div class="rp-meta">${esc(m.teacher_name)} \u00b7 ${esc(m.date)} \u00b7 slot ${esc(m.slot||'\u2014')} \u00b7 started ${esc(m.started||'\u2014')}</div></div></div>`).join('');
    el.innerHTML=`<div class="sm-head"><h2>Class Compliance</h2><p>Missed classes and late starts, teacher-wise. Teachers with more than ${d.threshold} late starts a month are reminded automatically.</p></div>${cards}
      <div class="card"><div class="card-header"><h3>Teachers</h3></div><div class="card-body">${teachers||'<div class="ws-empty"><p>No data yet</p></div>'}</div></div>
      <div class="card"><div class="card-header"><h3>Missed Classes</h3><span class="tc-count">${(d.missed||[]).length}</span></div><div class="card-body"><div class="lu-scroll">${missed||'<div class="ws-empty"><div class="big">\u2705</div><p>No missed classes</p></div>'}</div></div></div>
      <div class="card"><div class="card-header"><h3>Late Starts</h3><span class="tc-count">${(d.late||[]).length}</span></div><div class="card-body"><div class="lu-scroll">${late||'<div class="ws-empty"><div class="big">\u23f0</div><p>All classes started on time</p></div>'}</div></div></div>`;
  }catch(e){ el.innerHTML=errHtml(e); }
}
async function warnTeacher(id,name){
  if(!confirm('Send the punctuality reminder to '+name+'?')) return;
  try{ const r=await api('/api/admin/warn-teacher/'+id,'POST'); toast(r.message); }
  catch(e){ toast(e.message,true); }
}
let _luTab='live';
async function luTab(t){ _luTab=t;
  if(t==='offline'||t==='never'){
    try{ const f=await api('/api/admin/live-users?full=1'); window._luFull={offline:f.offline||[],never:f.never||[]}; if(window._lastLive&&f.counts) window._lastLive.counts=f.counts; }catch(e){}
  }
  if(window._lastLive) _paintLive(window._lastLive); else loadALive();
}
async function loadALive(){
  const el=document.getElementById('a-live-content');
  if(!el.dataset.painted) softSpin(el);
  try{ const d=await api('/api/admin/live-users'); window._lastLive=d; _paintLive(d); }
  catch(e){ el.innerHTML=errHtml(e); }
}
function _luRow(u,tab){
  const badge=u.role==='teacher'?'<span class="lu-role t">Teacher</span>':(u.role==='admin'?'<span class="lu-role a">Admin</span>':'<span class="lu-role s">Student</span>');
  let right='';
  if(tab==='live') right=`<div class="lu-right"><span class="lu-page">${esc(u.page||'')}</span><span class="lu-dur">${u.duration_min}m</span></div>`;
  else if(tab==='offline') right=`<div class="lu-right"><span class="lu-dim">${u.last_seen_min<60?u.last_seen_min+'m ago':Math.floor(u.last_seen_min/60)+'h ago'}</span></div>`;
  else right=`<div class="lu-right">${u.phone?`<a class="btn btn-ghost btn-sm" href="tel:${esc(u.phone)}" onclick="event.stopPropagation()">${ic('bell')} Call</a>`:''}</div>`;
  return `<div class="lu-row" onclick="openUserSessions(${u.user_id})"><span class="lu-dot ${tab==='live'?'on':''}"></span><div class="lu-main"><div class="lu-name">${esc(u.name)} ${badge}</div><div class="lu-meta">${esc(u.code||'')}${u.phone?' \u00b7 '+esc(u.phone):''} \u00b7 ${u.logins} login${u.logins===1?'':'s'}</div></div>${right}</div>`;
}
function _luSection(title,list,tab,emptyMsg){
  const rows=list.length?list.map(u=>_luRow(u,tab)).join(''):`<div class="ws-empty"><p>${emptyMsg}</p></div>`;
  return `<div class="card"><div class="card-header"><h3>${title}</h3><span class="tc-count">${list.length}</span></div><div class="card-body"><div class="lu-scroll">${rows}</div></div></div>`;
}
function _paintLive(d){
  const el=document.getElementById('a-live-content'); if(!el) return;
  const c=d.counts||{};
  const list=(_luTab==='live')?(d.live||[]):((window._luFull&&window._luFull[_luTab])||[]);
  const students=list.filter(u=>u.role==='student');
  const teachers=list.filter(u=>u.role==='teacher');
  const admins=list.filter(u=>u.role==='admin');
  const cards=`<div class="stats-grid">${statCard('Online Now',c.live||0,'user','green')}${statCard('Students Live',c.students_live||0,'users','indigo')}${statCard('Teachers Live',c.teachers_live||0,'user','teal')}${statCard('Admins Live',c.admins_live||0,'shield','amber')}${statCard('Never Logged In',c.never||0,'shield','amber',"luTab('never')")}</div>`;
  const tabs=`<div class="tt-tabs"><button class="tt-tab ${_luTab==='live'?'active':''}" onclick="luTab('live')">Online (${c.live||0})</button><button class="tt-tab ${_luTab==='offline'?'active':''}" onclick="luTab('offline')">Recent (${c.offline||0})</button><button class="tt-tab ${_luTab==='never'?'active':''}" onclick="luTab('never')">Never Logged In (${c.never||0})</button></div>`;
  const em={live:['No admins online right now.','No teachers online right now.','No students online right now.'],
            offline:['No recent admin sessions.','No recent teacher sessions.','No recent student sessions.'],
            never:['\u2705 All admins have logged in.','\u2705 All teachers have logged in.','\u2705 All students have logged in.']}[_luTab];
  const body=`<div class="ws-grid-3 lu3">${_luSection('Admins',admins,_luTab,em[0])}${_luSection('Teachers',teachers,_luTab,em[1])}${_luSection('Students',students,_luTab,em[2])}</div>`;
  el.dataset.painted='1';
  el.innerHTML=`<div class="sm-head" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px"><div><h2>Live Users</h2><p>Admins, teachers and students shown separately \u2014 who is online, what they are doing, and who never logs in.</p></div><span class="pager-info">Auto-refreshes every 15s</span></div>${cards}${tabs}${body}`;
}

async function openUserSessions(uid){
  showModal('User Details','<div id="us-body"><div class="spinner"></div></div>','<button class="btn btn-ghost" onclick="closeModal()">Close</button>');
  try{
    const d=await api('/api/admin/user/'+uid+'/sessions');
    const det=d.detail||{};
    const roleBadge=d.role==='teacher'?'<span class="lu-role t">Teacher</span>':(d.role==='admin'?'<span class="lu-role a">Admin</span>':'<span class="lu-role s">Student</span>');
    // full detail grid — batch, phone, class, medium, subjects (jo bhi available ho)
    const cells=[];
    const add=(k,v,lnk)=>{ if(v!=null&&String(v).trim()!=='') cells.push(`<div class="prof-cell"><div class="prof-k">${k}</div><div class="prof-v">${lnk?lnk:esc(String(v))}</div></div>`); };
    add('Batch',det.batch);
    add('Phone',det.phone,det.phone?`<a href="tel:${esc(det.phone)}" style="color:var(--primary);font-weight:700">${esc(det.phone)}</a>`:null);
    add('Class',det.class_name||(det.class_level?('Class '+det.class_level):''));
    add('Medium',det.medium);
    add('Subjects',(det.subjects||[]).join(', '));
    add('Email',det.email);
    const detHtml=cells.length?`<div class="prof-grid" style="margin-bottom:14px">${cells.join('')}</div>`:'';
    const rows=(d.sessions||[]).length?d.sessions.map(s=>`<div class="us-row"><div class="us-main"><div class="us-when">${esc(s.started)}</div><div class="us-page">${esc(s.page)}</div></div><span class="us-dur">${s.minutes}m</span></div>`).join(''):'<div class="ws-empty"><p>No sessions recorded yet</p></div>';
    document.getElementById('us-body').innerHTML=`<div class="alert alert-info" style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><strong>${esc(d.name)}</strong> ${roleBadge} <span style="color:var(--text-muted)">${esc(d.code||'')} \u00b7 Logged in <strong>${d.logins}</strong> time${d.logins===1?'':'s'}</span></div>${detHtml}<div style="font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text-muted);margin:2px 0 6px">Login History</div><div class="us-scroll">${rows}</div>`;
  }catch(e){ document.getElementById('us-body').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`; }
}

function aPage(page,el){
  if(!adminAllowed(page)){ toast('You do not have access to this section.',true); return; }
  navPush('admin-app',page);
  document.querySelectorAll('#admin-app .page').forEach(p=>p.classList.remove('active'));
  document.getElementById('a-page-'+page).classList.add('active');
  if(!el){ document.querySelectorAll('#admin-app .nav-item').forEach(n=>{ if((n.getAttribute('onclick')||'').includes("'"+page+"'")) el=n; }); }
  if(el){ document.querySelectorAll('#admin-app .nav-item').forEach(n=>n.classList.remove('active')); el.classList.add('active'); }
  const titles={dashboard:'Dashboard',approvals:'Approvals',teachers:'Teachers',tranks:'Teacher Ranking',vtasks:'Task Manager',urgent:'Urgent Videos',students:'Students',admins:'Admin Users',subjects:'Subjects',syllabus:'Syllabus Manager',timetable:'Time Table',counts:'Student Count',live:'Live Users',compliance:'Class Compliance',material:'Classes Material',qbank:'Study Material',tests:'Tests Tracker',dpptracker:'DPP Tracker',attendance:'Teacher Attendance',payouts:'Payouts'};
  _setPage(titles[page]||page);
  document.getElementById('a-title').textContent=titles[page]||page;
  _curLoader=function(){ _aLoadPage(page); };
  _aLoadPage(page);
}
function _aLoadPage(page){
  if(page==='dashboard') loadADashboard();
  else if(page==='dpptracker') loadADppTracker();
  else if(page==='vtasks') loadAVTasks();
  else if(page==='urgent') loadAUrgent();
  else if(page==='approvals') loadAApprovals();
  else if(page==='material') loadAMaterial();
  else if(page==='compliance') loadACompliance();
  else if(page==='reports') loadAReports();
  else if(page==='teachers') loadATeachers();
  else if(page==='tranks') loadATeacherRanks();
  else if(page==='doubts') loadADoubts();
  else if(page==='tests') loadATests();
  else if(page==='qbank') loadAQBank();
  else if(page==='live') loadALive();
  else if(page==='students') loadAStudents();
  else if(page==='admins') loadAAdmins();
  else if(page==='syllabus') loadASyllabus();
  else if(page==='subjects') loadASubjects();
  else if(page==='counts') loadACounts();
  else if(page==='timetable') loadATimetable();
  else if(page==='attendance') loadAAttendance();
  else if(page==='payouts') loadAPayouts();
}

/* ================= VIDEO TASK MANAGER (teacher) ================= */
let _tvtTimer=null;
async function loadTVTasks(){
  const el=document.getElementById('t-vtasks-content');
  softSpin(el);
  if(_tvtTimer){ clearInterval(_tvtTimer); _tvtTimer=null; }
  try{
    const d=await api('/api/teacher/video-tasks/my');
    const tasks=d.tasks||[];
    window._tvtMap={}; tasks.forEach(t=>window._tvtMap[t.id]=t);
    (d.special||[]).forEach(t=>window._tvtMap[t.id]=t);
    const active=tasks.filter(t=>t.status==='assigned'||t.status==='reshoot'||t.status==='rejected');
    const badge=document.getElementById('t-vt-badge');
    if(badge){ badge.style.display=active.length?'inline-block':'none'; badge.textContent=active.length; }
    const nxt=d.next_deadline;
    const hero=nxt?`
      <div class="vt-hero"><div><h3>${esc(nxt.title)}</h3><p>${nxt.video_type?esc(nxt.video_type)+' · ':''}${nxt.channel?esc(nxt.channel)+' · ':''}Deadline: ${esc(nxt.deadline_nice)}</p></div><div class="vt-sp"></div>
        <div class="vt-count" id="tvt-hero-cd" data-secs="${nxt.seconds_left||0}"></div></div>`:'';
    const st=d.stats||{};
    const stat=(l,n,color,icn,bucket)=>`<div class="vt-stat${bucket?' vt-stat-click':''}"${bucket?` data-bucket="${bucket}" onclick="_vtBucketFilter('${bucket}')"`:''}><div class="vs-ic" style="background:${color}1f;color:${color}">${ic(icn)}</div><div><div class="vs-n" style="color:${color}">${n}</div><div class="vs-l">${l}</div></div></div>`;
    const statCards=`<div class="vt-cards">
      ${stat('Assigned',st.assigned||0,'#8a6d10','clipboard')}
      ${stat('Uploaded',st.uploaded||0,'#059669','check')}
      ${stat('Pending',st.pending||0,'#0891b2','clock')}
      ${stat('On Time',st.on_time||0,'#047857','star')}
      ${stat('Delayed',st.delayed||0,'#dc2626','alert')}
    </div>`;
    const mt=Object.entries(st.month_types||{});
    const mtHtml=mt.length?`<div class="card" style="margin-bottom:16px"><div class="card-body" style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;padding:12px 16px"><span style="font-size:.68rem;font-weight:800;color:var(--text-muted);text-transform:uppercase;letter-spacing:.06em">${ic('chart')} This month you shot</span>${mt.map(([k,v])=>`<span class="vt-type">${esc(k)} · ${v}</span>`).join('')}</div></div>`:'';
    const card=t=>{
      const isU=(t.kind==='urgent');
      const dlLbl=isU?'Upload Deadline':'Deadline';
      const dlBlink=(isU&&t.status!=='uploaded')?' vt-dl-blink':'';
      const upTxt=isU?(t.status==='uploaded'
        ?(t.on_time===true?`<span class="vt-up-ok">${ic('check')} Uploaded on time</span>`
         :t.on_time===false?`<span class="vt-up-late">${ic('alert')} Upload delayed vs the deadline</span>`:'')
        :`<span class="vt-up-wait">${ic('clock')} Awaiting upload — publish before the deadline</span>`):'';
      const _open=(t.status==='assigned'||t.status==='reshoot'||t.status==='rejected');
      const _sbHead=(t.status==='reshoot')?`<div class="vt-resh-head">${ic('refresh')} Reshoot needed${t.review_remarks?` — ${esc(t.review_remarks)}`:''}</div>`
        :(t.status==='rejected')?`<div class="vt-resh-head" style="background:rgba(220,38,38,.1);color:#b91c1c;border-color:rgba(220,38,38,.35)">${ic('alert')} Rejected${t.review_remarks?` — ${esc(t.review_remarks)}`:''}</div>`:'';
      const subBox=_open?`
        <div class="vt-subm">
          ${_sbHead}
          <div class="vs-h">${ic('link')} ${t.status==='assigned'?'Submit your recorded video':'Submit your video again'}</div>
          <div class="vt-subm-row"><input id="tvt-link-${t.id}" class="input" placeholder="https://drive.google.com/file/d/...">
          <button class="btn btn-primary btn-sm" onclick="tvtSubmit(${t.id})">${ic('send')} ${t.status==='assigned'?'Submit Video':'Re-submit Video'}</button></div>
          <div class="vt-subm-note">Upload the video to the MVS drive folder first, then paste its shareable link here. Submit before the deadline for on-time credit.</div>
        </div>`:'';
      const doneBox=(t.submitted_link&&!_open)?`
        <div class="vt-subm done">
          <div class="vs-h">${ic('check')} Video submitted ${t.on_time===true?'— on time':(t.on_time===false?'— delayed':'')}</div>
          <div class="vt-done-link"><a href="${esc(t.submitted_link)}" target="_blank" rel="noopener">${ic('play')} Watch submitted video</a>${t.submitted_at?`<span style="color:var(--text-muted);font-weight:600">· ${esc(t.submitted_at)}</span>`:''}</div>
        </div>`:'';
      const reviewNote=(t.status==='submitted')?`<span class="vt-pill submitted blink">${ic('clock')} Under Review — Checking</span>`:'';
      const rejNote='';
      const propNote=(t.proposal_ok==='pending')?`<span class="vt-pill proposal">Pending Approval</span>`:'';
      return `<div class="vt-card st-${t.status}">${_vtThumb(t,'t')}<div class="vt-body">
        <div class="vt-chips">${propNote}${t.is_collab?`<span class="vt-pill vt-collab-blink" style="background:rgba(37,99,235,.15);color:#2563eb;font-weight:800">${ic('users')} COLLAB</span>`:''}${t.kind==='urgent'?`<span class="vt-pill" style="background:rgba(220,38,38,.15);color:#dc2626;font-weight:800">${ic('alert')} URGENT</span>`:''}${reviewNote}${_vtTypeBadge(t)}${t.channel?`<span class="vt-pill editing_soon">${ic('play')} ${esc(t.channel)}</span>`:''}</div>
        <div class="vt-title">${esc(t.title)}</div>
        <div class="vt-meta">
          ${t.deadline_nice?`<span class="${dlBlink}">${ic('clock')} ${dlLbl}: <b>${esc(t.deadline_nice)}</b></span>`:''}
          ${_open&&t.seconds_left!=null?`<span data-tvt-cd="${t.id}" data-secs="${t.seconds_left}" style="font-weight:800"></span>`:''}
          ${t.reference?`<span>Reference: ${esc(t.reference)}</span>`:''}
          ${t.remarks?`<span>Manager remarks: ${esc(t.remarks)}</span>`:''}
          ${t.submitted_at?`<span>${ic('check')} Submitted: ${esc(t.submitted_at)}${isU?'':` — <b>${t.on_time?'on time':'delayed'}</b>`}</span>`:''}
          ${upTxt?`<span>${upTxt}</span>`:''}
          ${!_open&&t.review_remarks?`<span>Review remarks: ${esc(t.review_remarks)}</span>`:''}
          ${t.reject_count>0?`<span style="color:var(--text-muted);font-weight:700">Reshoot/Rejection count: ${t.reject_count}</span>`:''}
        </div>
        ${_vtCollabHtml(t,false)}
        ${rejNote}${subBox}${doneBox}
      </div></div>`;
    };
    // ---- v73: master Task/Project cards + subject & type filters ----
    const spec=d.special||[];
    const specSubs=[...new Set(spec.map(t=>t.subject).filter(Boolean))].sort();
    const specCls=[...new Set(spec.map(t=>t.cls).filter(Boolean))].sort();
    if(_tvtSpecCls&&!specCls.includes(_tvtSpecCls)) specCls.push(_tvtSpecCls);
    if(_tvtSpecKind&&!spec.some(t=>t.kind===_tvtSpecKind)) _tvtSpecKind='';
    const fSpec=spec.filter(t=>(!_tvtSpecSub||t.subject===_tvtSpecSub)&&(!_tvtSpecKind||t.kind===_tvtSpecKind)&&(!_tvtSpecCls||t.cls===_tvtSpecCls));
    const subjSpec=spec.filter(t=>(!_tvtSpecSub||t.subject===_tvtSpecSub)&&(!_tvtSpecCls||t.cls===_tvtSpecCls));
    let spD=0,spT=0; subjSpec.forEach(t=>{spD+=t.done||0;spT+=t.total||0});
    const urgentT=tasks.filter(t=>t.kind==='urgent');
    const normalT=tasks.filter(t=>t.kind!=='urgent');
    const fTasks=_tvtSpecSub?normalT.filter(t=>!t.subject||t.subject===_tvtSpecSub):normalT;
    // v91: jab tak teacher ek card pe click na kare, neeche ka data hidden rahe —
    // dono cards halki blink ke saath "click here" signal dete hain.
    const showTasks=(_tvtView==='tasks'), showProj=(_tvtView==='projects');
    const sug=_tvtView?'':' suggest';
    const masterCards=`<div class="vtm-cards">
      <div class="vtm-card${sug} ${_tvtView==='tasks'?'on':''}" onclick="tvtView('tasks')">
        <div class="vtm-ic">${ic('clipboard')}</div>
        <div class="vtm-main"><div class="vtm-n">${active.length}<span> active</span></div>
          <div class="vtm-l">Tasks</div>
          <div class="vtm-s">Single video assignments · ${st.uploaded||0} uploaded · ${st.pending||0} pending</div></div>
        <div class="vtm-go">${ic('chev-down')}</div></div>
      <div class="vtm-card${sug} ${_tvtView==='projects'?'on':''}" onclick="tvtView('projects')">
        <div class="vtm-ic">${ic('folder')}</div>
        <div class="vtm-main"><div class="vtm-n">${spD}<span> / ${spT} videos done</span></div>
          <div class="vtm-l">Projects</div>
          <div class="vtm-s">One Shot · Rapid Revision · Projects${_tvtSpecSub?' — '+esc(_tvtSpecSub):''} · ${subjSpec.length} cards</div></div>
        <div class="vtm-go">${ic('chev-down')}</div></div></div>
      ${!_tvtView?`<div class="vtm-hint">${ic('help')}<span><b>Tap Tasks or Projects above</b> — the matching details will open here.</span></div>`:''}`;
    const filterBar=specSubs.length?`<div class="vtm-filter">
      <span class="vtm-fl">Subject</span>
      <select class="vtm-sel" id="tvt-spec-sub" onchange="tvtSpecSubSet(this.value)">
        <option value="">All Subjects (${specSubs.length})</option>
        ${specSubs.map(s=>`<option value="${esc(s)}" ${_tvtSpecSub===s?'selected':''}>${esc(s)}</option>`).join('')}
      </select>
      ${specCls.length?`<span class="vtm-fl">Class</span>
      <select class="vtm-sel" id="tvt-spec-cls" onchange="tvtSpecClsSet(this.value)">
        <option value="">All Classes</option>
        ${specCls.map(c=>`<option value="${c}" ${_tvtSpecCls===c?'selected':''}>Class ${c}</option>`).join('')}
      </select>`:''}
      <span class="vtm-fl">Type</span>
      <select class="vtm-sel" id="tvt-spec-kind" onchange="tvtSpecKindSet(this.value)">
      ${[['','All Types'],['one_shot','One Shot'],['rapid_revision','Rapid Revision'],['project','Projects']].filter(([k])=>!k||spec.some(t=>t.kind===k)).map(([k,l])=>`<option value="${k}" ${_tvtSpecKind===k?'selected':''}>${l}</option>`).join('')}
      </select>
    </div>`:'';
    el.innerHTML=`${hero}${statCards}${mtHtml}${masterCards}
      <div class="vtm-actions" style="display:flex;gap:10px;margin:0 0 16px;flex-wrap:wrap;align-items:center">
        <button class="btn btn-primary" onclick="openTVTPropose()">${ic('plus')} Propose a Video</button>
        <button class="btn vt-urgent-btn" onclick="openTVTUrgent()">${ic('alert')} Urgent Video</button>
        <span style="font-size:.74rem;color:var(--text-muted)">Have a video idea? Propose it. Something urgent? Submit it directly — no approval needed.</span>
      </div>
      ${urgentT.length?`<div class="vtm-sec-cap" style="border-left-color:#dc2626">Urgent Videos · submitted directly to production</div>
      <div class="vt-grid" style="margin-bottom:18px">${urgentT.map(card).join('')}</div>`:''}
      <div class="card vv-card" style="margin-bottom:16px"><div class="card-header" style="cursor:pointer;user-select:none" onclick="_tvtVvToggle()"><h3>${ic('chart')} My Video Performance <span style="font-size:.7rem;font-weight:600;color:var(--text-muted)">— real-time YouTube views</span></h3><span class="vt-os-chev" id="t-vv-chev">${ic('chev-down')}</span></div><div class="card-body" id="t-vv-body" style="display:none"><div id="t-vv-wrap"></div></div></div>
      <div class="card vv-card" style="margin-bottom:16px"><div class="card-header" style="cursor:pointer;user-select:none" onclick="_tvtTgToggle()"><h3>${ic('clipboard')} My Monthly Targets <span style="font-size:.7rem;font-weight:600;color:var(--text-muted)">— my progress this month</span></h3><span class="vt-os-chev" id="t-tg-chev">${ic('chev-down')}</span></div><div class="card-body" id="t-tg-body" style="display:none"><div id="t-tg-wrap"></div></div></div>
      ${filterBar}
      ${showProj?`<div class="vtm-sec-cap">Projects · One Shot, Rapid Revision &amp; custom — tap a card to expand</div>
        <div id="tvt-spec-wrap">${_vtSpecialT(fSpec)}</div>`:''}
      ${showTasks?`<div class="vtm-sec-cap">Tasks · Single video assignments</div>
      ${fTasks.length?`<div class="vt-grid">${fTasks.map(card).join('')}</div>`
        :`<div class="ws-empty"><div class="big">${ic('clipboard')}</div><p><b>No video tasks yet</b></p><small>When the production manager assigns you a task, it will appear here with its deadline countdown.</small></div>`}`:''}`;
    const tick=()=>{ document.querySelectorAll('[data-tvt-cd]').forEach(sp=>{
      let s=+sp.dataset.secs; if(isNaN(s))return; s--; sp.dataset.secs=s;
      const neg=s<0; sp.textContent=_vtCdText(s);
      sp.style.color=neg?'#b91c1c':(s<86400?'#b45309':'#047857'); }); };
    tick(); _tvtTimer=setInterval(tick,1000);
  }catch(e){ el.innerHTML=errHtml(e); }
}
async function openTVTPropose(){
  let types=window._vtTypesT;
  if(!types){ try{ types=((await api('/api/teacher/video-types')).types)||[]; window._vtTypesT=types; }catch(e){ types=[]; } }
  let chans=window._vtChansT;
  if(!chans){ try{ chans=((await api('/api/teacher/video-channels')).channels)||[]; window._vtChansT=chans; }catch(e){ chans=[]; } }
  window._vtThumbB64=null;
  window._tvtPKind='task';
  const chOpts=`<option value="">— No channel —</option>`+chans.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');
  showModal('Propose a Video / Project',`
    <div class="form-grid vt-form">
      <div class="form-group" style="grid-column:1/-1">
        <div class="vtaw-tabs">
          <button type="button" class="vtaw-tab on" id="tvtp-t-task" onclick="tvtPKind('task')">${ic('play')} Single Video</button>
          <button type="button" class="vtaw-tab" id="tvtp-t-proj" onclick="tvtPKind('project')">${ic('clipboard')} Project</button>
        </div></div>
      <div class="form-group" id="tvt-p-scope-wrap" style="grid-column:1/-1;display:none"><label>Project scope</label>
        <select id="tvt-p-scope" class="input" onchange="tvtScopeToggle()">
          <option value="chapter">Complete chapter — from my timetable (manager assigns the videos)</option>
          <option value="videos">A set of videos — I'll enter the titles myself</option>
        </select>
        <div id="tvt-p-items-wrap" style="display:none;margin-top:10px">
          <label>Videos / Deliverables — one row per video</label>
          <div id="tvt-p-items"></div>
          <button type="button" class="btn btn-ghost btn-sm" onclick="tvtPItemAdd()" style="margin-top:4px">${ic('plus')} Add video</button>
        </div>
      </div>
      <div class="form-group" id="tvt-p-subj-wrap" style="grid-column:1/-1;display:none"><label>Subject &amp; Class (for the project)</label>
        <select id="tvt-p-subject" class="input"><option value="">— Select your subject —</option></select>
        <div style="font-size:.72rem;color:var(--text-muted);margin-top:4px">Which subject and class this project is for, so the manager gets the correct chapters from your timetable.</div>
      </div>
      <div class="form-group" style="grid-column:1/-1"><label>Title</label><input id="tvt-p-title" class="input" placeholder="e.g. Probability Short Tricks — NIOS Special"></div>
      <div class="form-group"><label>Streaming</label><select id="tvt-p-stream" class="input" onchange="_vtFilterTypes('tvt-p-stream','tvt-p-type',window._vtTypesT)"><option value="">— Select —</option><option value="recorded">Recorded</option><option value="live">Live</option></select></div>
      <div class="form-group"><label>Video Type</label><select id="tvt-p-type" class="input">${_vtTypeOptsHtml(types,'','','— Select type —')}</select></div>
      <div class="form-group" style="grid-column:1/-1"><label>Channel (optional)</label><select id="tvt-p-channel" class="input">${chOpts}</select></div>
      <div class="form-group vt-thumb-box" style="grid-column:1/-1"><label>Reference Thumbnail (optional)</label>
        <div class="vt-file vt-drop" ondragover="_vtDropOver(event,this)" ondragleave="_vtDropLeave(event,this)" ondrop="_vtDropFile(event,this)"><label class="vt-file-btn" for="tvt-p-thumb">${ic('image')} Upload Image</label><span class="vt-drop-hint">or drag &amp; drop an image here</span>
          <span class="vt-file-name" id="vt-thumb-name">No file chosen</span></div>
        <input id="tvt-p-thumb" type="file" accept="image/*" style="display:none" onchange="vtThumbPreview(this)">
        <div id="vt-thumb-prev" style="margin-top:8px"></div>
      </div>
      <div class="form-group" style="grid-column:1/-1"><label>Why this video? (optional)</label><textarea id="tvt-p-ref" class="input" rows="2" placeholder="Student demand, exam relevance, etc."></textarea></div>
    </div>
    <p style="font-size:.74rem;color:var(--text-muted)">Your proposal goes to the production manager. Once approved, you will get the thumbnail and deadline here.</p>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="tvtProposeSave()">${ic('send')} Send for Approval</button>`);
  tvtLoadMySubjects();
}
async function tvtLoadMySubjects(){
  const sel=document.getElementById('tvt-p-subject'); if(!sel) return;
  let sc=window._tvtMySubjClasses;
  if(!sc){ try{ const p=await api('/api/teacher/profile'); sc=p.subject_classes||[]; window._tvtMySubjClasses=sc; }catch(e){ sc=[]; } }
  if(!sc.length){ sel.innerHTML='<option value="">— No subjects set —</option>'; return; }
  sel.innerHTML='<option value="">— Select your subject —</option>'+sc.map(x=>{const s=(x.subject||'').trim(),c=(x.class||x.class_level||'').trim();return `<option value="${esc(s)}||${esc(c)}">${esc(s)}${c?' \u00b7 Class '+esc(c):''}</option>`;}).join('');
}
function tvtScopeToggle(){
  const sc=(document.getElementById('tvt-p-scope')||{}).value;
  const w=document.getElementById('tvt-p-items-wrap'); if(!w) return;
  const show=(sc==='videos'); w.style.display=show?'block':'none';
  const items=document.getElementById('tvt-p-items');
  if(show && items && !items.children.length){ tvtPItemAdd();tvtPItemAdd();tvtPItemAdd(); }
}
function tvtPItemAdd(v){
  const w=document.getElementById('tvt-p-items'); if(!w) return;
  const d=document.createElement('div'); d.className='vtp-item';
  d.innerHTML=`<input class="input tvt-p-itm" placeholder="e.g. Ray Optics — full project video" value="${esc(v||'')}"><button type="button" onclick="this.parentElement.remove()">×</button>`;
  w.appendChild(d);
}
function _tvtVvToggle(){
  const b=document.getElementById('t-vv-body'); if(!b) return;
  const open=(b.style.display==='none'); b.style.display=open?'block':'none';
  const ch=document.getElementById('t-vv-chev'); if(ch) ch.style.transform=open?'rotate(180deg)':'';
  if(open) renderVideoViews('t-vv-wrap','/api/teacher',false);
}
function _tvtTgToggle(){
  const b=document.getElementById('t-tg-body'); if(!b) return;
  const open=(b.style.display==='none'); b.style.display=open?'block':'none';
  const ch=document.getElementById('t-tg-chev'); if(ch) ch.style.transform=open?'rotate(180deg)':'';
  if(open) renderMyTargets('t-tg-wrap');
}
function _ttTeacherCard(t,showName){
  const rows=t.rows.map(r=>{
    const met=r.target>0&&r.done>=r.target;
    return `<div class="tt-row">
      <div class="tt-lbl">${esc(r.label)}${r.custom?'<span class="tt-cust">extra</span>':''}</div>
      <div class="tt-mid">${_ttBar(r.done,r.target)}<b class="tt-num ${met?'ok':''}">${r.done}/${r.target||'—'}</b></div>
      <div class="tt-chips">${r.assigned?`<span class="tt-chip">assigned ${r.assigned}</span>`:''}${r.pending?`<span class="tt-chip pend">pending ${r.pending}</span>`:""}${r.verify?`<span class="tt-chip verify">verify ${r.verify}</span>`:""}${met?`<span class="tt-chip ok">${ic('check')} done</span>`:''}</div>
    </div>`;
  }).join('');
  const subChips=[...new Set(t.subjects||[])].map(s=>`<span class="tt-sub">${esc(s)}</span>`).join('');
  const bysub=(t.multi&&(t.by_subject||[]).length)?`<details class="tt-bysub"><summary>${ic('folder')} By subject (${t.by_subject.length}) — Videos target per subject</summary>
    <div class="tt-subwrap">${t.by_subject.map(b=>{const met=b.target>0&&b.done>=b.target;return `<div class="tt-srow"><span class="tt-slbl">${esc(b.subject)}</span>${_ttBar(b.done,b.target)}<b class="tt-num ${met?'ok':''}">${b.done}/${b.target||'—'}</b>${b.pending?`<span class="tt-chip pend">pending ${b.pending}</span>`:''}${b.assigned?`<span class="tt-chip">assigned ${b.assigned}</span>`:''}</div>`;}).join('')}</div></details>`:'';
  return `<div class="tt-card">${showName?`<div class="tt-head"><div class="tt-name">${esc(t.name)}</div><div class="tt-subs">${subChips}</div></div>`:(subChips?`<div class="tt-subs" style="margin-bottom:10px">${subChips}</div>`:'')}<div class="tt-rows">${rows}</div>${bysub}</div>`;
}
async function renderMyTargets(wrapId){
  const wrap=document.getElementById(wrapId); if(!wrap) return;
  wrap.innerHTML='<div class="spinner"></div>';
  try{
    const d=await api('/api/teacher/my-targets');
    const t=d.me;
    if(!t||!t.rows){ wrap.innerHTML='<div class="vv-empty">No targets set yet.</div>'; return; }
    wrap.innerHTML=`<div style="font-size:.72rem;color:var(--text-muted);margin-bottom:12px">Month: <b>${esc(d.month)}</b> · <span style="color:#059669;font-weight:700">green = target met</span></div>`+_ttTeacherCard(t,false);
  }catch(e){ wrap.innerHTML=errHtml(e); }
}
function tvtPKind(k){
  window._tvtPKind=k;
  const tk=document.getElementById('tvtp-t-task'), pj=document.getElementById('tvtp-t-proj');
  if(tk) tk.classList.toggle('on',k==='task');
  if(pj) pj.classList.toggle('on',k==='project');
  const sw=document.getElementById('tvt-p-scope-wrap'); if(sw) sw.style.display=(k==='project')?'block':'none';
  const subw=document.getElementById('tvt-p-subj-wrap'); if(subw) subw.style.display=(k==='project')?'block':'none';
  if(k==='project') tvtScopeToggle();
}
async function tvtProposeSave(){
  const title=document.getElementById('tvt-p-title').value.trim();
  if(!title){ toast('Please enter a video title'); return; }
  const ptype=window._tvtPKind||'task';
  const body={ title, propose_type:ptype,
    video_type:(document.getElementById('tvt-p-type')||{}).value||'',
    streaming:val('tvt-p-stream')||'',
    channel_id:val('tvt-p-channel')||'',
    reference:document.getElementById('tvt-p-ref').value.trim(),
    thumbnail_b64:window._vtThumbB64||null };
  if(ptype==='project'){
    body.project_scope=val('tvt-p-scope')||'chapter';
    const sv=val('tvt-p-subject')||'';
    if(sv){ const i=sv.indexOf('||'); body.subject=(i<0?sv:sv.slice(0,i)).trim(); body.class_level=(i<0?'':sv.slice(i+2)).trim(); }
    if(body.project_scope==='chapter' && !body.subject){ toast('Please select the subject and class for this project'); return; }
    if(body.project_scope==='videos'){
      const items=[...document.querySelectorAll('#tvt-p-items .tvt-p-itm')].map(i=>i.value.trim()).filter(Boolean);
      if(!items.length){ toast('Add at least one video title'); return; }
      body.video_items=items;
      body.video_count=String(items.length);
    }
  }
  try{
    await api('/api/teacher/video-tasks/propose','POST',body);
    window._vtThumbB64=null; closeModal(); toast('Proposal sent for approval.'); loadTVTasks();
  }catch(e){ toast(e.message||'Could not send'); }
}
async function openTVTUrgent(){
  let types=window._vtTypesT;
  if(!types){ try{ types=((await api('/api/teacher/video-types')).types)||[]; window._vtTypesT=types; }catch(e){ types=[]; } }
  let chans=window._vtChansT;
  if(!chans){ try{ chans=((await api('/api/teacher/video-channels')).channels)||[]; window._vtChansT=chans; }catch(e){ chans=[]; } }
  const chOpts=`<option value="">— No channel —</option>`+chans.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');
  const dl=new Date(Date.now()+24*3600*1000); dl.setMinutes(0);
  const dlVal=`${dl.getFullYear()}-${String(dl.getMonth()+1).padStart(2,'0')}-${String(dl.getDate()).padStart(2,'0')}T${String(dl.getHours()).padStart(2,'0')}:00`;
  showModal('Urgent Video',`
    <div class="form-grid vt-form">
      <div class="form-group" style="grid-column:1/-1"><label>Video Title</label><input id="tvt-u-title" class="input" placeholder="e.g. Breaking — NIOS Exam Date Out"></div>
      <div class="form-group"><label>Streaming</label><select id="tvt-u-stream" class="input" onchange="_vtFilterTypes('tvt-u-stream','tvt-u-type',window._vtTypesT)"><option value="">— Select —</option><option value="recorded">Recorded</option><option value="live">Live</option></select></div>
      <div class="form-group"><label>Video Type</label><select id="tvt-u-type" class="input">${_vtTypeOptsHtml(types,'','','— Select type —')}</select></div>
      <div class="form-group" style="grid-column:1/-1"><label>Channel (optional)</label><select id="tvt-u-channel" class="input">${chOpts}</select></div>
      <div class="form-group" style="grid-column:1/-1"><label>Submit Video Link</label><input id="tvt-u-link" class="input" placeholder="https://drive.google.com/... (your shot video)"></div>
      <div class="form-group" style="grid-column:1/-1"><label>Upload by (deadline)</label><input id="tvt-u-deadline" type="datetime-local" class="input" value="${dlVal}"></div>
    </div>
    <p style="font-size:.74rem;color:var(--text-muted)">No approval needed — this goes straight to the production manager's Urgent Videos. On-time is based on the upload happening by your deadline.</p>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="tvtUrgentSave()">${ic('send')} Submit Urgent Video</button>`);
}
async function tvtUrgentSave(){
  const val=id=>(document.getElementById(id)||{}).value||'';
  const title=val('tvt-u-title').trim();
  if(!title){ toast('Please enter a video title'); return; }
  const body={ title, link:val('tvt-u-link').trim(), channel_id:val('tvt-u-channel')||'',
    video_type:val('tvt-u-type'), streaming:val('tvt-u-stream'), deadline:val('tvt-u-deadline') };
  try{
    await api('/api/teacher/video-tasks/urgent','POST',body);
    closeModal(); toast('Urgent video submitted.'); loadTVTasks();
  }catch(e){ toast(e.message||'Could not submit'); }
}
async function tvtSubmit(id){  const link=document.getElementById('tvt-link-'+id).value.trim();
  if(!link){ toast('Please paste the video drive link'); return; }
  try{
    const r=await api(`/api/teacher/video-tasks/${id}/submit`,'POST',{link});
    toast(r.on_time?'Submitted on time — great job!':'Submitted (after deadline).');
    loadTVTasks();
  }catch(e){ toast(e.message||'Could not submit'); }
}
/* dashboard countdown banner */
async function loadVTBanner(){
  const el=document.getElementById('t-vt-banner'); if(!el) return;
  try{
    const d=await api('/api/teacher/video-tasks/my');
    // v115: My Tasks ka sidebar badge bhi dashboard pe hi refresh ho
    const _actN=(d.tasks||[]).filter(t=>t.status==='assigned').length;
    const _tb=document.getElementById('t-vt-badge'); if(_tb){ _tb.style.display=_actN?'inline-block':'none'; _tb.textContent=_actN; }
    const nxt=d.next_deadline;
    if(!nxt){ el.style.display='none'; el.innerHTML=''; return; }
    el.style.display='block';
    el.innerHTML=`<div class="vt-banner" onclick="tPage('vtasks',null)" style="cursor:pointer">
      <div style="width:40px;height:40px;border-radius:11px;background:rgba(184,148,31,.15);color:#8a6d10;display:flex;align-items:center;justify-content:center;flex-shrink:0">${ic('clipboard')}</div>
      <div style="flex:1;min-width:160px"><div style="font-weight:800;font-size:.86rem">${esc(nxt.title)}</div>
        <div style="font-size:.7rem;color:var(--text-muted)">${nxt.channel?esc(nxt.channel)+' · ':''}Due ${esc(nxt.deadline_nice)} — tap to open My Tasks</div></div>
      <div class="vt-count" id="tvt-banner-cd" data-secs="${nxt.seconds_left||0}"></div></div>`;
    const cd=document.getElementById('tvt-banner-cd');
    const paint=()=>{ let s=+cd.dataset.secs; s=Math.max(0,s-1); cd.dataset.secs=s;
      const m=Math.floor(s%3600/60),ss=s%60;
      const cls=s<=0?'over':(s<86400?'urgent':'');
      const cells=s>=86400?[[''+Math.floor(s/86400),'days'],[''+String(Math.floor(s%86400/3600)).padStart(2,'0'),'hrs'],[''+String(m).padStart(2,'0'),'min'],[''+String(ss).padStart(2,'0'),'sec']]
        :[[''+String(Math.floor(s/3600)).padStart(2,'0'),'hrs'],[''+String(m).padStart(2,'0'),'min'],[''+String(ss).padStart(2,'0'),'sec']];
      cd.innerHTML=cells.map(x=>`<div class="vt-cd ${cls}"><b>${x[0]}</b><small>${x[1]}</small></div>`).join(''); };
    paint(); if(window._tvtBannerInt) clearInterval(window._tvtBannerInt);
    window._tvtBannerInt=setInterval(()=>{ if(!document.getElementById('tvt-banner-cd')){ clearInterval(window._tvtBannerInt); return; } paint(); },1000);
  }catch(e){ el.style.display='none'; }
}

/* ================= VIDEO TASK MANAGER (admin) ================= */
let _vtTeachers=[], _vtChannels=[], _vtTypes=[], _vtF={teacher_id:0,status:'',channel_id:0,video_type:'',collab:'',q:''}, _vtTimer=null;
// v134: video type ko streaming (live/recorded/both) ke hisaab se filter karo
function _vtScopeOk(t,stream){ const sc=(t&&t.streaming_scope)||'both'; return !stream||sc==='both'||sc===stream; }
function _vtTypeOptsHtml(types,streamVal,selectedName,placeholder){
  return `<option value="">${placeholder||'— Select type —'}</option>`+
    (types||[]).filter(t=>_vtScopeOk(t,streamVal)).map(c=>`<option value="${esc(c.name)}" ${selectedName===c.name?'selected':''}>${esc(c.name)}</option>`).join('');
}
function _vtFilterTypes(streamSelId,typeSelId,types){
  const s=(document.getElementById(streamSelId)||{}).value||'';
  const ts=document.getElementById(typeSelId); if(!ts) return;
  ts.innerHTML=_vtTypeOptsHtml(types,s,ts.value);
}
const VT_LBL={assigned:'Assigned',submitted:'Submitted',approved:'Approved',editing_soon:'Editing Soon',editing_done:'Editing Done',uploaded:'Uploaded',reshoot:'Reshoot',rejected:'Rejected',proposal:'Pending Approval'};
function _vtQs(){ const f=_vtF,q=[]; if(f.teacher_id)q.push('teacher_id='+f.teacher_id); if(f.status)q.push('status='+f.status); if(f.channel_id)q.push('channel_id='+f.channel_id); if(f.video_type)q.push('video_type='+encodeURIComponent(f.video_type)); return q.length?'?'+q.join('&'):''; }
function _vtPill(t,blink,who){
  let cls=t.status, lbl=VT_LBL[t.status]||t.status;
  if((t.status==='assigned'||t.status==='reshoot'||t.status==='rejected')&&t.overdue){ cls='delayed'; lbl='Overdue'; }
  // teacher side: upload hone tak status blink karta rahe
  const bl=(blink&&t.status!=='uploaded'&&t.proposal_ok!=='pending')?' blink':'';
  let extra='';
  if(t.status==='submitted'&&t.on_time!=null&&t.kind!=='urgent') extra=` <span class="vt-pill ${t.on_time?'ontime':'delayed'}${bl}">${t.on_time?'On Time':'Delayed'}</span>`;
  const oc=who?` onclick="vtStatusOpen(${t.id},'${who}',event)" title="Tap for full status history"`:''; 
  return `<span class="vt-pill ${cls}${bl}${who?' lnk':''}"${oc}>${lbl}</span>${extra}`;
}
function vtThumbPreview(input){
  const file=input&&input.files&&input.files[0];
  if(file) _vtThumbFile(file);
}
function _vtDropOver(e,el){ e.preventDefault(); e.stopPropagation(); if(el) el.classList.add('drag'); }
function _vtDropLeave(e,el){ e.preventDefault(); e.stopPropagation(); if(el) el.classList.remove('drag'); }
function _vtDropFile(e,el){
  e.preventDefault(); e.stopPropagation(); if(el) el.classList.remove('drag');
  const f=e.dataTransfer&&e.dataTransfer.files&&e.dataTransfer.files[0];
  if(f) _vtThumbFile(f);
}
function _vtThumbFile(file){
  // v137: ye core ab file seedhe leta hai — click-browse aur drag-drop dono isi ko call karte hain.
  if(!file) return;
  const nameEl=document.getElementById('vt-thumb-name');
  const prev=document.getElementById('vt-thumb-prev');
  const setName=(t)=>{ if(nameEl) nameEl.textContent=t; };
  const setPrev=(src)=>{ if(prev) prev.innerHTML=`<img src="${src}" style="max-height:90px;border-radius:10px;border:1px solid var(--border)">`; };
  const fail=(msg)=>{ window._vtThumbB64=null; setName(msg||'Could not read this image'); };
  setName(file.name||'thumbnail');
  if(!/^image\//i.test(file.type||'')&&!/\.(jpe?g|png|webp|gif|bmp|heic|heif|avif)$/i.test(file.name||'')){
    fail('Please choose an image file'); return;
  }
  const reader=new FileReader();
  reader.onerror=()=>fail('Could not read the file');
  reader.onload=()=>{
    const dataUrl=reader.result;
    const img=new Image();
    img.onload=()=>{
      try{
        const MAXW=1280, sc=Math.min(1, MAXW/((img.naturalWidth||img.width)||MAXW));
        const w=Math.max(1,Math.round(((img.naturalWidth||img.width))*sc));
        const h=Math.max(1,Math.round(((img.naturalHeight||img.height))*sc));
        const cv=document.createElement('canvas'); cv.width=w; cv.height=h;
        const ctx=cv.getContext('2d'); ctx.fillStyle='#fff'; ctx.fillRect(0,0,w,h); ctx.drawImage(img,0,0,w,h);
        let out=cv.toDataURL('image/jpeg',0.82);
        if(out.length>1400000) out=cv.toDataURL('image/jpeg',0.6);
        if(out.length>1400000) out=cv.toDataURL('image/jpeg',0.42);
        window._vtThumbB64=out; setPrev(out); setName((file.name||'thumbnail')+' \u2713');
      }catch(e){
        if(String(dataUrl).length<1800000){ window._vtThumbB64=dataUrl; setPrev(dataUrl); setName((file.name||'thumbnail')+' \u2713'); }
        else fail('Image too large — please use a smaller one');
      }
    };
    img.onerror=()=>{
      if(String(dataUrl).length<1800000){ window._vtThumbB64=dataUrl; setPrev(dataUrl); setName((file.name||'thumbnail')+' \u2713 (original)'); }
      else fail('This format could not be previewed — try a JPG or PNG');
    };
    img.src=dataUrl;
  };
  reader.readAsDataURL(file);
}
function _vtThumb(t,who){
  const has=!!(t.thumbnail_b64||t.thumbnail_link);
  const img=t.thumbnail_b64?`<img src="${t.thumbnail_b64}" alt="">`
    :(t.thumbnail_link?`<img src="${esc(t.thumbnail_link)}" onerror="this.remove()" alt="">`:'');
  const blink=who==='t';
  return `<div class="vt-thumb${has?' click':''}"${has?` onclick="vtThumbOpen(${t.id},'${who||'t'}')" title="Open full screen — download available"`:''}>${img||esc((t.title||'V').slice(0,1).toUpperCase())}<div class="vt-status">${_vtPill(t,blink,who)}</div>${has?`<span class="vt-dl">${ic('download')} View</span>`:''}</div>`;
}
function _vtTypeBadge(t){ return t.video_type?`<span class="vt-type">${ic('play')} ${esc(t.video_type)}</span>`:''; }
function vtThumbOpen(id,who){
  const t=(((who==='a')?window._avtMap:window._tvtMap)||{})[id]; if(!t) return;
  const name=((t.title||'thumbnail').replace(/[^\w\- ]+/g,'').trim().slice(0,60)||'thumbnail');
  if(t.thumbnail_b64){ openImageViewerSrc(t.thumbnail_b64,name+'.jpg'); return; }
  const link=t.thumbnail_link||'';
  if(/\.(png|jpe?g|webp|gif|bmp)(\?|#|$)/i.test(link)) openImageViewerSrc(link,name+'.jpg');
  else if(link) window.open(link,'_blank');
  else toast('No thumbnail attached to this task');
}
function vtStatusOpen(id,who,ev){
  if(ev){ ev.stopPropagation(); ev.preventDefault(); }
  const t=(((who==='a')?window._avtMap:window._tvtMap)||{})[id]; if(!t) return;
  let hist=(t.history||[]).slice();
  if(!hist.length){ // purane task — client-side synthesis
    if(t.created_at) hist.push({s:'assigned',at:t.created_at,note:'Task assigned'});
    if(t.submitted_at) hist.push({s:'submitted',at:t.submitted_at,note:'Video link submitted — '+(t.on_time?'on time':'delayed')});
    if(t.reviewed&&!['assigned','submitted'].includes(t.status)) hist.push({s:t.status,at:'',note:t.review_remarks||''});
  }
  const lbl=s=>(VT_LBL[s]||(s==='progress'?'Progress':s==='edited'?'Updated':s));
  const dotCls=s=>['submitted','approved','editing_done','uploaded'].includes(s)?'done':(['rejected'].includes(s)?'bad':'');
  const rows=hist.map(h=>`<div class="vt-tl-i ${dotCls(h.s)}"><div class="vt-tl-s">${esc(lbl(h.s))}</div>
    <div class="vt-tl-a">${esc(h.at||'')}</div>${h.note?`<div class="vt-tl-n">${esc(h.note)}</div>`:''}</div>`).join('');
  showModal(`Status History — ${esc(t.title)}`,`
    <div style="margin-bottom:14px;display:flex;gap:8px;align-items:center;flex-wrap:wrap">${_vtPill(t,false)}<span style="font-size:.72rem;color:var(--text-muted);font-weight:700">current status</span></div>
    ${t.is_collab?`<div class="cb-box" style="margin:0 0 14px"><div class="cb-head">${ic('users')} COLLAB TASK ${t.collab_all_verified?'<span class="cb-pill ok">All verified</span>':'<span class="cb-pill bad">Verify pending</span>'}</div><div class="cb-chips">${(t.collab_teachers||[]).map(c=>`<span class="cbnm ${c.verified?'ok':''}">${esc(c.name)}${c.verified?' — Approved':''}</span>`).join('')}</div></div>`:''}
    <div class="vt-tl">${rows||'<div style="font-size:.8rem;color:var(--text-muted)">No history yet.</div>'}</div>`,
    `<button class="btn btn-primary" onclick="closeModal()">Close</button>`);
}
