  window._vtBucket=null;
  const sels=document.querySelectorAll('.vt-filt-sel'); const sSel=sels[sels.length-1];
  if(sSel) sSel.value=_vtF.status;
  document.querySelectorAll('.vt-stat.vt-ap-blink,.vt-stat[data-ap]').forEach(c=>c.classList.toggle('vt-stat-on', _vtF.status==='submitted'));
