  const btn=document.getElementById('nt-btn'); btn.disabled=true; btn.textContent='Sending...';
  try{ const r=await api('/api/admin/teacher/'+tid+'/notify','POST',{title,message}); toast(r.message||'Notification sent.'); closeModal(); }
  catch(e){ document.getElementById('nt-status').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`; btn.disabled=false; btn.textContent='Send'; }
