// modal + panel dono ke liye shared: file select/drag karte hi staged upload shuru
function _dppWireStage(pid){
  const fi=document.getElementById('dpp-sub-file');
  if(!fi) return;
  fi.addEventListener('change',()=>{ if(fi.files.length) _dppStageUpload(pid,fi.files[0]); });
  const dz=fi.closest('.file-drop');
  if(dz) dz.addEventListener('drop',e=>{ const f=e.dataTransfer&&e.dataTransfer.files; if(f&&f.length) _dppStageUpload(pid,f[0]); });
}
