  return `<div class="card" style="margin-top:18px;border:1.5px solid rgba(184,148,31,.35)"><div class="card-body" style="padding:16px">
    <h4 style="margin:0 0 10px;font-size:.95rem">${ic('upload')} ${subm?'Re-submit Your Answer':'Submit Your Answer'}</h4>
    ${fileDropHTML('dpp-sub-file','dpp-sub-label','.pdf,image/*')}
    <div id="dpp-up-wrap" style="display:none;margin-top:12px">
      <div style="height:12px;background:rgba(0,0,0,.09);border-radius:99px;overflow:hidden;border:1px solid var(--border)"><div id="dpp-up-fill" style="height:100%;width:0%;background:linear-gradient(90deg,var(--acc),#d4af37);transition:width .25s;border-radius:99px"></div></div>
      <div id="dpp-up-text" style="font-size:.78rem;color:var(--text-muted);margin-top:6px;text-align:center;line-height:1.4">0%</div>
    </div>
    <div style="margin-top:14px;text-align:right"><button class="btn btn-success" id="dpp-sub-btn" disabled title="Wait for the upload to reach 100%" onclick="submitDppFile(${pid})">${subm?'Re-submit Answer':'Submit Answer'}</button></div>
  </div></div>`;
