// File select hote hi background upload (progress % ke saath) — submit sirf 100% ke baad
async function _dppStageUpload(pid,file){
  const wrap=document.getElementById('dpp-up-wrap'), fill=document.getElementById('dpp-up-fill'),
        txt=document.getElementById('dpp-up-text'), btn=document.getElementById('dpp-sub-btn');
  if(!wrap||!fill||!txt) return;
  window._dppStaged=null; if(btn){ btn.disabled=true; btn.textContent='Submit'; }
  wrap.style.display='block'; fill.style.width='0%';
  const setp=p=>{ fill.style.width=p+'%'; txt.innerHTML='Uploading… <b>'+Math.round(p)+'%</b>'; };
  txt.textContent='Preparing your file…';
  let f;
  try{
    const _r=await _prepDppAnswer(file,m=>{ txt.textContent=m; });
    if(!_r.ok){ txt.innerHTML='<span style="color:var(--danger)">File is too large — try a shorter PDF or a smaller photo.</span>'; return; }
    f=_r.file;
  }catch(e){ txt.textContent='Could not read the file — please select it again.'; return; }
  const kb=Math.round(f.size/1024);
  // Test-answer sheet wala hi proven flow: EK direct upload, live progress % ke
  // saath (koi chunks nahi). 100% pe Submit enable hota hai.
  for(let att=0;att<2;att++){
    try{
      const res=await _dppStageXHR(pid,f,setp);
      window._dppStaged={pid:pid,answer_id:res.answer_id};
      fill.style.width='100%';
      txt.innerHTML='<span style="color:var(--acc);font-weight:600">✔ Upload complete ('+(kb>1024?(kb/1024).toFixed(1)+'MB':kb+'KB')+')</span> — now press <b>Submit</b>';
      if(btn){ btn.disabled=false; btn.focus(); }
      return;
    }catch(e){
      if(att===0 && /fail|fetch|network|timeout|abort/i.test(e.message||'')){
        txt.textContent='Network issue — retrying in 4 seconds…';
        await new Promise(r=>setTimeout(r,4000)); setp(0); continue;
      }
      txt.innerHTML='<span style="color:var(--danger)">'+(e.message||'Upload failed')+' — please select the file and try again.</span>';
      return;
    }
  }
}
// Direct multipart upload (test-answer jaisa) — live byte-level progress %
function _dppStageXHR(pid,f,onp){
  return new Promise((res,rej)=>{
    const x=new XMLHttpRequest();
    x.open('POST',API+`/api/student/dpp-packs/${pid}/stage`);
    x.setRequestHeader('Authorization','Bearer '+TOKEN);
    x.timeout=10*60*1000;
    x.upload.onprogress=e=>{ if(e.lengthComputable&&e.total>0) onp(Math.min(99,e.loaded/e.total*100)); };
    x.onload=()=>{
      if(x.status>=200&&x.status<300){ try{ res(JSON.parse(x.responseText)); }catch(e){ rej(new Error('Bad response')); } }
      else{ let d='Upload failed ('+x.status+')'; try{ d=JSON.parse(x.responseText).detail||d; }catch(e){} rej(new Error(d)); }
    };
    x.onerror=()=>rej(new TypeError('Failed to fetch'));
    x.ontimeout=()=>rej(new TypeError('Upload timeout — network slow hai'));
    const fd=new FormData(); fd.append('file',f,f.name||'dpp-answer.pdf');
    x.send(fd);
  });
}

// DPP answer upload ke liye tight prep: bada PDF/photo chhota karke hi bhejo
// (warna slow net pe proxy connection kaat deta hai — "Failed to fetch")
async function _prepDppAnswer(file,statusCb){
  const IMG_MAX=2*1024*1024, PDF_TRIG=2*1024*1024, PDF_TARGET=4*1024*1024, HARD=8*1024*1024;
  if(file.type && file.type.startsWith('image/')){
    statusCb&&statusCb('Compressing the photo…');
    let f=await compressIfImage(file,1400,0.72), q=0.6;
    while(f.size>IMG_MAX && q>=0.3){ f=await compressIfImage(file,1400,q); q-=0.15; }
    return {file:f, ok:f.size<=IMG_MAX};
  }
  if(file.type==='application/pdf' && file.size>PDF_TRIG){
    statusCb&&statusCb('Optimizing the PDF for a faster upload…');
    try{ const f=await compressPdf(file,statusCb,PDF_TARGET);
      if(f && f.size<file.size) return {file:f, ok:f.size<=HARD, compressed:true}; }catch(e){}
  }
  return {file, ok:file.size<=HARD};
}
// File server pe staged hai — submit sirf confirm karta hai (INSTANT, koi file transfer nahi)
async function submitDppFile(pid){
  const st=window._dppStaged;
  if(!st||st.pid!==pid){ toast('Let the upload reach 100% first.',true); return; }
  const btn=document.getElementById('dpp-sub-btn'); btn.disabled=true; btn.textContent='Submitting...';
  for(let att=0;att<2;att++){
    try{
      await api(`/api/student/dpp-packs/${pid}/submit-staged`,'POST',{answer_id:st.answer_id});
      try{ closeModal(); }catch(e){}
      toast('DPP submitted! Status: Checking.');
      loadSDpp(); return;
    }catch(e){
      if(att===0 && /fail|fetch|network|reach/i.test(e.message||'')){
        toast('Network issue — 4 sec me dobara try…',true);
        await new Promise(r=>setTimeout(r,4000)); continue;
      }
      toast(e.message||'Submit failed',true); btn.disabled=false; btn.textContent='Submit'; return;
    }
  }
}
