function downloadPaper(id){
  showModal('Paper ka Medium?',
  `<div class="pm-grid" style="margin-top:4px">
    <button class="pm-opt" onclick="closeModal();examPdfStudent(${id},'en',false)"><span class="pm-ic">A</span><span class="pm-tx"><b>English</b></span></button>
    <button class="pm-opt" onclick="closeModal();examPdfStudent(${id},'hi',false)"><span class="pm-ic">\u0905</span><span class="pm-tx"><b>\u0939\u093f\u0902\u0926\u0940</b></span></button>
  </div>`,'');
}
function examSolPick(id){
  showModal('Solutions ka Medium?',
  `<div class="pm-grid" style="margin-top:4px">
    <button class="pm-opt" onclick="closeModal();examPdfStudent(${id},'en',true)"><span class="pm-ic">A</span><span class="pm-tx"><b>English</b></span></button>
    <button class="pm-opt" onclick="closeModal();examPdfStudent(${id},'hi',true)"><span class="pm-ic">\u0905</span><span class="pm-tx"><b>\u0939\u093f\u0902\u0926\u0940</b></span></button>
  </div>`,'');
}
/* student paper/solutions PDF — built on-device from portal data (no answers unless window over) */
async function examPdfStudent(id,medium,withSol){
  try{
    toast('Preparing PDF\u2026');
    const ex=await api('/api/student/exam/'+id);
    const qs=ex.questions||[];
    if(!qs.length){ toast('No questions found.',true); return; }
    if(withSol&&!ex.expired){ toast('Solutions will be available after the test window ends.',true); return; }
    const isM=(ex.test_type==='mcq');
    let logo=null;
    try{ if(ex.teacher_id){ const lr=await fetch(API+'/api/student/teacher/'+ex.teacher_id+'/photo',{headers:{'Authorization':'Bearer '+TOKEN}}); if(lr.ok){ const lb=await lr.blob(); logo=await new Promise(res=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.onerror=()=>res(null);fr.readAsDataURL(lb);}); } } }catch(e){}
    const qLbl=medium==='hi'?'\u092a\u094d\u0930\u0936\u094d\u0928':'Question';
    const mkLbl=m=>medium==='hi'?('[ '+(m||1)+' \u0905\u0902\u0915 ]'):('[ '+(m||1)+' mark'+((m||1)>1?'s':'')+' ]');
    const body=qs.map((q,qi)=>{
      const qno=q.q_no||qi+1;
      const en=q.question_text||'', hi=q.question_text_hi||'';
      const qMain=medium==='hi'?(hi.trim()?hi:en):en;
      let h='';
      // Part A / Part B figures ab _pdfQHTML handle karta hai
      if(isM&&Array.isArray(q.options)&&q.options.length){
        let ci=-1;
        if(withSol&&q.correct_option!=null) ci=q.options.findIndex(o=>String(o).trim()===String(q.correct_option).trim());
        h+='<div class="opts">'+q.options.map((o,oi)=>{
          const oh=(medium==='hi'&&Array.isArray(q.options_hi)&&(q.options_hi[oi]||'').trim())?q.options_hi[oi]:null;
          return '<div class="opt'+(withSol&&ci===oi?' correct':'')+'"><b>'+String.fromCharCode(65+oi)+'</b><span>'+_fmtRich(oh||o)+'</span></div>';
        }).join('')+'</div>';
        if(withSol&&ci>=0&&q.options[ci]!=null){
          const ansO=(medium==='hi'&&Array.isArray(q.options_hi)&&(q.options_hi[ci]||'').trim())?q.options_hi[ci]:q.options[ci];
          h+='<div class="sol"><div class="sol-l">'+(medium==='hi'?'\u0909\u0924\u094d\u0924\u0930':'Answer')+'</div><div class="sol-t"><b>('+String.fromCharCode(65+ci)+')</b> '+_fmtRich(ansO)+'</div>';
          if((q.explanation||'').trim()) h+='<div class="sol-t" style="margin-top:4px">'+_fmtRich(q.explanation)+'</div>';
          h+='</div>';
        }
      }
      if(withSol&&!isM&&(q.model_answer||'').trim()){
        h+='<div class="sol"><div class="sol-l">'+(medium==='hi'?'\u0939\u0932':'Solution')+'</div><div class="sol-t">'+_fmtRich(q.model_answer)+'</div>'+(q.model_answer_image?'<img class="qimg" src="'+q.model_answer_image+'">':'')+'</div>';
      }
      return '<div class="q"><div class="q-h"><b>'+qLbl+' '+qno+'</b><span class="q-m">'+mkLbl(q.max_marks)+'</span></div>'+_pdfQHTML(qMain,q.image_b64,q.alt_image_b64,'q-t')+h+'</div>';
    }).join('');
    const w=window.open('','_blank');
    if(!w){ toast('Popup blocked — please allow popups.',true); return; }
    w.document.write(buildPdfDoc(ex,body,withSol,isM,medium==='hi'?'hi':'en',logo));
    w.document.close();
  }catch(e){ toast(e.message,true); }
}
function examCardHTML(e){
  const isM=e.test_type==='mcq';
  // backend `awarded` bhejta hai; purana card `score` padhta tha -> undefined/45
  const _got=(e.score!=null?e.score:(e.awarded!=null?e.awarded:null));
  const tyPill=isM?`<span class="tx-pill o">OBJECTIVE</span>`:`<span class="tx-pill v">SUBJECTIVE</span>`;
  const topCol=isM?'linear-gradient(90deg,#b8941f,#ffb347)':'linear-gradient(90deg,#a1741a,#d4a94e)';
  let stPill='', right='';
  if(e.status==='graded'){
    const pct=Math.round((_got||0)/(e.total_marks||1)*100);
    const off=(169.6*(1-pct/100)).toFixed(1);
    stPill=`<span class="tx-pill g">CHECKING DONE ✓</span>`;
    right=`<div class="tx-ring"><svg width="60" height="60" viewBox="0 0 60 60"><circle cx="30" cy="30" r="27" fill="none" stroke="var(--border)" stroke-width="5"/><circle cx="30" cy="30" r="27" fill="none" stroke="${pct>=60?'#059669':'#d97706'}" stroke-width="5" stroke-linecap="round" stroke-dasharray="169.6" stroke-dashoffset="${off}"/></svg><div class="t">${pct}%</div></div>`;
  } else if(e.status==='grading'){
    stPill=`<span class="tx-pill a">CHECKING SOON</span>`;
  } else if(e.status==='marking'){
    stPill=`<span class="tx-pill a">MARKING BY TEACHER</span>`;
  }
  const _sch=spSchedOf(e),_future=_sch&&_sch.getTime()>Date.now();
  const _exp=_sch&&Date.now()>(_sch.getTime()+(e.duration_min||60)*60000);
  if(_exp&&!stPill){
    stPill=`<span class="tx-pill s">NOT ATTEMPTED</span>`;
  }
  if(!stPill){
    stPill=_future?`<span class="tx-pill tx-up">UPCOMING</span>`:(isM?`<span class="tx-pill g">INSTANT RESULT</span>`:`<span class="tx-pill s">TEACHER GRADES</span>`);
  }
  const action = e.status==='graded'
    ? `<button class="btn btn-primary btn-sm" onclick="openExamResult(${e.id})">View Result${_got!=null?' \u00b7 '+_got+'/'+e.total_marks:''}</button>`
    : (e.status==='grading'||e.status==='marking')
    ? `<button class="btn btn-ghost btn-sm" disabled>${e.status==='marking'?'Marking by teacher':'Checking soon'}</button>`
    : (_exp?`<button class="btn btn-primary btn-sm" onclick="openExamPlayer(${e.id})">${ic('book')} View Paper</button>`
    : (_future?`<span class="tx-cdchip">Starts in <b data-cd="${_sch.getTime()}">\u2026</b></span>`:`<button class="btn btn-primary btn-sm" onclick="openExamPlayer(${e.id})">Start Test</button>`));
  return `<div class="tx-card ${e.status!=='graded'&&e.status!=='grading'&&e.status!=='marking'?'tx-live':''}"><div class="top" style="background:${topCol}"></div><div class="tx-pad">
    <div style="display:flex;gap:12px;align-items:flex-start;flex-wrap:wrap">
      <span class="tx-tile ${isM?'o':'v'} tx-tlogo" data-tid="${e.teacher_id||''}">${esc(txInit(e.subject||'GEN'))}</span>
      <div style="flex:1;min-width:190px">
        <div style="display:flex;gap:7px;align-items:center;flex-wrap:wrap"><b style="font-size:.93rem">${esc(e.title)}</b>${tyPill}${stPill}</div>
        <div class="tx-meta">
          ${e.subject?`<span class="tx-pill nv inf"><b>${esc(e.subject)}</b></span>`:''}
          ${e.class_name?`<span class="tx-pill s" style="border-color:rgba(4,120,87,.4);color:#047857">${esc(e.class_name)}</span>`:''}
          ${spCleanCh(e.chapter)?`<span class="tx-pill s">${esc(spCleanCh(e.chapter))}</span>`:''}
          <span class="tx-pill s inf">${ic('clipboard')} <b>${e.questions}</b> Qs</span><span class="tx-pill s inf">${ic('chart')} <b>${e.total_marks}</b> marks</span><span class="tx-pill s inf">${ic('clock')} ${e.duration_min?('<b>'+e.duration_min+'</b> min'):'No time limit'}</span>${_sch?`<span class="tx-pill s inf">${ic('calendar')} ${spSchedFmt(_sch)}</span>`:''}
        </div>
      </div>
      ${right}
    </div>
    <div class="tx-acts" style="display:flex;gap:8px;margin-top:13px;justify-content:flex-end;flex-wrap:wrap">
      ${(_future||_exp)?'':`<button class="btn btn-ghost btn-sm" onclick="downloadPaper(${e.id})">${ic('download')} Paper</button>`}
      ${_exp?`<button class="btn btn-ghost btn-sm" onclick="_solHub(${e.id})">${ic('book')} Solutions</button>`:''}
      ${(e.graded||0)>0?`<button class="btn btn-ghost btn-sm" title="Class ranking of this test — attempt na bhi kiya ho to dikh sakta hai" onclick="openExamRanking(${e.id},'student')">${ic('chart')} Ranking</button>`:''}
      ${action}
    </div>
  </div></div>`;
}

/* ================= TEST RANKING (podium + list + compare) ================= */
async function openExamRanking(examId,role){
  role=role||ROLE||'student';
  showModal('Test Ranking','<div class="spinner"></div>','');
  try{
    const d=await api(`/api/${role}/exam/${examId}/ranking`);
    window._rankData=d; window._rankRole=role;
    const rows=d.rows||[];
    if(!rows.length){
      showModal('Test Ranking',`<div class="ws-empty"><div class="big">${ic('chart')}</div><p><b>No evaluated copies yet</b></p><small>Ranking appears as soon as the checking is done.</small></div>`,`<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
      return;
    }
    const medal=['#f59e0b','#a2946d','#b45309'];
    const total=(d.exam&&d.exam.total_marks)||0;
    const bav=(r,sz)=>`<div style="width:${sz}px;height:${sz}px;border-radius:50%;background:linear-gradient(135deg,#b8941f,#a1741a);color:#241a05;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:${Math.round(sz*.42)}px;border:3px solid #fff;box-shadow:0 3px 10px rgba(0,0,0,.18)">${esc((r.name||'?').slice(0,1).toUpperCase())}</div>`;
    const pod=[rows[1],rows[0],rows[2]].filter(Boolean);
    const podHtml=`<div class="trk-podium">${pod.map(r=>{
      const h=r.rank===1?104:r.rank===2?80:66; const sz=r.rank===1?60:50;
      return `<div class="trk-pod trk-click" onclick="rankClick(${r.student_id})"><div class="trk-pod-av" style="position:relative">${bav(r,sz)}<span class="trk-medal" style="background:${medal[r.rank-1]}">${r.rank}</span></div>
        <div class="trk-pod-nm">${esc(r.name)}${(role==='student'&&r.student_id===d.me_id)?' <span class="trk-you">(you)</span>':''}</div><div class="trk-pod-sc">${r.marks}<small>/${total}</small></div>
        <div class="trk-pod-base" style="height:${h}px;background:linear-gradient(180deg,${medal[r.rank-1]}33,${medal[r.rank-1]}0d);border-top:4px solid ${medal[r.rank-1]}"><b>#${r.rank}</b></div></div>`;
    }).join('')}</div>`;
    const meRow=(role==='student'&&d.me_id)?rows.find(r=>r.student_id===d.me_id):null;
    const meHtml=meRow?`<div class="trk-me"><div class="trk-me-l"><div class="trk-me-rank">#${meRow.rank}</div><div><b>Your Rank</b><div class="trk-me-sub">of ${rows.length} students &middot; <b>${meRow.marks}/${total}</b></div></div></div><div class="trk-me-hint">Tap any student to compare</div></div>`:'';
    const list=rows.map(r=>`<div class="sbb-row ${(role==='student'&&r.student_id===d.me_id)?'me':''}" onclick="rankClick(${r.student_id})">
      <span class="sbb-rank ${r.rank<=3?'top':''}">${r.rank}</span>
      <span class="sbb-av">${esc((r.name||'?').slice(0,1).toUpperCase())}</span>
      <div class="sbb-main"><div class="sbb-nm">${esc(r.name)}${(role==='student'&&r.student_id===d.me_id)?' <span class="trk-you">(you)</span>':''}</div></div>
      ${r.attempted!=null?`<span style="font-size:.68rem;color:var(--text-muted)">${r.attempted} Qs</span>`:''}
      <b class="sbb-xp">${r.marks}<small style="font-weight:600;color:var(--text-muted)">/${total}</small></b></div>`).join('');
    showModal(`${esc(d.exam.title||'Test')} — Ranking`,
      `<div style="font-size:.74rem;color:var(--text-muted);margin-bottom:10px">${esc(d.exam.subject||'')}${d.exam.chapter?' &middot; '+esc(d.exam.chapter):''} &middot; ${total} marks &middot; ${d.graded} evaluated</div>
       ${podHtml}${meHtml}<div class="hide-scroll" style="max-height:280px;overflow-y:auto;padding-right:4px">${list}</div>
       ${rows.length>5?`<div class="trk-scroll-hint">Scroll for all ${rows.length} students</div>`:''}`,
      `<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
  }catch(e){ showModal('Test Ranking',errHtml(e),`<button class="btn btn-ghost" onclick="closeModal()">Close</button>`); }
}
function rankClick(sid){
  const d=window._rankData; if(!d) return;
  const role=window._rankRole;
  const r=(d.rows||[]).find(x=>x.student_id===sid); if(!r) return;
  const total=d.exam.total_marks||0;
  if(role==='student'&&d.me_id&&(d.rows||[]).some(x=>x.student_id===d.me_id)){
    const me=(d.rows||[]).find(x=>x.student_id===d.me_id);
    if(sid===d.me_id){
      showModal('That\'s you!',`<p style="font-size:.88rem">You scored <b>${me.marks}/${total}</b> (Rank #${me.rank}). Tap another student to compare.</p>`,`<button class="btn btn-primary btn-sm" onclick="openExamRanking(${d.exam.id},'student')">&larr; Back</button>`);
      return;
    }
    const gap=Math.round((r.marks-me.marks)*10)/10;
    const ahead=gap>0;
    const attL=(r.attempted!=null&&me.attempted!=null)?`<div class="sdet-row"><span>Questions attempted</span><b>${r.attempted} vs ${me.attempted} (you)</b></div>`:'';
    showModal(`${esc(r.name)} — Rank #${r.rank}`,
      `<div class="trk-cmp-head"><div class="trk-cmp-cell"><div class="trk-cmp-score">${me.marks}</div><div class="trk-cmp-who">You &middot; Rank #${me.rank}</div></div>
        <div class="trk-cmp-diff ${ahead?'behind':'ahead'}">${ahead?gap+' marks behind':Math.abs(gap)+' marks ahead'}</div>
        <div class="trk-cmp-cell"><div class="trk-cmp-score">${r.marks}</div><div class="trk-cmp-who">${esc(r.name)} &middot; Rank #${r.rank}</div></div></div>
      <div class="sdet-grid" style="grid-template-columns:1fr;margin-top:6px">${attL}</div>
      ${ahead?`<div class="trk-sugg"><b>&#128161; Rank #${r.rank} tak kaise pahunche:</b><div class="trk-sugg-note">Aapko <b>${gap} marks</b> aur chahiye. Solutions dekho, galtiyan note karo aur agle test mein unhi topics ko strong karo — har question ki practice se gap band ho jayega.</div></div>`
            :`<div class="trk-sugg"><b>&#127881; You are ahead!</b><div class="trk-sugg-note">${esc(r.name)} se aap <b>${Math.abs(gap)} marks</b> aage ho. Aise hi consistent raho.</div></div>`}`,
      `<button class="btn btn-ghost" onclick="openExamRanking(${d.exam.id},'student')">&larr; Back</button><button class="btn btn-primary btn-sm" onclick="closeModal()">Close</button>`);
  }else{
    // teacher / admin — student detail card
    showModal(`${esc(r.name)} — Test Details`,
      `<div class="sdet-grid" style="grid-template-columns:1fr 1fr">
        <div class="sdet-row"><span>Rank</span><b>#${r.rank} of ${d.graded}</b></div>
        <div class="sdet-row"><span>Marks</span><b>${r.marks} / ${total}</b></div>
        ${r.attempted!=null?`<div class="sdet-row"><span>Questions attempted</span><b>${r.attempted}</b></div>`:''}
        ${r.batch?`<div class="sdet-row"><span>Batch</span><b>${esc(r.batch)}</b></div>`:''}
      </div>`,
      `<button class="btn btn-ghost" onclick="openExamRanking(${d.exam.id},'${role}')">&larr; Back</button><button class="btn btn-primary btn-sm" onclick="closeModal()">Close</button>`);
  }
}
/* ================= DPP RANKING (earliest submission first — podium + full list) ================= */
async function openDppRanking(pid,role){
  role=role||ROLE||'student';
  showModal('DPP Ranking','<div class="spinner"></div>','');
  try{
    const d=await api(`/api/${role}/dpp-packs/${pid}/ranking`);
    window._dppRankData=d; window._dppRankRole=role; window._dppRankPid=pid;
    const rows=d.rows||[];
    const pk=d.pack||{};
    const pkLine=`${esc(pk.subject||'')}${pk.chapter?' &middot; '+esc(pk.chapter):''}${pk.part?' &middot; '+esc(pk.part):' &middot; Whole Chapter'}${pk.class_name?' &middot; Class '+esc(pk.class_name):''}`;
    if(!rows.length){
      showModal(`${esc(pk.title||'DPP')} — Ranking`,`<div class="ws-empty"><div class="big">${ic('chart')}</div><p><b>Kisi ne abhi submit nahi kiya</b></p><small>Jaise hi pehla student submit karega, ranking yaha dikhne lagegi.</small></div>`,`<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
      return;
    }
    const canClick=(role==='teacher'||role==='admin');
    const medal=['#f59e0b','#a2946d','#b45309'];
    const stChip=r=>r.status==='checked'
      ?`<span class="dpp-rk-st ok">${ic('check')} Checked</span>`
      :`<span class="dpp-rk-st">${ic('clock')} Submitted</span>`;
    const bav=(r,sz)=>`<div style="width:${sz}px;height:${sz}px;border-radius:50%;background:linear-gradient(135deg,#b8941f,#a1741a);color:#241a05;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:${Math.round(sz*.42)}px;border:3px solid #fff;box-shadow:0 3px 10px rgba(0,0,0,.18)">${esc((r.name||'?').slice(0,1).toUpperCase())}</div>`;
    const youTag=r=>(role==='student'&&r.me)?' <span class="trk-you">(you)</span>':'';
    const pod=[rows[1],rows[0],rows[2]].filter(Boolean);
    const podHtml=`<div class="trk-podium">${pod.map(r=>{
      const h=r.rank===1?104:r.rank===2?80:66; const sz=r.rank===1?60:50;
      const click=canClick?` trk-click" onclick="dppRankStudent(${r.rank})`:` nosel`;
      return `<div class="trk-pod${click}"><div class="trk-pod-av" style="position:relative">${bav(r,sz)}<span class="trk-medal" style="background:${medal[r.rank-1]}">${r.rank}</span></div>
        <div class="trk-pod-nm">${esc(r.name)}${youTag(r)}</div><div class="trk-pod-sc dpp-rk-time">${esc((r.submitted_at||'').split(',')[0])}</div>
        <div class="trk-pod-base" style="height:${h}px;background:linear-gradient(180deg,${medal[r.rank-1]}33,${medal[r.rank-1]}0d);border-top:4px solid ${medal[r.rank-1]}"><b>#${r.rank}</b></div></div>`;
    }).join('')}</div>`;
    const meRow=(role==='student')?rows.find(r=>r.me):null;
    const meHtml=meRow?`<div class="trk-me"><div class="trk-me-l"><div class="trk-me-rank">#${meRow.rank}</div><div><b>Your Rank</b><div class="trk-me-sub">of ${rows.length} submissions &middot; ${esc(meRow.submitted_at||'')}</div></div></div></div>`:'';
    const list=rows.map(r=>`<div class="sbb-row${r.me?' me':''}${canClick?' trk-click':''}" ${canClick?`onclick="dppRankStudent(${r.rank})"`:''}>
      <span class="sbb-rank ${r.rank<=3?'top':''}">${r.rank}</span>
      <span class="sbb-av">${esc((r.name||'?').slice(0,1).toUpperCase())}</span>
      <div class="sbb-main"><div class="sbb-nm">${esc(r.name)}${youTag(r)}</div><div class="sbb-sub">${esc(r.submitted_at||'')}</div></div>
      ${stChip(r)}</div>`).join('');
    showModal(`${esc(pk.title||'DPP')} — Ranking`,
      `<div style="font-size:.74rem;color:var(--text-muted);margin-bottom:10px">${pkLine} &middot; <b>${rows.length}</b> submission${rows.length>1?'s':''} &middot; sabse pehle submit = Rank 1</div>
       ${podHtml}${meHtml}<div class="hide-scroll" style="max-height:260px;overflow-y:auto;padding-right:4px">${list}</div>
       ${rows.length>5?`<div class="trk-scroll-hint">Scroll for all ${rows.length} submissions</div>`:''}`,
      `<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
  }catch(e){ showModal('DPP Ranking',errHtml(e),`<button class="btn btn-ghost" onclick="closeModal()">Close</button>`); }
}
function dppRankStudent(rank){
  const d=window._dppRankData; if(!d) return;
  const role=window._dppRankRole; const pid=window._dppRankPid;
  const r=(d.rows||[]).find(x=>x.rank===rank); if(!r) return;
  showModal(`${esc(r.name)} — DPP Details`,
    `<div class="sdet-grid" style="grid-template-columns:1fr 1fr">
      <div class="sdet-row"><span>Rank</span><b>#${r.rank} of ${d.count||d.rows.length}</b></div>
      <div class="sdet-row"><span>Status</span><b>${r.status==='checked'?'Checked':'Submitted'}</b></div>
      <div class="sdet-row"><span>Submitted</span><b>${esc(r.submitted_at||'—')}</b></div>
      ${r.class_name?`<div class="sdet-row"><span>Class</span><b>${esc(r.class_name)}</b></div>`:''}
      ${r.phone?`<div class="sdet-row"><span>Phone</span><b>${esc(r.phone)}</b></div>`:''}
      ${r.filename?`<div class="sdet-row"><span>File</span><b>${esc(r.filename)}</b></div>`:''}
      ${r.checked_at?`<div class="sdet-row"><span>Checked at</span><b>${esc(r.checked_at)}</b></div>`:''}
      ${r.checked_by?`<div class="sdet-row"><span>Checked by</span><b>${esc(r.checked_by)}</b></div>`:''}
    </div>
    ${r.remarks?`<div class="sdet-row" style="margin-top:8px;flex-direction:column;align-items:flex-start;gap:4px"><span>Remarks</span><b style="font-weight:600">${esc(r.remarks)}</b></div>`:''}`,
    `<button class="btn btn-ghost" onclick="openDppRanking(${pid},'${role}')">&larr; Back</button><button class="btn btn-primary btn-sm" onclick="closeModal()">Close</button>`);
}
/* ================= DPP VIEW/DOWNLOAD TRACKER (teacher/admin — clickable chips) ================= */
async function openDppTrack(pid,event){
  const role=(ROLE==='admin')?'admin':'teacher';
  showModal('DPP Tracker','<div class="spinner"></div>','');
  try{
    const d=await api(`/api/${role}/dpp-packs/${pid}/track-list?event=${event}`);
    const rows=d.rows||[];
    const isV=d.event==='view';
    const title=`${esc((d.pack&&d.pack.title)||'DPP')} — ${isV?'Views':'Downloads'}`;
    if(!rows.length){
      showModal(title,`<div class="ws-empty"><div class="big">${ic(isV?'eye':'download')}</div><p><b>Abhi kisi ne ${isV?'view':'download'} nahi kiya</b></p><small>Jaise hi students DPP ${isV?'kholenge':'download karenge'}, unke naam yaha aa jayenge.</small></div>`,`<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
      return;
    }
    const list=rows.map((r,i)=>`<div class="sbb-row nosel">
      <span class="sbb-rank ${i<3?'top':''}">${i+1}</span>
      <span class="sbb-av">${esc((r.name||'?').slice(0,1).toUpperCase())}</span>
      <div class="sbb-main"><div class="sbb-nm">${esc(r.name)}</div><div class="sbb-sub">${esc(r.at||'')}</div></div>
      <span class="dpp-rk-st${isV?'':' ok'}">${ic(isV?'eye':'download')} ${isV?'Viewed':'Downloaded'}</span></div>`).join('');
    showModal(title,
      `<div style="font-size:.74rem;color:var(--text-muted);margin-bottom:10px"><b>${rows.length}</b> student${rows.length>1?'s':''} ne ${isV?'DPP kholi (view)':'PDF download ki'} &middot; latest pehle</div>
       <div class="hide-scroll" style="max-height:300px;overflow-y:auto;padding-right:4px">${list}</div>
       ${rows.length>6?`<div class="trk-scroll-hint">Scroll for all ${rows.length} students</div>`:''}`,
      `<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
  }catch(e){ showModal('DPP Tracker',errHtml(e),`<button class="btn btn-ghost" onclick="closeModal()">Close</button>`); }
}
/* ================= STUDENT TEST PLAYER v2 =================
   medium selection at start + in-test medium toggle + live timer + MCQ palette
   + review-and-submit (attempted / not-answered) + thank-you stats screen */
let _plMed='en', _plTimerI=null, _plAns={}, _plRev={};
function _plStart(id){
  const sk='mvs_start_'+id;
  if(!localStorage.getItem(sk)) localStorage.setItem(sk,String(Date.now()));
  return parseInt(localStorage.getItem(sk))||Date.now();
}
function _plDurLeft(ex){
  if(!ex.duration_min)return null;
  const sch=spSchedOf(ex);
  if(sch) return sch.getTime()+ex.duration_min*60000-Date.now();   // fixed window end
  return _plStart(ex.id)+ex.duration_min*60000-Date.now();
}
async function openExamPlayer(id){
  navPushView('player');
  const el=document.getElementById('s-tests-content'); softSpin(el);
  try{
    const ex=await api('/api/student/exam/'+id);
    ex.id=id;
    window._curExam=ex; window._examFile=null; _plAns={}; _plRev={};
    if(ex.already_submitted){ openExamResult(id); return; }
    const _gsch0=spSchedOf(ex);
    if(!_gsch0&&ex.duration_min){ const _k='mvs_start_'+id,_st=+localStorage.getItem(_k)||0;
      if(_st&&_st+ex.duration_min*60000<=Date.now()) localStorage.removeItem(_k); }
    const _gsch=spSchedOf(ex);
    if(_gsch&&_gsch.getTime()>Date.now()){ el.innerHTML=`<div class="pl-head"><button class="btn btn-ghost btn-sm" title="Back" onclick="loadSTests()">${ic('back')}</button><div class="pl-title">${esc(ex.title||'Test')}</div></div><div class="card"><div class="card-body"><div class="ws-empty"><div class="big">${ic('clock')}</div><p><b>This test is scheduled</b></p><small>Start time: ${spSchedFmt(_gsch)} — a live countdown is running on the Tests page.</small></div></div></div>`; return; }
    const _gend=_gsch?(_gsch.getTime()+(ex.duration_min||60)*60000):null;
    if(_gend&&Date.now()>_gend){ _expiredView(el,ex,id); return; }
    _plStart(id);
    if(ex.medium==='Bilingual'){ _plMediumScreen(id); }
    else { _plMed=(ex.medium==='Hindi')?'hi':'en'; await _plRender(id); }
  }catch(e){ el.innerHTML=errHtml(e); }
}
/* test window over: view-only mode with paper + solutions */
function _expiredView(el,ex,id){
  // Ye SIRF question paper hai - solutions alag "Solutions" button se khulte
  // hain, isliye yahan koi answer/solution nahi dikhaya jaata
  const qs=ex.questions||[], isM=ex.test_type==='mcq';
  const list=qs.map((q,i)=>{
    const no=q.q_no||i+1;
    // question text + uske figures (OR wale question me dono parts ke)
    const body=_qBodyHTML(q.question_text||'', q.image_b64||null, q.alt_image_b64||null);
    const opts=(isM&&Array.isArray(q.options)&&q.options.length)
      ? `<div class="exp-opts">${q.options.map((o,oi)=>`<div class="exp-opt"><b>(${String.fromCharCode(65+oi)})</b> <span>${_fmtRich(o)}</span></div>`).join('')}</div>`
      : '';
    return `<div class="exp-q"><div class="pl-qtop"><div class="exp-qt"><b>Q${no}.</b> ${body}</div><span class="pl-marks">${q.max_marks} marks</span></div>${opts}</div>`;
  }).join('');
  el.innerHTML=`<div class="pl-head pl-sticky"><div class="pl-band"><button class="btn btn-ghost btn-sm" title="Back" onclick="loadSTests()">${ic('back')}</button><div style="flex:1;min-width:180px"><div class="pl-title">${esc(ex.title)}</div><div class="pl-info">${ex.subject?`<span class="pl-sub">${esc(ex.subject)}</span> \u00b7 `:''}${qs.length} questions \u00b7 ${ex.total_marks} marks${ex.teacher_name?' \u00b7 By '+esc(ex.teacher_name):''}</div></div><span class="tx-pill tx-up">WINDOW OVER</span></div></div>
  <div class="pl-note">${ic('clock')} The test window is over, so this test can no longer be attempted. This is the question paper. Use the Solutions button on the Tests page to see the answers.</div>
  <div style="display:flex;gap:8px;flex-wrap:wrap;margin:12px 0 16px"><button class="btn btn-ghost btn-sm" onclick="downloadPaper(${id})">${ic('download')} Download Paper</button></div>
  ${list||'<div class="tx-empty"><b>No questions</b></div>'}`;
  renderMath(el);
  _txLoadLogos(el);
}
function _plMediumScreen(id){
  const ex=window._curExam, el=document.getElementById('s-tests-content');
  el.innerHTML=`<div class="pl-head"><button class="btn btn-ghost btn-sm" title="Back" onclick="loadSTests()">${ic('back')}</button><div class="pl-title">${esc(ex.title||'Test')}</div></div>
  <div class="pl-mp"><div class="pl-mp-t">Select Medium · माध्यम चुनें</div>
  <div class="pm-grid" style="margin-top:16px">
    <button class="pm-opt" onclick="_plSetMed('en',${id})"><span class="pm-ic">A</span><span class="pm-tx"><b>English</b></span></button>
    <button class="pm-opt" onclick="_plSetMed('hi',${id})"><span class="pm-ic">अ</span><span class="pm-tx"><b>हिंदी</b></span></button>
    <button class="pm-opt" onclick="_plSetMed('hg',${id})"><span class="pm-ic" style="font-size:.8rem">Aअ</span><span class="pm-tx"><b>Hinglish</b></span></button>
  </div></div>`;
}
async function _plSetMed(m,id){ _plMed=m; await _plRender(id); const el=document.getElementById('s-tests-content'); el.scrollIntoView(); window.scrollTo(0,0); }
async function _plEnsureHi(){
  const ex=window._curExam, sub=spDetectSubject((ex.subject||'')+' '+(ex.title||''));
  const jobs=[];
  ex.questions.forEach(q=>{
    if(!(q.question_text_hi||q.question_hi||q._hiT)&&(q.question_text||'').trim()) jobs.push(async()=>{ const t=await spTranslate(q.question_text,sub); if(t)q._hiT=t; });
    if(Array.isArray(q.options)){ q._hiO=q._hiO||[]; q.options.forEach((o,j)=>{ if(!((q.options_hi||[])[j])&&!q._hiO[j]&&(o||'').trim()) jobs.push(async()=>{ const t=await spTranslate(o,sub); if(t)q._hiO[j]=t; }); }); }
  });
  if(!jobs.length)return;
  toast('Translating to Hindi…');
  for(let i=0;i<jobs.length;i+=4){ await Promise.all(jobs.slice(i,i+4).map(f=>f())); }
}
function _plQText(q){
  const en=(q.question_text||''), hi=(q.question_text_hi||q.question_hi||q._hiT||'');
  if(_plMed==='hi') return hi||en;
  if(_plMed==='hg') return (hi&&hi.trim()!==en.trim())?(en+'\n'+hi):en;
  return en;
}
function _plOptText(q,j){
  const en=q.options[j], hi=((q.options_hi||[])[j])||((q._hiO||[])[j])||'';
  if(_plMed==='hi') return hi||en;
  if(_plMed==='hg') return (hi&&hi.trim()!==String(en).trim())?(en+' · '+hi):en;
  return en;
}
function _qBodyHTML(text, img, altImg){
  // OR wale question me: Part A -> uska figure -> OR -> Part B -> uska figure
  const im=src=>src?`<img class="pl-qimg" src="${src}">`:'';
  const sp=_splitOr(text);
  if(sp.b===null||!altImg) return `<div class="pl-qtext">${_fmtRich(text)}</div>${im(img)}`;
  return `<div class="pl-qtext">${_fmtRich(sp.a)}</div>${im(img)}`
    +`<div class="pl-qtext"><span class="rt-or">OR</span></div>`
    +`<div class="pl-qtext">${_fmtRich(sp.b)}</div>${im(altImg)}`;
}
async function _plRender(id){
  const ex=window._curExam, el=document.getElementById('s-tests-content');
  const isM=ex.test_type==='mcq';
  if(isM){ ex.questions.forEach(q=>{ const s=document.querySelector('input[name="pl-'+q.q_no+'"]:checked'); if(s)_plAns[q.q_no]=s.value; }); }
  if(_plMed==='hi'||_plMed==='hg'){ softSpin(el); await _plEnsureHi(); }
  const biling=ex.medium==='Bilingual';
  const qs=ex.questions.map(q=>{
    const qBody=_qBodyHTML(_plQText(q), q.image_b64, q.alt_image_b64);
    const qtext=`<div class="pl-qtop"><div class="pl-qtext-wrap">${qBody}</div><span class="pl-marks">${q.max_marks} marks</span></div>`;
    if(isM){
      const opts=(q.options||[]).map((o,idx)=>`<label class="pl-opt"><input type="radio" name="pl-${q.q_no}" value="${esc(o)}" ${_plAns[q.q_no]===o?'checked':''} onchange="_plPal()"><span>${_fmtRich(_plOptText(q,idx))}</span></label>`).join('');
      return `<div class="pl-q" id="plq-${q.q_no}"><div class="pl-qnum">${q.q_no}</div><div class="pl-qbody">${qtext}<div class="pl-opts">${opts}</div></div></div>`;
    }
    return `<div class="pl-q" id="plq-${q.q_no}"><div class="pl-qnum">${q.q_no}</div><div class="pl-qbody">${qtext}</div></div>`;
  }).join('');
  const palette=isM?`<div class="pl-pal">${ex.questions.map(q=>`<button type="button" class="pl-pn" id="plpn-${q.q_no}" onclick="document.getElementById('plq-${q.q_no}').scrollIntoView({behavior:'smooth',block:'center'})">${q.q_no}</button>`).join('')}</div>`:'';
  const medToggle=biling?`<select class="pl-msel" title="Language / माध्यम" onchange="_plSetMed(this.value,${id})"><option value="en"${_plMed==='en'?' selected':''}>English</option><option value="hi"${_plMed==='hi'?' selected':''}>हिंदी</option><option value="hg"${_plMed==='hg'?' selected':''}>Hinglish</option></select>`:'';
  const timer=ex.duration_min?`<div class="pl-timer" id="pl-timer">${ic('clock')} <b>--:--:--</b></div>`:'';
  const upload=!isM?`<div class="pl-upload"><div class="pl-up-title">Upload your handwritten answer sheet</div><div class="pl-up-desc">Write all answers on paper with question numbers, then upload a clear photo (or PDF). Your teacher will check each question and give marks with remarks.</div><input type="file" id="pl-file" accept="image/*,application/pdf" onchange="_examPickFile(this)"><div id="pl-file-name" class="pl-file-name"></div></div>`:'';
  el.innerHTML=`<div class="pl-head pl-sticky"><div class="pl-band"><button class="btn btn-ghost btn-sm" title="Back" onclick="loadSTests()">${ic('back')}</button><div style="flex:1;min-width:180px"><div class="pl-title">${esc(ex.title)}</div><div class="pl-info">${ex.subject?`<span class="pl-sub">${esc(ex.subject)}</span> · `:''}${ex.questions.length} questions · ${ex.total_marks} marks${ex.teacher_name?' · <span class="pl-tlogo" data-tid="'+(ex.teacher_id||'')+'"></span>By '+esc(ex.teacher_name):''}</div></div><div class="pl-head-r">${medToggle}${timer}</div></div></div>${palette}<div class="pl-qs">${qs}</div>${upload}<button class="btn btn-primary" style="width:100%;margin-top:14px" onclick="_plReview(${id})">Review & Submit</button>`;
  renderMath(el); _plPal(); _plTimerStart(ex); _txLoadLogos(el);
}
function _plPal(){
  const ex=window._curExam; if(!ex||ex.test_type!=='mcq')return;
  ex.questions.forEach(q=>{
    const s=document.querySelector('input[name="pl-'+q.q_no+'"]:checked');
    if(s)_plAns[q.q_no]=s.value;   // har selection turant _plAns me save (review page pe DOM chala jaata hai)
    const pn=document.getElementById('plpn-'+q.q_no); if(!pn)return;
    pn.classList.toggle('done',!!s);
  });
}
function _plTimerStart(ex){
  if(_plTimerI){ clearInterval(_plTimerI); _plTimerI=null; }
  if(!ex.duration_min)return;
  const tick=()=>{
    const t=document.getElementById('pl-timer'); if(!t){ clearInterval(_plTimerI); _plTimerI=null; return; }
    let left=_plDurLeft(ex); if(left==null)return;
    const over=left<=0; if(over)left=0;
    const s=Math.floor(left/1000);
    const h=String(Math.floor(s/3600)).padStart(2,'0'), m=String(Math.floor((s%3600)/60)).padStart(2,'0'), ss=String(s%60).padStart(2,'0');
    t.innerHTML=`${ic('clock')} <b>${h}:${m}:${ss}</b>`;
    t.classList.toggle('over',over);
    t.title=over?'Time over — please submit now':'Time remaining';
  };
  tick(); _plTimerI=setInterval(tick,1000);
}
/* ---- review & submit (attempted / not-answered marking) ---- */
function _plReview(id){
  const ex=window._curExam;
  const isM=ex.test_type==='mcq';
  _plRev={};
  ex.questions.forEach(q=>{
    if(isM){ const s=document.querySelector('input[name="pl-'+q.q_no+'"]:checked'); _plRev[q.q_no]=!!s; if(s)_plAns[q.q_no]=s.value; }
    else _plRev[q.q_no]=true;
  });
  const el=document.getElementById('s-tests-content');
  const rows=ex.questions.map(q=>{
    const att=_plRev[q.q_no];
    return `<div class="pl-rv-row" id="plrv-${q.q_no}"><div class="pl-rv-q"><b>Q${q.q_no}</b><span>${q.max_marks} marks</span></div><div class="pl-rv-tg"><button class="${att?'on':''}" onclick="_plRvSet(${q.q_no},true)">Attempted</button><button class="${!att?'off-on':''}" onclick="_plRvSet(${q.q_no},false)">Not answered</button></div></div>`;
  }).join('');
  el.innerHTML=`<div class="pl-head"><button class="btn btn-ghost btn-sm" onclick="_plRender(${id})">${ic('back')} Back to questions</button><div class="pl-title">Review & Submit</div></div>
  <div class="card"><div class="card-body">
    <div class="pl-rv-t">Mark the questions you actually attempted</div>
    <div class="pl-rv-s">Keep the questions you actually answered as <b>Attempted</b> and mark the ones you skipped as <b>Not answered</b> — this ensures your teacher receives an accurate report.</div>
    <div class="pl-rv-list">${rows}</div>
    <div class="pl-rv-sum" id="pl-rv-sum"></div>
    <button class="btn btn-primary" style="width:100%;margin-top:12px" onclick="_plSubmit(${id})">Confirm & Submit Test</button>
  </div></div>`;
  _plRvSum();
}
function _plRvSet(qno,att){
  _plRev[qno]=att;
  const row=document.getElementById('plrv-'+qno);
  if(row){ const bs=row.querySelectorAll('button'); bs[0].classList.toggle('on',att); bs[1].classList.toggle('off-on',!att); }
  _plRvSum();
}
function _plRvSum(){
  const ex=window._curExam; let att=0,attM=0,sk=0,skM=0;
  ex.questions.forEach(q=>{ if(_plRev[q.q_no]){ att++; attM+=q.max_marks||0; } else { sk++; skM+=q.max_marks||0; } });
  const el=document.getElementById('pl-rv-sum');
  if(el)el.innerHTML=`<div><b>${att}</b><span>Attempted</span></div><div><b>${attM}</b><span>Attempt marks</span></div><div><b>${sk}</b><span>Not answered</span></div><div><b>${skM}</b><span>Skipped marks</span></div>`;
}
async function _plSubmit(id){
  const ex=window._curExam; let body={};
  const attempted=[], skipped=[];
  ex.questions.forEach(q=>{ (_plRev[q.q_no]?attempted:skipped).push(q.q_no); });
  if(ex.test_type==='mcq'){
    const ans={};
    for(const q of ex.questions){ const sel=document.querySelector('input[name="pl-'+q.q_no+'"]:checked'); const v=(sel?sel.value:_plAns[q.q_no]); if(v!=null&&v!=='')ans[q.q_no]=v; }
    body={mcq_answers:ans};
  } else {
    if(!window._examFile){ toast('Please upload your handwritten answer sheet',true); return; }
    if(window._examFile.size>MAXB){
      toast('Large file \u2014 compressing automatically\u2026');
      try{ const _r=await smartCompress(window._examFile,m=>toast(m)); if(_r&&_r.ok&&_r.file) window._examFile=_r.file; }catch(e){}
      if(window._examFile.size>MAXB){ toast('The file is still too large after compression. Please upload a smaller scan or photo.',true); return; }
    }
    const b64=await _fileB64(window._examFile);
    body={answer_image_b64:b64, mime_type:window._examFile.type||'image/jpeg'};
  }
  body.attempted=attempted; body.skipped=skipped;
  const el=document.getElementById('s-tests-content'); softSpin(el);
  try{
    const r=await api('/api/student/exam/'+id+'/submit','POST',body);
    if(_plTimerI){ clearInterval(_plTimerI); _plTimerI=null; }
    let attM=0,skM=0;
    ex.questions.forEach(q=>{ if(_plRev[q.q_no])attM+=q.max_marks||0; else skM+=q.max_marks||0; });
    const allDone=skipped.length===0;
    const tName=ex.teacher_name||'your teacher';
    el.innerHTML=`<div class="pl-thanks">
      <div class="pl-thanks-ic">${ic('check')}</div>
      <div class="pl-thanks-msg">Thank you!</div>
      <div class="pl-thanks-note">Your answer sheet has been sent to <b>${esc(tName)}</b>.${allDone?' <b>Excellent</b> — you attempted every question!':''} Your result will be available soon — you can keep checking the <b>Result Status</b> tab.</div>
      <div class="pl-tstats"><div><b>${attempted.length}</b><span>Attempted</span></div><div><b>${attM}</b><span>Attempt marks</span></div><div><b>${skipped.length}</b><span>Not answered</span></div><div><b>${skM}</b><span>Skipped marks</span></div></div>
      <div class="tx-pill a" style="margin-top:14px">CHECKING SOON</div>
      <button class="btn btn-primary" onclick="${r.status==='graded'?('openExamResult('+id+')'):'loadSTests()'}" style="margin-top:16px">${r.status==='graded'?'View Result':'Back to Tests'}</button></div>`;
  }catch(e){ el.innerHTML=errHtml(e)+`<div style="margin-top:10px"><button class="btn btn-ghost btn-sm" onclick="openExamPlayer(${id})">Try Again</button></div>`; }
}
function _examPickFile(inp){ const f=inp.files[0]; window._examFile=f; const n=document.getElementById('pl-file-name'); if(n) n.textContent=f?('Selected: '+f.name):''; }
function _fileB64(file){ return new Promise((res,rej)=>{ const r=new FileReader(); r.onload=()=>res(r.result); r.onerror=rej; r.readAsDataURL(file); }); }

async function downloadMyAnswer(id){
  try{
    toast('Preparing your answer sheet\u2026');
    const r=await fetch(API+'/api/student/exam/'+id+'/answer',{headers:{Authorization:'Bearer '+TOKEN}});
    if(!r.ok){ toast('Answer sheet not available',true); return; }
    const blob=await r.blob();
    const u=URL.createObjectURL(blob);
    const ext=(blob.type&&blob.type.indexOf('pdf')>=0)?'pdf':(blob.type&&blob.type.indexOf('png')>=0)?'png':'jpg';
    const a=document.createElement('a'); a.href=u; a.download='my-answer-sheet.'+ext; document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(u),4000);
  }catch(e){ toast('Could not download answer sheet',true); }
}
async function openExamResult(id){
  navPushView('result');
  const el=document.getElementById('s-tests-content'); softSpin(el);
  try{
    const r=await api('/api/student/exam/'+id+'/result');
    window._lastResult=r; r.id=id;
    if(r.status!=='graded'){
      const marking=r.status==='marking';
      el.innerHTML=`<div class="pl-head"><button class="btn btn-ghost btn-sm" title="Back" onclick="loadSTests()">${ic('back')}</button><div class="pl-title">${esc(r.title||'Test')}</div></div><div class="card"><div class="card-body"><div class="ws-empty"><div class="big">${ic(marking?'edit':'clock')}</div><p><b>${marking?'Marking by teacher':'Checking soon'}</b></p><small>${marking?'The teacher is checking your answer sheet — your marks will appear here shortly.':'Your answer sheet is with your teacher. Marks will appear here once checking starts.'}</small></div></div></div>`;
      return;
    }
    const pct=r.total_marks?Math.round(r.total_awarded/r.total_marks*100):0;
    const vClass=r.verdict==='Excellent'?'exc':r.verdict==='Good'?'good':'imp';
    const biling=r.medium==='Bilingual';
    const isMcq=r.test_type==='mcq';
    const items=r.results.map(it=>{
      if(isMcq&&it.correct_answer!==undefined){
        const ok=!!it.is_correct;
        const your=(it.your_answer===null||it.your_answer===undefined||it.your_answer==='')?'Not answered':it.your_answer;
        const ex_=(biling&&it.explanation_hi)?(it.explanation||'')+'\n'+it.explanation_hi:(it.explanation||'');
        return `<div class="rs-q ${ok?'rs-ok':'rs-bad'}"><div class="rs-qhead"><div class="rs-qtext"><b>Q${it.q_no}.</b> ${_fmtRich(it.question)}${(biling&&it.question_hi)?`<div class="rs-qtext-hi">${_fmtRich(it.question_hi)}</div>`:''}</div><div class="rs-marks">${it.marks}/${it.max}</div></div><div class="rs-ans-row ${ok?'ok':'bad'}"><span class="rs-ans-ic">${ok?ic('check'):'<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg>'}</span><span><b>Your answer:</b> ${_fmtRich(String(your))}</span></div>${ok?'':`<div class="rs-ans-row ok"><span class="rs-ans-ic">${ic('check')}</span><span><b>Correct answer:</b> ${_fmtRich(String(it.correct_answer||''))}</span></div>`}${ex_?`<div class="rs-expl"><b>Explanation:</b> ${_fmtRich(ex_)}</div>`:''}</div>`;
      }
      return `<div class="rs-q"><div class="rs-qhead"><div class="rs-qtext"><b>Q${it.q_no}.</b> ${_fmtRich(it.question)}${(biling&&it.question_hi)?`<div class="rs-qtext-hi">${_fmtRich(it.question_hi)}</div>`:''}</div><div class="rs-marks">${it.marks}/${it.max}</div></div>${it.remark?`<div class="rs-remark">${esc(it.remark)}</div>`:''}</div>`;
    }).join('');
    const st=localStorage.getItem('mvs_start_'+id);
    const dur=r.duration_min||r.duration||0;
    let dlBlock='';
    if(dur&&st){ const left=parseInt(st)+dur*60000-Date.now(); if(left>0)dlBlock=`<span class="rs-dl-note">The answer sheet download will be available after the test duration ends.</span>`; }
    const hasSol=isMcq||((r.results||[]).some(it=>it.model_answer||it.model));
    el.innerHTML=`<div class="pl-head"><button class="btn btn-ghost btn-sm" title="Back" onclick="loadSTests()">${ic('back')}</button><div class="pl-title">${esc(r.title)} — Result</div></div><div class="rs-score-card"><div><div class="rs-score-big">${r.total_awarded}/${r.total_marks}</div><div class="rs-score-sub">${pct}% scored</div></div><div class="rs-verdict ${vClass}">${esc(r.verdict||'')}</div></div><div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:10px 0"><span class="tx-pill g">CHECKING DONE ✓</span>${hasSol?`<button class="btn btn-primary btn-sm" onclick="_solHub(${id})">Solutions</button>`:''}${r.has_answer?(dlBlock||`<button class="btn btn-ghost btn-sm" onclick="downloadMyAnswer(${id})">${ic('download')} Download My Answer Sheet</button>`):''}</div><div class="rs-list">${items}</div>${(r.feedback||'').trim()?`<div class="rs-feedback"><div class="rs-fb-title">Teacher's Suggestion <span class="rs-fb-lang"><button class="on" id="rsfb-en" onclick="rsFbLang('en')">EN</button><button id="rsfb-hi" onclick="rsFbLang('hi')">हिंदी</button></span></div><div class="rs-fb-text" id="rs-fb-text" data-en="${esc(r.feedback)}">${esc(r.feedback)}</div><div class="rs-fb-teacher">— ${esc(r.teacher_name||'Your Teacher')}</div></div>`:''}`;
    renderMath(el);
  }catch(e){ el.innerHTML=errHtml(e); }
}
async function rsFbLang(m){
  const box=document.getElementById('rs-fb-text'); if(!box)return;
  const enB=document.getElementById('rsfb-en'), hiB=document.getElementById('rsfb-hi');
  if(enB)enB.classList.toggle('on',m==='en'); if(hiB)hiB.classList.toggle('on',m==='hi');
  if(m==='en'){ box.textContent=box.dataset.en||box.textContent; return; }
  const en=box.dataset.en||box.textContent;
  const sub=spDetectSubject(((window._lastResult||{}).subject||'')+' '+((window._lastResult||{}).title||''));
  const t=await spTranslate(en,sub);
  if(t)box.textContent=t;
}
