async function _solData(id,med){
  let r=window._lastResult;
  if(!r||r.id!==id){
    try{ r=await api('/api/student/exam/'+id+'/result'); }
    catch(err){
      // Jis student ne test attempt hi nahi kiya uske liye result nahi hota -
      // window khatam hone ke baad exam detail me hi solutions aa jate hain
      const d=await api('/api/student/exam/'+id);
      const ex=d.exam||d;
      r={ id:id, title:ex.title, subject:ex.subject, test_type:ex.test_type,
          total_marks:ex.total_marks, total_awarded:null, verdict:null, feedback:'',
          results:(d.questions||[]).map(q=>({
            q_no:q.q_no, max:q.max_marks, marks:null,
            question:q.question_text||'', question_hi:q.question_text_hi||'',
            model_answer:q.model_answer||'', model_answer_hi:q.model_answer_hi||'',
            correct_answer:q.correct_option!=null?q.correct_option:'',
            explanation:q.explanation||'', explanation_hi:q.explanation_hi||'', remark:''
          })) };
      if(!r.results.length || !r.results.some(x=>x.model_answer||x.correct_answer||x.explanation)){
        throw new Error('Solutions are not available yet. They open once the test window is over.');
      }
    }
    window._lastResult=r; r.id=id;
  }
  const sub=spDetectSubject((r.subject||'')+' '+(r.title||''));
  const items=[];
  for(const it of (r.results||[])){
    const o={q_no:it.q_no,max:it.max,marks:it.marks};
    o.q_en=it.question||''; o.q_hi=it.question_hi||'';
    if(med!=='en'&&!o.q_hi&&o.q_en){ const t=await spTranslate(o.q_en,sub); if(t)o.q_hi=t; }
    if(r.test_type==='mcq'){
      o.a_en=it.correct_answer!=null?String(it.correct_answer):''; o.a_hi='';
      o.x_en=it.explanation||''; o.x_hi=it.explanation_hi||'';
      if(med!=='en'){
        if(o.a_en&&/[A-Za-z]/.test(o.a_en)&&o.a_en.length<200){ const t=await spTranslate(o.a_en,sub); if(t)o.a_hi=t; }
        if(o.x_en&&!o.x_hi){ const t=await spTranslate(o.x_en,sub); if(t)o.x_hi=t; }
      }
    } else {
      o.a_en=it.model_answer||it.model||''; o.a_hi=it.model_answer_hi||it.model_hi||'';
      if(med!=='en'&&o.a_en&&!o.a_hi){ const t=await spTranslate(o.a_en,sub); if(t)o.a_hi=t; }
      o.rmk=it.remark||'';
    }
    items.push(o);
  }
  return {r,items};
}
async function _solView(id,med){
  closeModal();
  const el=document.getElementById('s-tests-content'); softSpin(el);
  try{
    const d=await _solData(id,med); const r=d.r, items=d.items;
    const rows=items.map(o=>{
      const qMain=med==='hi'?(o.q_hi||o.q_en):o.q_en;
      const qHi=(med==='both'&&o.q_hi)?`<div class="rs-qtext-hi">${_fmtRich(o.q_hi)}</div>`:'';
      let ans='';
      if(r.test_type==='mcq'){
        const aMain=med==='hi'?(o.a_hi||o.a_en):o.a_en;
        ans=`<div class="rs-ans-row ok"><span class="rs-ans-ic">${ic('check')}</span><span><b>Correct answer:</b> ${_fmtRich(aMain||'—')}</span></div>`;
        const xMain=med==='hi'?(o.x_hi||o.x_en):o.x_en;
        if(xMain)ans+=`<div class="rs-expl"><b>Explanation:</b> ${_fmtRich(xMain)}</div>`;
        if(med==='both'&&o.x_hi)ans+=`<div class="rs-expl">${_fmtRich(o.x_hi)}</div>`;
      } else {
        const aMain=med==='hi'?(o.a_hi||o.a_en):o.a_en;
        if(aMain)ans=`<div class="rs-expl"><b>Model answer:</b> ${_fmtRich(aMain)}</div>`+(med==='both'&&o.a_hi?`<div class="rs-expl">${_fmtRich(o.a_hi)}</div>`:'');
        if(o.rmk)ans+=`<div class="rs-remark">${_fmtRich(o.rmk)}</div>`;
      }
      return `<div class="rs-q"><div class="rs-qhead"><div class="rs-qtext"><b>Q${o.q_no}.</b> ${_fmtRich(qMain)}${qHi}</div><div class="rs-marks">${o.max} marks</div></div>${ans}</div>`;
    }).join('');
    // Jis student ne test attempt nahi kiya uska result hi nahi hota - uske
    // liye "Back to Result" 404 ("No attempt found") de raha tha
    const _hasAtt=(r.total_awarded!=null);
    const _back=_hasAtt?`openExamResult(${id})`:`loadSTests()`;
    el.innerHTML=`<div class="pl-head"><button class="btn btn-ghost btn-sm" onclick="${_back}">${ic('back')} ${_hasAtt?'Back to Result':'Back to Tests'}</button><div class="pl-title">${esc(r.title||'Test')} — Solutions</div></div><div class="rs-list">${rows}</div>`;
    renderMath(el);
  }catch(e){ el.innerHTML=errHtml(e); }
}
async function _solPdf(id,med){
  closeModal();
  toast('Preparing solutions PDF…');
  try{
    const d=await _solData(id,med); const r=d.r, items=d.items;
    const isM=r.test_type==='mcq';
    const ex={title:(r.title||'Test')+' — Solutions',subject:r.subject,chapter:'',test_type:r.test_type,duration_min:null,total_marks:r.total_marks};
    const qLbl=med==='hi'?'प्रश्न':'Question';
    const body=items.map(o=>{
      const qMain=med==='hi'?(o.q_hi||o.q_en):o.q_en;
      let h='';
      if(med==='both'&&o.q_hi)h+='<div class="q-hi">'+escH(o.q_hi)+'</div>';
      if(isM){
        const aMain=med==='hi'?(o.a_hi||o.a_en):o.a_en;
        h+='<div class="sol"><div class="sol-l">'+(med==='hi'?'उत्तर':'Answer')+'</div><div class="sol-t">'+_fmtRich(aMain||'—')+'</div>';
        const xMain=med==='hi'?(o.x_hi||o.x_en):o.x_en;
        if(xMain)h+='<div class="sol-t" style="margin-top:4px">'+_fmtRich(xMain)+'</div>';
        if(med==='both'&&o.x_hi)h+='<div class="q-hi">'+_fmtRich(o.x_hi)+'</div>';
        h+='</div>';
      } else {
        const aMain=med==='hi'?(o.a_hi||o.a_en):o.a_en;
        if(aMain){ h+='<div class="sol"><div class="sol-l">'+(med==='hi'?'हल':'Model Answer')+'</div><div class="sol-t">'+_fmtRich(aMain)+'</div>'+(med==='both'&&o.a_hi?'<div class="q-hi">'+_fmtRich(o.a_hi)+'</div>':'')+'</div>'; }
      }
      return '<div class="q"><div class="q-h"><b>'+qLbl+' '+o.q_no+'</b><span class="q-m">[ '+o.max+' '+(med==='hi'?'अंक':'marks')+' ]</span></div>'+_pdfQHTML(qMain,o.image_b64||null,o.alt_image_b64||null,'q-t')+h+'</div>';
    }).join('');
    const w=window.open('','_blank');
    if(!w){ toast('Popup blocked — please allow popups.',true); return; }
    w.document.write(buildPdfDoc(ex,body,true,isM,med==='hi'?'hi':'en',null));
    w.document.close();
  }catch(e){ toast(e.message,true); }
}


