      const media=`${d.has_voice?`<button class="btn btn-ghost btn-sm" onclick="playDoubtVoice(this,'/api/student/doubt/${d.id}/voice')">${ic('play')} My Voice Note</button>`:''}${d.has_file?doubtAttachHtml('student',d.id,d.attach_mime,d.attach_name,false):''}`;
