async function submitStudioReport(id){
  const st=((document.querySelector('input[name="sr-status"]:checked')||{}).value)||'held';
  const notes=(document.getElementById('sr-notes').value||'').trim();
  const reporter=(document.getElementById('sr-reporter').value||'').trim();
  if(st!=='held'&&!notes){ toast('Please add a short note about the issue / cancellation.',true); return; }
  const payload={entry_id:id,status:st,notes:notes,reporter:reporter,
    start_time:(document.getElementById('sr-start').value||'').trim(),
    end_time:(document.getElementById('sr-end').value||'').trim()};
  try{
    if(window._srFile){ payload.notes_file_b64=await _fileB64(window._srFile); payload.notes_file_name=window._srFile.name; payload.notes_file_mime=window._srFile.type||'application/pdf'; }
    else if(window._srRemove){ payload.remove_notes_file=true; }
    const r=await api('/api/admin/studio-reports','POST',payload);
    window._srReports=window._srReports||{}; window._srReports[id]=r.report;
    window._srFile=null; window._srRemove=false;
    closeModal(); toast('Studio report saved.'); aRenderTT();
  }catch(e){ toast(e.message||'Could not save the report',true); }
}
async function deleteStudioReport(entryId,rid){
  if(!confirm('Remove this studio report?')) return;
  try{ await api('/api/admin/studio-reports/'+rid,'DELETE'); if(window._srReports) delete window._srReports[entryId]; closeModal(); toast('Report removed.'); aRenderTT(); }catch(e){ toast(e.message||'Could not remove the report',true); }
}
// ===== v100: drag & drop PDF upload zones (teacher + admin panels) =====
function _dzInit(inputId){
  const z=document.getElementById('dz-'+inputId);
  if(!z||z._dzWired) return;
  z._dzWired=true;
  ['dragover','dragenter'].forEach(ev=>z.addEventListener(ev,e=>{ e.preventDefault(); e.stopPropagation(); z.classList.add('over'); }));
  z.addEventListener('dragleave',e=>{ if(!z.contains(e.relatedTarget)) z.classList.remove('over'); });
  z.addEventListener('dragend',()=>z.classList.remove('over'));
  z.addEventListener('drop',e=>{
    e.preventDefault(); e.stopPropagation(); z.classList.remove('over');
    const f=e.dataTransfer&&e.dataTransfer.files&&e.dataTransfer.files[0];
    if(!f) return;
    if(!(f.type==='application/pdf'||/\.pdf$/i.test(f.name||''))){ toast('Only PDF files can be uploaded here.',true); return; }
    if(inputId==='lec-pdf') _smartPdfPick(f,'dz-lec-pdf',cf=>_lecSetFile(cf,'pdf'));
    else if(inputId==='sr-file') _smartPdfPick(f,'dz-sr-file',cf=>_srSetFile(cf));
    else if(inputId==='cru-file') _smartPdfPick(f,'dz-cru-file',cf=>_cruSetFile(cf));
  });
}
