async function submitClassReportUpload(id){
  // v101: one modal — academic report (students) + optional studio note (internal)
  const topic=(document.getElementById('cru-topic').value||'').trim();
  const start=(document.getElementById('cru-start').value||'').trim();
  const end=(document.getElementById('cru-end').value||'').trim();
  const srStatus=((document.querySelector('input[name="cru-sr-status"]:checked')||{}).value)||'held';
  const srNotes=(document.getElementById('cru-srnotes').value||'').trim();
  const srReporter=(document.getElementById('cru-srreporter').value||'').trim();
  const hasAcademic=!!(topic||window._crFile);
  const hadStudio=!!((window._srReports||{})[id]);
  const hasStudio=hadStudio||srStatus!=='held'||!!srNotes;
  if(!hasAcademic&&!hasStudio){ toast('Add a topic, notes PDF or a studio note.',true); return; }
  if(hasStudio&&srStatus!=='held'&&!srNotes&&!hadStudio){ toast('Please add a short note about the issue / cancellation.',true); return; }
  const btn=document.getElementById('cru-btn'); if(btn){ btn.disabled=true; btn.textContent='Saving...'; }
  try{
    const msgs=[];
    if(hasAcademic){
      const payload={entry_id:id, topic_covered:topic,
        homework:(document.getElementById('cru-hw').value||'').trim(),
        start_time:start, end_time:end,
        remarks:(document.getElementById('cru-remarks').value||'').trim()};
      if(window._crFile){ payload.pdf_b64=await _fileB64(window._crFile); payload.pdf_filename=window._crFile.name; }
      const r=await _xhrJson('/api/admin/class-report-backfill',payload,pc=>{ if(btn) btn.textContent='Uploading… '+pc+'%'; });
      window._crUploaded=window._crUploaded||{}; window._crUploaded[id]=true;
      msgs.push(r.message||'Class report uploaded');
    }
    if(hasStudio){
      const r2=await api('/api/admin/studio-reports','POST',{entry_id:id, status:srStatus, notes:srNotes, reporter:srReporter, start_time:start, end_time:end});
      if(r2&&r2.report){ window._srReports=window._srReports||{}; window._srReports[id]=r2.report; }
      msgs.push('Studio note saved');
    }
    window._crFile=null;
    closeModal(); toast(msgs.join(' \u00b7 ')||'Saved.'); aRenderTT();
  }catch(e2){ toast(e2.message||'Could not save',true); if(btn){ btn.disabled=false; btn.textContent='Upload Report'; } }
}
