// ===== EXCEL BULK UPLOAD (Students) =====
function openExcelUpload(){
  showModal('App Sales Sheet Upload',
 `<div class="alert alert-info">Upload the Excel/CSV downloaded from your app's (Appx) <strong>Sales</strong> section here. The system automatically extracts the <strong>Name</strong>, <strong>Phone No.</strong> and <strong>Item (Batch)</strong> details and creates students — each student logs in with their phone and sees their batch.</div><div class="form-group"><label>Sales File (.xlsx / .csv)</label><input type="file" class="form-control" id="excel-file" accept=".xlsx,.xls,.csv" onchange="previewExcel()"></div><div id="excel-preview"></div><label style="display:flex;align-items:center;gap:8px;font-size:.82rem;margin:6px 0"><input type="checkbox" id="excel-wa"> Import ke baad naye students ko WhatsApp welcome bhejo</label><div id="excel-status"></div>`,
 `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" id="excel-btn" onclick="processExcel()">Import Students</button>`);
}
function _pickCol(row,names){
  const keys=Object.keys(row);
  for(const n of names){
    const k=keys.find(k=>k.trim().toLowerCase()===n.toLowerCase());
    if(k!==undefined && row[k]!=null && String(row[k]).trim()!=='') return String(row[k]).trim();
  }
  // fuzzy: contains
  for(const n of names){
    const k=keys.find(k=>k.trim().toLowerCase().includes(n.toLowerCase()));
    if(k!==undefined && row[k]!=null && String(row[k]).trim()!=='') return String(row[k]).trim();
  }
  return '';
}
function _parseSalesRows(rows){
  const out=[];
  for(const row of rows){
    const name=_pickCol(row,['Name']);
    const phone=_pickCol(row,['Phone No.','Phone No','Phone Number','Phone','Mobile']);
    const batch=_pickCol(row,['Item','Batch','Course','Plan']);
    const email=_pickCol(row,['Email','E-mail','Email Id','Email Address']);
    const digits=(phone||'').replace(/\D/g,'');
    if(digits.length<10) continue;
    out.push({name, phone:digits.slice(-10), batch, email});
  }
  return out;
}
async function previewExcel(){
  const fi=document.getElementById('excel-file'); const pv=document.getElementById('excel-preview');
  window._excelParsed=null;   // nayi file -> purana count/breakdown reset
  const _st=document.getElementById('excel-status'); if(_st) _st.innerHTML='';
  if(!fi.files.length){ pv.innerHTML=''; return; }
  try{
    const data=await fi.files[0].arrayBuffer();
    const wb=XLSX.read(data,{type:'array'});
    const rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);
    const parsed=_parseSalesRows(rows);
    window._excelParsed=parsed;
    if(parsed.length===0){ pv.innerHTML=`<div class="alert alert-danger">No valid rows found. The sheet must have <strong>Name</strong>, <strong>Phone No.</strong>, <strong>Item</strong> columns are required.</div>`; return; }
    const uniq=new Map(); parsed.forEach(p=>uniq.set(p.phone,p));
    const dup=parsed.length-uniq.size;
    const sample=[...uniq.values()].slice(0,3).map(p=>`<div class="slist-row"><div class="slist-info"><div class="slist-name">${esc(p.name||'—')}</div><div class="slist-meta">${esc(p.phone)} · ${esc(p.batch||'No batch')}</div></div></div>`).join('');
    pv.innerHTML=`<div class="alert alert-success"><strong>${uniq.size}</strong> unique students mile${dup>0?` (${dup} duplicate in the sheet — auto-removed)`:''}.</div>
      <div id="excel-breakdown" style="margin:10px 0"><div class="spinner" style="width:20px;height:20px"></div> Checking who is new / already added…</div>${sample}`;
    // pre-import breakdown (kuch add nahi hota — sirf ginti)
    try{
      const a=await api('/api/admin/students/bulk-analyze','POST',{students:[...uniq.values()]});
      const bd=document.getElementById('excel-breakdown');
      if(bd) bd.innerHTML=`<div class="imp-bd">
        <div class="imp-bd-row"><span>Total in sheet</span><b>${a.total}</b></div>
        <div class="imp-bd-row"><span style="color:#059669">New → MVS App (will add)</span><b style="color:#059669">${a.new_app}</b></div>
        <div class="imp-bd-row"><span style="color:#0891b2">Matched with MVS Portal (will add)</span><b style="color:#0891b2">${a.on_portal}</b></div>
        <div class="imp-bd-row"><span style="color:#b07f1e">Already on Class Manager (duplicate — SKIP)</span><b style="color:#b07f1e">${a.already_cm}</b></div>
        <div class="imp-bd-row imp-bd-tot"><span>Will import (duplicates hate ke)</span><b>${a.will_import}</b></div>
      </div>`;
    }catch(e){ const bd=document.getElementById('excel-breakdown'); if(bd) bd.innerHTML=`<div style="font-size:.75rem;color:var(--text-muted)">Breakdown check skip (${esc(e.message)}). Import phir bhi chalega.</div>`; }
  }catch(e){ pv.innerHTML=`<div class="alert alert-danger">File padhne mein error: ${esc(e.message)}</div>`; }
}
async function processExcel(){
  const fi=document.getElementById('excel-file');
  if(!fi.files.length){ toast('Please select a file.',true); return; }
  const btn=document.getElementById('excel-btn'); btn.disabled=true; btn.textContent='Importing...';
  const status=document.getElementById('excel-status');
  try{
    // hamesha CURRENT file se parse karo — purani file ka stale cache use na ho
    const data=await fi.files[0].arrayBuffer(); const wb=XLSX.read(data,{type:'array'});
    let parsed=_parseSalesRows(XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]));
    if(!parsed.length){ toast('No valid students found.',true); btn.disabled=false; btn.textContent='Import Students'; return; }
    // remove duplicate phone numbers WITHIN the sheet (keep latest occurrence)
    const map=new Map();
    parsed.forEach(p=>map.set(p.phone,p));
    const deduped=[...map.values()];
    const inSheetDup=parsed.length-deduped.length;
    // progress UI (batch-wise)
    document.getElementById('excel-preview').innerHTML='';
    status.innerHTML=`<div class="prog-wrap"><div class="prog-bar"><div class="prog-fill" id="imp-fill"></div></div><div class="prog-text" id="imp-text">0% — taiyaari...</div></div>`;
    const batchSize=100; let created=0, updated=0, skipped=0, done=0, dups=[];
    for(let i=0;i<deduped.length;i+=batchSize){
      const batch=deduped.slice(i,i+batchSize);
      const r=await api('/api/admin/students/bulk-import','POST',{students:batch});
      created+=r.created||0; updated+=r.updated||0; skipped+=r.skipped||0; dups=dups.concat(r.duplicates||[]); done+=batch.length;
      const pct=Math.round(done/deduped.length*100);
      const f=document.getElementById('imp-fill'), t=document.getElementById('imp-text');
      if(f) f.style.width=pct+'%'; if(t) t.textContent=`${pct}% — ${done}/${deduped.length} students`;
    }
    const dupRows=dups.map(d=>`<div class="topper-row"><div style="flex:1;min-width:0"><b>${esc(d.existing_name||d.sheet_name)}</b> <span class="topper-sub">${esc(d.phone)} \u00b7 ${esc(d.existing_user_id||'')} \u00b7 batch: ${esc(d.existing_batch||'\u2014')}</span>${d.sheet_name&&d.sheet_name!==d.existing_name?`<div class="topper-sub">Sheet name: ${esc(d.sheet_name)}</div>`:''}</div><span class="xm-chip" style="background:rgba(201,150,46,.16);color:#b07f1e">MVS PORTAL</span></div>`).join('');
    status.innerHTML=`<div class="alert alert-success"><strong>Import complete!</strong> — total <strong>${deduped.length}</strong> unique students processed<br>
      <strong>${created}</strong> new students added (MVS App)<br>
      <strong>${updated}</strong> already existed as MVS App (batch refreshed)<br>
      ${dups.length?`<strong style="color:#b07f1e">${dups.length}</strong> duplicate(s) already exist from <strong>MVS Portal</strong> — <strong>not added again</strong>, verify below<br>`:''}
      ${inSheetDup>0?`<strong>${inSheetDup}</strong> duplicates inside the sheet (auto-removed)<br>`:''}
      ${skipped>0?`<strong>${skipped}</strong> invalid phone skipped`:''}</div>
      ${dups.length?`<div style="font-size:.75rem;font-weight:800;color:var(--text-muted);margin:12px 0 6px">MVS PORTAL DUPLICATES \u2014 VERIFY THESE (${dups.length})</div><div class="hide-scroll" style="max-height:250px">${dupRows}</div>`:''}`;
    toast(`${created} new, ${updated} refreshed, ${dups.length} portal duplicates skipped`);
    if(created>0 && (document.getElementById('excel-wa')||{}).checked){
      try{
        status.innerHTML+=`<div id="excel-wa-out" style="margin-top:10px"><div class="spinner"></div> Sending WhatsApp welcome...</div>`;
        let afterId=0,waSent=0,waFailed=0,more=true;
        while(more){
          const wr=await api('/api/admin/whatsapp/send-welcome','POST',{all_pending:true,after_id:afterId,limit:50});
          waSent+=wr.sent||0; waFailed+=wr.failed||0; afterId=wr.last_id||afterId; more=!!wr.has_more;
          const o=document.getElementById('excel-wa-out'); if(o) o.innerHTML=`<div class="spinner" style="width:16px;height:16px"></div> WhatsApp: ${waSent} sent...`;
        }
        const o=document.getElementById('excel-wa-out'); if(o) o.innerHTML=`<div class="alert ${waFailed?'alert-warning':'alert-success'}">WhatsApp: <b>${waSent}</b> sent \u00b7 <b>${waFailed}</b> failed</div>`;
      }catch(we){ const o=document.getElementById('excel-wa-out'); if(o) o.innerHTML=`<div class="alert alert-warning">WhatsApp send skipped: ${esc(we.message)}</div>`; }
    }
    btn.textContent='Done'; btn.disabled=false; btn.setAttribute('onclick','closeModal()');
    loadAStudents();
  }catch(e){ status.innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`; toast('Error: '+e.message,true); btn.disabled=false; btn.textContent='Import Students'; }
}
