function initNavAccordion(){
  if(!document.getElementById('navacc-css')){
    var st=document.createElement('style'); st.id='navacc-css';
    st.textContent=[
      // accordion category header — reference jaisa bada, styled, clickable row
      '.sidebar-nav .nav-section{display:flex !important;align-items:center;gap:11px;padding:11px 14px !important;margin:3px 12px !important;font-size:.8rem !important;font-weight:800 !important;color:var(--sidebar-text) !important;opacity:1 !important;text-transform:uppercase;letter-spacing:.5px;border-radius:12px;cursor:pointer;user-select:none;transition:background .15s,color .15s}',
      '.sidebar-nav .nav-section:hover{background:rgba(184,148,31,.10);color:var(--accent) !important}',
      '.sidebar-nav .nav-section.open{color:var(--accent) !important}',
      '.nav-sec-ic{display:inline-flex;width:20px;height:20px;flex:none;opacity:.85}',
      '.nav-sec-ic svg{width:19px;height:19px}',
      '.nav-sec-chev{margin-left:auto;font-size:.7rem;opacity:.6;transition:transform .25s}',
      '.sidebar-nav .nav-section.open .nav-sec-chev{transform:rotate(180deg)}',
      // sub-items thoda andar (hierarchy) + smooth
      '.sidebar-nav .nav-item{margin-left:22px !important;margin-right:12px !important}',
      // icon-collapse (chhoti sidebar) mode: accordion ignore, sab icons dikhein
      '@media(min-width:900px){ .app.nav-collapsed .nav-item{display:flex !important;margin-left:10px !important} .app.nav-collapsed .nav-sec-chev,.app.nav-collapsed .nav-sec-ic{display:none} .app.nav-collapsed .nav-section{justify-content:center;font-size:0 !important} }'
    ].join('\n');
    document.head.appendChild(st);
  }
  document.querySelectorAll('.app .sidebar-nav').forEach(function(nav){
    _accGroupClose(nav, true);
    if(!nav._accObs){
      nav._accObs=new MutationObserver(function(){
        if(nav._accT) return;
        nav._accT=setTimeout(function(){ nav._accT=null; _accGroupClose(nav, false); }, 80);
      });
      nav._accObs.observe(nav, {childList:true, subtree:true});
    }
  });
}
function _accGroupClose(nav, forceAll){
  var secs=[].slice.call(nav.querySelectorAll('.nav-section'));
  secs.forEach(function(sec){
    var items=[], n=sec.nextElementSibling;
    while(n && !n.classList.contains('nav-section')){ if(n.classList.contains('nav-item')) items.push(n); n=n.nextElementSibling; }
    sec._items=items;
    if(!sec.querySelector('.nav-sec-ic')){
      var _lbl=(sec.textContent||'').trim().toLowerCase();
      var _SIC={main:'grid',home:'grid',overview:'grid',content:'folder',materials:'folder',material:'folder',work:'clipboard',progress:'chart',account:'user',academics:'book',production:'play',teachers:'users','leads & support':'help',system:'shield',sales:'chart'};
      var icw=document.createElement('span'); icw.className='nav-sec-ic'; try{ icw.innerHTML=ic(_SIC[_lbl]||'folder'); }catch(e){}
      sec.insertBefore(icw, sec.firstChild);
    }
    if(!sec.querySelector('.nav-sec-chev')){ var ch=document.createElement('span'); ch.className='nav-sec-chev'; ch.textContent='\u25be'; sec.appendChild(ch); }
    if(!sec._accClick){ sec._accClick=true; sec.addEventListener('click',function(){ _setNavSec(sec, !sec._open); }); }
  });
  secs.forEach(function(sec){ if(forceAll || !sec._open) _setNavSec(sec,false); });
}
function _secOf(secs,item){ for(var i=0;i<secs.length;i++){ if((secs[i]._items||[]).indexOf(item)>=0) return secs[i]; } return null; }
function _setNavSec(sec,open){
  if(!sec) return; sec._open=open; sec.classList.toggle('open',open);
  (sec._items||[]).forEach(function(it){ it.style.display=open?'':'none'; });
  // chevron ki rotation CSS (.nav-section.open .nav-sec-chev) se hoti hai
}
function errHtml(e){ return `<div class="alert alert-danger"> ${esc(e.message)}<br><small>If this keeps happening, the backend may be asleep — refresh after 30–60 seconds.</small></div>`; }

// ============================================================
//  ULTRA RESPONSIVE HELPERS (mobile drawer + table auto-scroll)
// ============================================================
(function(){
  // overlay behind the drawer
  var ov=document.createElement('div'); ov.className='side-overlay';
  document.body.appendChild(ov);
  function closeSidebar(){ document.querySelectorAll('.sidebar.open').forEach(function(sb){sb.classList.remove('open');}); ov.classList.remove('show'); }
  window.closeSidebar=closeSidebar;
  ov.addEventListener('click',closeSidebar);
  function openSidebar(appEl){ var sb=appEl.querySelector('.sidebar'); if(sb){ sb.classList.add('open'); ov.classList.add('show'); } }
  // hamburger button into every topbar (teacher, admin, student)
  document.querySelectorAll('.app').forEach(function(appEl){
    var tb=appEl.querySelector('.topbar'); if(!tb) return;
    var h=document.createElement('button'); h.className='hamburger'; h.type='button'; h.setAttribute('aria-label','Menu');
    h.innerHTML='<span></span><span></span><span></span>';
    h.addEventListener('click',function(e){ e.stopPropagation(); openSidebar(appEl); });
    tb.insertBefore(h, tb.firstChild);
  });
  // tap on any nav item closes the drawer
  document.querySelectorAll('.sidebar .nav-item').forEach(function(n){ n.addEventListener('click',function(){ closeSidebar(); }); });
  // swipe-left on open drawer closes it
  var tx=null;
  document.addEventListener('touchstart',function(e){ tx=e.touches[0].clientX; },{passive:true});
  document.addEventListener('touchend',function(e){
    if(tx===null) return; var dx=e.changedTouches[0].clientX-tx; tx=null;
    if(dx<-60 && document.querySelector('.sidebar.open')) closeSidebar();
  },{passive:true});
  // wrap every table (present + future renders) in a horizontal-scroll shell
  function wrapTables(){
    document.querySelectorAll('table').forEach(function(t){
      if(t.closest('.tbl-scroll')) return;
      var w=document.createElement('div'); w.className='tbl-scroll';
      t.parentNode.insertBefore(w,t); w.appendChild(t);
    });
    markScrollables();
  }
  function markScrollables(){
    document.querySelectorAll('.tbl-scroll').forEach(function(w){
      var can=w.scrollWidth>w.clientWidth+6;
      w.classList.toggle('can-scroll',can);
      if(can&&!w.dataset.hintBound){
        w.dataset.hintBound='1';
        w.addEventListener('scroll',function(){ w.classList.add('scrolled'); },{passive:true,once:true});
      }
    });
  }
  window.addEventListener('resize',function(){ requestAnimationFrame(markScrollables); });
  wrapTables();
  var pending=false;
  new MutationObserver(function(muts){
    for(var i=0;i<muts.length;i++){ if(muts[i].addedNodes.length){ 
      if(!pending){ pending=true; requestAnimationFrame(function(){ pending=false; wrapTables(); }); }
      break; } }
  }).observe(document.body,{childList:true,subtree:true});
})();


/* ==================== MVS PORTAL ONE-TAP SSO ====================
   Student portal ka Class Manager card #sso=<token> (ya fallback #student=<phone>) ke saath kholta hai.
   Yahan hum wahi exact flow programmatically chalate hain: lookup-by-phone -> login -> openStudent().
   Token = base64url(JSON{m:mobile, x:expiry}) + "." + HMAC-SHA256 signature (CRM_SSO_SECRET / CRON_SECRET).
   Backend verification chaho to Railway par isi secret se signature check endpoint bana sakte ho.  */
function _ssoOverlay(show){
  var o=document.getElementById('sso-ovl');
  if(show){
    if(!o){ o=document.createElement('div'); o.id='sso-ovl';
      o.style.cssText='position:fixed;inset:0;z-index:99999;background:rgba(7,16,34,.92);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;color:#fff;font-family:inherit';
      o.innerHTML='<div style="width:52px;height:52px;border-radius:50%;border:4px solid rgba(255,255,255,.15);border-top-color:#b8941f;animation:ssoSpin .8s linear infinite"></div>'+
        '<div style="font-size:1.05rem;font-weight:700">Logging you in\u2026</div>'+
        '<div style="font-size:.8rem;opacity:.65">MVS Portal \u2192 Class Manager</div>'+
        '<style>@keyframes ssoSpin{to{transform:rotate(360deg)}}</style>';
      document.body.appendChild(o);
    }
    o.style.display='flex';
  } else if(o){ o.style.display='none'; }
}
async function mvsSsoFromHash(){
  var h=location.hash||'';
  var phone='';
  var mT=h.match(/^#sso=([A-Za-z0-9_-]+)\.([A-Za-z0-9_-]+)$/);
  if(mT){
    try{
      var pj=JSON.parse(atob(mT[1].replace(/-/g,'+').replace(/_/g,'/')));
      if(pj && pj.m && (!pj.x || Date.now() < Number(pj.x))) phone=String(pj.m);
      else { toast('Login link expired — Class Manager ko MVS portal se dobara kholein.',true); }
    }catch(e){}
  } else {
    var mP=h.match(/^#student(?:=(\d{10}))?$/i);
    if(!mP) return;
    if(mP[1]) phone=mP[1];
  }
  try{ history.replaceState(null,'',location.pathname+location.search); }catch(e){}
  if(!phone){ goLogin('student'); return; }          // sirf #student -> seedha phone-login screen (landing skip)
  CURRENT_PORTAL='student';
  _ssoOverlay(true);
  window._ssoToken=(mT?mT[0].slice(5):'');   // "#sso=" ke baad ka pura token
  try{
    var d=await api('/api/auth/sso-lookup','POST',{token:window._ssoToken,phone:phone});
    if(d.found){
      var data=await api('/api/auth/login','POST',{user_id:d.user_id,password:d.password});
      _apiBust(); TOKEN=data.access_token; ROLE=data.role; NAME=data.name;
      document.getElementById('landing').style.display='none';
      document.getElementById('login-screen').classList.remove('active');
      _ssoOverlay(false);
      openStudent();
      try{ toast('Welcome, '+(data.name||d.name||'Student')+'!'); }catch(e){}
      return;
    }
    _ssoOverlay(false);
    if(d.portal && d.locked){
      goLogin('student');
      toast('Your class access is not unlocked yet on the MVS Portal. Please contact the admin.',true);
      return;
    }
    if(d.portal && d.profile){
      window._ssoProfile=d.profile;
      ssoBatchPopup(d.profile,d.batches||[]);
      return;
    }
    goLogin('student');
    var sp=document.getElementById('sp-phone'); if(sp) sp.value=phone;
    var msg='No student found for this phone. Please contact the admin.';
    if(d.reason==='not_configured'||d.reason==='endpoint_missing'||d.reason==='unreachable'||d.reason==='bad_key'||d.reason==='http_error'){
      msg='MVS Portal connection pending — auto-login is not active yet. Please inform the admin.';
      console.warn('[SSO] '+d.reason+': '+(d.detail||''));
    } else if(d.reason==='not_on_portal'){
      msg='This phone is not registered on the MVS Portal. Please contact the admin.';
    }
    toast(msg,true);
  }catch(e){
    _ssoOverlay(false); goLogin('student');
    var sp2=document.getElementById('sp-phone'); if(sp2) sp2.value=phone;
    toast(e.message,true);
  }
}
// MVS Portal se aaya naya student — sirf batch chunta hai, baaki sab auto
function ssoBatchPopup(p,batches){
  document.getElementById('landing').style.display='none';
  const subChips=(p.subjects||[]).map(x=>`<span class="pill">${esc(x)}</span>`).join('');
  const bBtns=(batches||[]).map(b=>{
    const nm=(typeof b==='string')?b:b.name, mode=(typeof b==='string')?'live':(b.mode||'live');
    const badge=mode==='rec'
      ? `<span class="bt-badge bt-rec">${ic('play')} REC.</span>`
      : `<span class="bt-badge bt-live"><i></i> LIVE</span>`;
    return `<button class="batch-card" onclick="ssoRegister('${esc(nm).replace(/'/g,"\\'")}',this)"><span class="bt-name">${esc(nm)}</span>${badge}</button>`;
  }).join('');
  showModal('Welcome, '+esc(p.name||'Student')+'!',
    `<div class="pill-row">${p.class_level?`<span class="pill pill-hl">Class ${esc(p.class_level)}</span>`:''}${p.medium?`<span class="pill">${esc(p.medium)} Medium</span>`:''}${p.session?`<span class="pill">${esc(p.session)}</span>`:''}</div>
     ${subChips?`<div class="sso-lbl">Your Subjects</div><div class="pill-row">${subChips}</div>`:''}
     <div class="sso-lbl">Select Your Batch</div>
     <div class="batch-grid">${bBtns||'<p style="color:var(--text-muted);font-size:.85rem">No batch available for your class/session. Please contact the admin.</p>'}</div>
     <div id="sso-reg-status"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal();goLogin('student')">Cancel</button>`);
}
async function ssoRegister(batch,btn){
  document.querySelectorAll('#modal-body .batch-card').forEach(b=>b.disabled=true);
  if(btn){ btn.classList.add('picked'); btn.innerHTML='<span class="bt-name">Setting up your account\u2026</span>'; }
  try{
    const r=await api('/api/auth/sso-register','POST',{token:window._ssoToken||'',phone:(window._ssoProfile||{}).phone||'',batch_name:batch});
    _apiBust(); TOKEN=r.access_token; ROLE='student'; NAME=r.name;
    closeModal();
    document.getElementById('login-screen').classList.remove('active');
    openStudent();
    toast('Welcome, '+(r.name||'Student')+'! Your profile is ready.');
  }catch(e){
    const st=document.getElementById('sso-reg-status');
    if(st) st.innerHTML=`<div class="alert alert-danger" style="margin-top:10px">${esc(e.message)}</div>`;
    document.querySelectorAll('#modal-body button').forEach(b=>b.disabled=false);
    if(btn){ btn.classList.remove('picked'); btn.innerHTML=`<span class="bt-name">${esc(batch)}</span>`; }
  }
}

