window.addEventListener('drop',e=>{ e.preventDefault(); });

// ---- PDF re-upload replace warning (admin + teacher) ----
/* UPDATE 22: NIOS book chapter rules */
// grammar / writing-skills = NIOS book chapter nahi — progress counting me mat lao
function _isNonBookChapter(name){
  return /grammar|tense|reported speech|narration|direct and indirect|indirect speech|direct speech|conjunction|preposition|clause|modal|subject[ -]?verb|writing skill|notice writing|letter writing|article writing|essay|punctuation|active voice|passive voice|comprehension|unseen/i.test(String(name||''));
}
// merged chapter "Chapter 15 & 16 - X" / "Chapter 25 to 28 - X" -> individual chapter names
function _expandMergedChapter(name){
  const s=String(name||'').trim();
  const m=s.match(/chapter\s*[-–:]?\s*((?:\d+\s*(?:,|&|and|to|\-)?\s*)+\d+)\s*[-–:]/i)||s.match(/chapter\s*[-–:]?\s*((?:\d+\s*(?:,|&|and|to|\-)?\s*)+\d+)$/i);
  if(!m) return null;
  const seg=m[1];
  let nums=[];
  const rg=seg.match(/(\d+)\s*(?:to|\-)\s*(\d+)/i);
  if(rg){ const a=+rg[1],b=+rg[2]; if(b>a&&b-a<=15) for(let i=a;i<=b;i++) nums.push(i); }
  if(!nums.length) nums=(seg.match(/\d+/g)||[]).map(Number);
  nums=[...new Set(nums)].filter(n=>n>0&&n<100);
  if(nums.length<2) return null;
  return nums.map(n=>'Chapter '+n);
}
// subject dropdown chips: sirf book chapters count karo (merged -> individual)
function _countBookChapters(list){
  let n=0;
  (list||[]).forEach(it=>{ if(it.kind!=='chapter'||_isNonBookChapter(it.chapter)) return; n+=(_expandMergedChapter(it.chapter)||['']).length; });
  return n;
}

window._DEMO_TT_B64='';
function downloadDemoTT(){
  try{
    const bin=atob(window._DEMO_TT_B64); const u8=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++) u8[i]=bin.charCodeAt(i);
    const url=URL.createObjectURL(new Blob([u8],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'}));
    const a=document.createElement('a'); a.href=url; a.download='MVS_Timetable_Demo_All_Subjects.docx'; a.click();
    setTimeout(()=>URL.revokeObjectURL(url),5000);
  }catch(e){ toast('Download failed',true); }
}

/* UPDATE 22: PDF parse preview — split/delete/edit karke final upload */
window._pdfPreview=null;
function openPdfPreview(rows,opts){
  window._pdfPreview={rows:(rows||[]).map(r=>({subject:r.subject||'',chapter:r.chapter||'',part:r.part||'',date:r.date||'',day:r.day||'',time:r.time||'',type:r.type||'chapter',_grammar:(r.type||'chapter')!=='event'&&_isNonBookChapter(r.chapter),match_action:r.match_action||'',match_no:r.match_no||'',match_title:r.match_title||'',match_kind:r.match_kind||'',match_note:r.match_note||'',match_score:r.match_score,match_candidates:r.match_candidates||[]})),
    isAdmin:!!(opts&&opts.isAdmin), class_name:(opts&&opts.class_name)||'Class 12',
    replace:(opts&&opts.replace)?'true':'false',
    from_date:(opts&&opts.from_date)||'', skipped_before:+(opts&&opts.skipped_before)||0};
  showModal('Check Chapters \u2014 Preview',
   '<div id="pvw-head"></div><div class="pvw-list" id="pvw-list"></div>',
   '<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" id="pvw-btn" onclick="commitPdfPreview()">Final Upload</button>');
  renderPdfPreview();
}
function renderPdfPreview(){
  const P=window._pdfPreview; if(!P) return;
  const head=document.getElementById('pvw-head'), list=document.getElementById('pvw-list');
  if(!head||!list) return;
  const subs=[...new Set(P.rows.map(r=>r.subject).filter(Boolean))];
  const chaps=new Set(P.rows.filter(r=>r.type!=='event'&&!_isNonBookChapter(r.chapter)).map(r=>r.subject+'|'+(r.chapter||'').toLowerCase()));
  const gcount=new Set(P.rows.filter(r=>r.type!=='event'&&_isNonBookChapter(r.chapter)).map(r=>r.subject+'|'+(r.chapter||'').toLowerCase()));
  head.innerHTML=`<div class="alert alert-info" style="margin-bottom:8px"><strong>${P.rows.length} entries \u00b7 ${chaps.size} chapters</strong>${gcount.size?` <span style="color:#b07f1e">+ ${gcount.size} grammar</span>`:''} \u00b7 ${esc(P.class_name)}${subs.length?` \u00b7 ${esc(subs.join(', '))}`:''}<br><span style="font-size:.8rem">Nothing is saved yet. Use the <b>Chapter/Grammar</b> toggle to mark entries (grammar is not counted), <b>Split</b> to separate merged entries, and delete to remove extras \u2014 then tap <b>Final Upload</b>.</span></div>`
   + ((P.from_date&&P.replace==='true')?`<div class="alert alert-warning" style="margin-bottom:8px"><strong>Partial replace active:</strong> entries from <b>${esc(fmtNice(P.from_date))}</b> onwards will be replaced \u2014 everything before that date stays exactly as it is.${P.skipped_before?` ${P.skipped_before} PDF row${P.skipped_before===1?'':'s'} before that date ${P.skipped_before===1?'was':'were'} left out.`:''}</div>`:'')
   + _sylSummary(P.rows);
  const b=document.getElementById('pvw-btn');
  if(!P.rows.length){ list.innerHTML='<div class="ws-empty"><p>All rows have been deleted.</p></div>'; if(b) b.disabled=true; return; }
  if(b) b.disabled=false;
  let lastSub=null, html='';
  P.rows.forEach((r,i)=>{
    if(r.subject!==lastSub){ lastSub=r.subject; html+=`<div class="pvw-subj">${esc(r.subject||'(No subject)')}</div>`; }
    const merged=r.type!=='event'&&_expandMergedChapter(r.chapter);
    html+=`<div class="pvw-row${r.type==='event'?' ev':''}">
      <div class="pvw-date">${r.date?esc(fmtNice(r.date)):'\u2014'}${r.day?`<br>${esc(r.day)}`:''}${r.time?`<br>${esc(r.time)}`:''}</div>
      <div class="pvw-main">
        <input class="form-control pvw-ch" value="${esc(r.chapter||'')}" placeholder="Chapter name" onchange="pvwEdit(${i},'chapter',this.value)">
        <input class="form-control pvw-pt" value="${esc(r.part||'')}" placeholder="Part" onchange="pvwEdit(${i},'part',this.value)">
        ${_sylBadge(r)}
      </div>
      ${merged?'<span class="pvw-merged">Merged</span>':''}
      ${r.type!=='event'?`<div class="pvw-tog"><button class="${!r._grammar?'on':''}" onclick="pvwType(${i},'chapter')">Chapter</button><button class="${r._grammar?'on g':''}" onclick="pvwType(${i},'grammar')">Grammar</button></div>`:''}
      ${r.type!=='event'?`<button class="btn btn-ghost btn-sm" onclick="pvwSplit(${i})" title="Split into separate chapters">Split</button>`:''}
      <button class="btn btn-danger btn-sm" onclick="pvwDel(${i})" title="Delete this row">${ic('trash')}</button>
    </div>`;
  });
  list.innerHTML=html;
}
function pvwEdit(i,f,v){ const P=window._pdfPreview; if(P&&P.rows[i]) P.rows[i][f]=v; }
function pvwType(i,kind){
  const P=window._pdfPreview; if(!P||!P.rows[i]) return;
  const r=P.rows[i];
  if(kind==='grammar'){
    r._grammar=true;
    r.chapter='Grammar: '+(r.chapter||'').replace(/^grammar\s*[:\-]\s*/i,'');
  } else {
    r._grammar=false;
    r.chapter=(r.chapter||'').replace(/^grammar\s*[:\-]\s*/i,'');
  }
  renderPdfPreview();
}
function pvwDel(i){ const P=window._pdfPreview; if(!P) return; P.rows.splice(i,1); renderPdfPreview(); }
function pvwSplit(i){
  const P=window._pdfPreview; if(!P||!P.rows[i]) return;
  const r=P.rows[i];
  const names=_expandMergedChapter(r.chapter)||[(r.chapter||'Chapter')+' 1',(r.chapter||'Chapter')+' 2'];
  P.rows.splice(i,1,...names.map(nm=>Object.assign({},r,{chapter:nm})));
  renderPdfPreview();
  toast('Split into '+names.length+' chapters \u2014 you can edit the names now.');
}
async function commitPdfPreview(){
  const P=window._pdfPreview; if(!P) return;
  if(!P.rows.length){ toast('No rows left.',true); return; }
  const btn=document.getElementById('pvw-btn'); btn.disabled=true; btn.textContent='Uploading...';
  try{
    const r=await api((P.isAdmin?'/api/admin/':'/api/teacher/')+'timetable-pdf-commit','POST',{rows:P.rows,class_name:P.class_name,replace:P.replace,from_date:(P.from_date||'')});
    const isA=P.isAdmin; window._pdfPreview=null; closeModal();
    toast(r.added+' entries uploaded! ');
    if(isA) loadATimetable(); else loadTTimetable();
  }catch(e){ toast('Error: '+e.message,true); btn.disabled=false; btn.textContent='Final Upload'; }
}

function pdfReplaceWarn(subj, entries, warnId, cbId, cls){
  const w=document.getElementById(warnId); if(!w) return;
  subj=(subj||'').trim();
  if(!subj){ w.innerHTML=''; return; }
  const cl=String(cls||'').replace(/\D/g,'');
  // duplicate sirf SAME CLASS me — same-name subject ki dusri class alag timetable hai
  const n=(entries||[]).filter(e=>(e.subject||'').trim().toLowerCase()===subj.toLowerCase()
      &&(!cl||String(e.class_name||'').replace(/\D/g,'')===cl)).length;
  if(n>0){
    w.innerHTML=`<div class="alert alert-warning"><strong>${esc(subj)}</strong>${cls?` (${esc(cls)})`:''} already has <strong>${n}</strong> timetable entr${n===1?'y':'ies'} uploaded. Tick "Replace existing entries" below to replace the old timetable, otherwise the new entries will be added on top of it.</div>`;
    const cb=document.getElementById(cbId); if(cb&&!cb.checked) cb.checked=true;
  } else w.innerHTML='';
}

// ---- Punch card (teacher dashboard + attendance page) ----
let _pwInt=null;
function _fmtClock(d){
  let h=d.getHours(); const am=h>=12?'PM':'AM'; h=h%12||12;
  const p=n=>String(n).padStart(2,'0');
  return p(h)+':'+p(d.getMinutes())+':'+p(d.getSeconds())+' '+am;
}
function _pwTick(){
  // v102: dashboard + attendance dono punch cards DOM me saath rehte hain (duplicate
  // id="pw-clock") — getElementById sirf pehla update karta tha, doosra card ka clock
  // khaali reh jaata tha. Ab class se SAB clocks tick hote hain.
  const els=document.querySelectorAll('.pw-clock');
  if(!els.length){ clearInterval(_pwInt); _pwInt=null; return; }
  try{ const t=_fmtClock(new Date()); els.forEach(el=>{ el.textContent=t; }); }catch(e){}
}
async function _fillPunchRank(wrapId){
  const box=document.getElementById('pw-rank-'+wrapId); if(!box) return;
  try{
    const d=await api('/api/teacher/my-rank');
    const me=d.me; if(!me){ box.innerHTML=''; return; }
    box.innerHTML=`<button class="pw-rankbtn" onclick="tPage('performance')" title="Open your performance page">
      <span class="pw-rank-l">${ic('chart')} Your Rank</span>
      <span class="pw-rank-r"><b>#${me.rank}</b> of ${(d.results||[]).length} \u00b7 ${me.score}/100 \u203a</span></button>`;
  }catch(e){ box.innerHTML=''; }
}
async function renderPunchCard(wrapId){
  const wrap=document.getElementById(wrapId); if(!wrap) return;
  let d;
  try{ d=await api('/api/teacher/attendance/today'); }
  catch(e){ wrap.innerHTML=''; return; }
  if(d.policy&&d.policy.disabled){
    wrap.innerHTML=`<div class="myt-card" style="margin-bottom:18px">
      <div style="font-size:.66rem;font-weight:800;letter-spacing:.07em;color:var(--text-muted);text-transform:uppercase;margin-bottom:6px">My Daily Target — set by admin</div>
      <div class="myt-row"><span class="myt-chip gold">TARGET ${d.required_hours||8}h / DAY</span>${d.policy.label?`<span class="myt-chip">${esc(d.policy.label)}</span>`:''}</div>
      <div class="myt-note" style="margin-top:10px">Punch in/out is turned off for you on this portal — your attendance is managed on the other app.</div>
      <div id="myt-est-${wrapId}" style="margin-top:10px"></div>
    </div>`;
    // v105: card ke neeche is mahine ka estimated % + payout page ka rasta
    try{
      const ed=await api('/api/teacher/earnings?month='+curMonth());
      const est=document.getElementById('myt-est-'+wrapId);
      if(est&&ed&&ed.target_only){
        const sp=(ed.earnings&&ed.earnings.salary_pct!=null)?ed.earnings.salary_pct:0;
        const spc=sp>=85?'#15803d':sp>=65?'#b45309':'#b91c1c';
        est.innerHTML=`<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;border-top:1px dashed var(--border);padding-top:10px">
          <div style="font-size:.8rem;font-weight:700">This month's estimated earnings: <b style="color:${spc}">est. ${sp}%</b> of salary</div>
          <button class="btn btn-primary btn-sm" onclick="tPage('payout')">View Estimated Earnings</button>
        </div>`;
      }
    }catch(e){}
    return;
  }
  const dateLbl=new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'short'});
  let statusHtml='', btnHtml='';
  if(!d.punch_in){
    statusHtml=`You have not punched in yet today`;
    btnHtml=`<button class="pw-punchbtn in" id="pw-btn" onclick="doPunch('in')">${ic('finger')} Punch In</button>`;
  } else if(!d.punch_out){
    statusHtml=`<span class="pw-live"><span class="d"></span>ON DUTY SINCE ${esc(d.punch_in)}</span>`;
    btnHtml=`<button class="pw-punchbtn out" id="pw-btn" onclick="doPunch('out')">${ic('finger')} Punch Out</button>`;
  } else {
    statusHtml=`<span class="pw-live" style="background:rgba(16,185,129,.12);color:#059669"><span class="d" style="background:#059669;animation:none"></span>DAY COMPLETE - ${d.hours!=null?d.hours+' HOURS':'DONE'}</span>`;
    btnHtml=`<button class="pw-punchbtn out" id="pw-btn" disabled>${ic('check')} Punched Out at ${esc(d.punch_out)}</button>`;
  }
  wrap.innerHTML=`<div class="pw-shell" style="margin-bottom:18px">
    <div class="pw-banner">${ic('finger')}<div class="pw-bigdate">${esc(dateLbl)}</div><div class="pw-clock" id="pw-clock"></div></div>
    <div class="pw-body">
      <div class="pw-status">${statusHtml}</div>
      ${btnHtml}
      <div class="pw-mini">
        <div class="m"><div class="l">Punch In</div><div class="v">${esc(d.punch_in||'--:--')}</div></div>
        <div class="m"><div class="l">Punch Out</div><div class="v">${esc(d.punch_out||'--:--')}</div></div>
        <div class="m"><div class="l">Counted</div><div class="v">${d.net_hours!=null?d.net_hours+' h':(d.hours!=null?d.hours+' h':'--')}</div></div>
        <div class="m"><div class="l">Target</div><div class="v">${d.required_hours?d.required_hours+' h':'--'}</div></div>
      </div>
      ${d.punch_in&&d.required_hours?`<div class="wt-prog" style="margin:10px 0 2px"><div class="${(d.net_hours||0)>=d.required_hours?'done':''}" style="width:${Math.min(100,Math.round((d.net_hours||0)/d.required_hours*100))}%"></div></div>
      <div style="display:flex;justify-content:space-between;font-size:.68rem;font-weight:700;color:rgba(255,255,255,.75)"><span>${(d.net_hours||0)} of ${d.required_hours}h counted${d.policy&&d.policy.break_minutes?` (break ${d.policy.break_minutes}m skipped)`:''}</span>${d.extra_hours>0?`<span style="color:#93c5fd">+${d.extra_hours}h extra — no extra payout</span>`:`<span>${Math.min(100,Math.round((d.net_hours||0)/d.required_hours*100))}%</span>`}</div>`:''}
      <div id="geo-note"></div>
      <div id="pw-rank-${wrapId}" class="pw-rankwrap"></div>
      <div class="pw-cap">Time is captured automatically in IST. The admin sees your attendance in real time.</div>
    </div></div>`;
  _pwTick();
  _fillPunchRank(wrapId);
  if(!_pwInt) _pwInt=setInterval(_pwTick,1000);
  if(!window._geoState.checked) _loadGeofence(); else _geoNote();
}
// geofence status cache
window._geoState=window._geoState||{checked:false,active:false,offices:[]};
async function _loadGeofence(){
  try{ const g=await api('/api/teacher/geofence'); window._geoState={checked:true,active:!!g.active,offices:g.offices||[],radius:g.radius||null}; }
  catch(e){ window._geoState={checked:true,active:false,offices:[]}; }
  _geoNote();
}
function _geoNote(txt,cls){
  const ns=document.querySelectorAll('#geo-note'); if(!ns.length) return;   // dashboard + attendance dono cards update (DOM me 2 ho sakte hain)
  let h='';
  if(txt){
    if(cls==='success'||cls==='error') window._geoFlash={txt,cls,at:Date.now()};   // re-render ke baad bhi dikhe (10 min tak)
    h=`<div class="alert alert-${cls==='error'?'danger':(cls||'info')}" style="margin-top:10px;font-size:.8rem">${txt}</div>`;
  } else {
    const f=window._geoFlash;
    if(f && Date.now()-f.at<10*60*1000) h=`<div class="alert alert-${f.cls==='error'?'danger':(f.cls||'info')}" style="margin-top:10px;font-size:.8rem">${f.txt}</div>`;
    else{
      window._geoFlash=null;
      if(window._geoState.active){ const rad=window._geoState.radius;
        const br=(window._geoState.offices||[]).map(o=>`${esc(o.name)}: ${o.radius||rad||0}m`).join(' · ');
        h=`<div style="font-size:.72rem;color:var(--text-muted);margin-top:8px;text-align:center">Location check ON — punch-in is allowed only from within the office radius${br?` (<b>${br}</b>)`:(rad?` (<b>${rad}m</b>)`:'')}.</div>`; }
    }
  }
  ns.forEach(n=>n.innerHTML=h);
}
function _stripTags(h){
  const d=document.createElement('div'); d.innerHTML=String(h||'');
  return d.textContent||'';
}
function _geoErrMsg(code){
  const ua=navigator.userAgent||'';
  const ios=/iPad|iPhone|iPod/.test(ua), and=/Android/i.test(ua);
  if(code===1){
    if(ios) return 'Location is BLOCKED. On iPhone: tap the <b>aA icon</b> in the address bar → Website Settings → Location → <b>Allow</b> (Location Services must be ON: Settings → Privacy &amp; Security → Location Services). Then tap "Try Again".';
    if(and) return 'Location is BLOCKED. Tap the <b>lock icon</b> in the address bar → Permissions → Location → <b>Allow</b>, then tap "Try Again".';
    return 'Location is BLOCKED. Tap the <b>lock icon</b> in the address bar → Site settings → Location → <b>Allow</b>, then tap "Try Again".';
  }
  if(code===2) return 'Could not get your location — turn on <b>GPS/Location</b> on your phone and try again.';
  if(code===3) return 'Location timed out — the GPS signal is weak. Move to an open area and tap "Try Again".';
  return 'Could not fetch your location. Please turn on GPS and try again.';
}
function _getLocation(onProg){
  return new Promise((res,rej)=>{
    if(!navigator.geolocation){ rej(new Error('This device/browser does not support location — please try Chrome or Safari on your mobile.')); return; }
    let best=null, settled=false, wid=null;
    const cleanup=()=>{ if(wid!=null){ try{navigator.geolocation.clearWatch(wid);}catch(e){} wid=null; } };
    const ok=()=>{ if(settled) return; settled=true; cleanup(); res(best); };
    const fail=m=>{ if(settled) return; settled=true; cleanup(); rej(new Error(m)); };
    // watchPosition: kai readings aati hain — pehli kabhi-kabhi bahut coarse hoti hai (PC/IP ±2000m),
    // GPS/WiFi lock hote hi behtar hoti hai. 14s tak ka BEST reading lete hain.
    wid=navigator.geolocation.watchPosition(
      pos=>{ const c={lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy||9999};
             if(!best||c.accuracy<best.accuracy){ best=c; if(onProg) onProg(best); }
             if(best.accuracy<=25) ok(); },
      err=>{ if(err&&err.code===1) fail(_geoErrMsg(1)); },
      {enableHighAccuracy:true,maximumAge:0,timeout:20000});
    setTimeout(()=>{ if(best) ok(); else fail(_geoErrMsg(3)); }, window._GEO_MAX_WAIT||14000);
    setTimeout(()=>{ if(best&&best.accuracy>=1500) ok(); }, window._GEO_FAST_WAIT||6000);   // IP-based reading (PC) — aur improve nahi hogi
  });
}
async function doPunch(kind,confirm){
  const btn=document.getElementById('pw-btn');
  window._geoFlash=null;
  if(kind==='out'&&!confirm){ window._punchOutArmed=false; }
  if(!window._geoState.checked) await _loadGeofence();
  let payload={}, geoErr=null, wifiWhy=null;
  if(window._geoState.active){
    if(btn){ btn.disabled=true; btn.textContent='Location check...'; }
    // permission state pehle dekho — denied ho to GPS skip, WiFi fallback try hoga
    let denied=false;
    try{
      if(navigator.permissions&&navigator.permissions.query){
        const st=await navigator.permissions.query({name:'geolocation'});
        if(st&&st.state==='denied'){
          denied=true; geoErr=_geoErrMsg(1);
          if(!window._geoPermWatch){ window._geoPermWatch=true;   // settings me allow karte hi auto-punch
            st.onchange=()=>{ if(st.state==='granted'){ window._geoPermWatch=false; _geoNote('Permission granted — continuing your punch...','info'); doPunch(kind); } }; }
        }
        else if(st.state==='prompt') _geoNote('The browser will ask for <b>location permission</b> — tap <b>Allow</b> and your punch happens automatically.','info');
        else _geoNote('Checking your location...','info');
      } else _geoNote('Checking your location...','info');
    }catch(e){ _geoNote('Checking your location...','info'); }
    if(!denied){
      try{ payload=await _getLocation(b=>_geoNote(`Getting your location… (±${Math.round(b.accuracy)}m — waiting for the best reading)`,'info')); }
      catch(e){ geoErr=e.message; payload={}; }   /* GPS fail — neeche WiFi fallback try hoga */
    }
    if(geoErr || (payload.accuracy!=null && payload.accuracy>80)){
      // GPS fail/PC — office WiFi (trusted IP) se auto-verify try karo, coords ke bina
      wifiWhy = geoErr || `Your device's location is too weak (±${Math.round(payload.accuracy)}m) — please try office WiFi or a mobile phone.`;
      payload={wifi_fallback:true};
      _geoNote('GPS is not accurate enough — verifying via <b>office WiFi</b>...','info');
    }
  }
  if(btn){ btn.disabled=true; btn.textContent=kind==='in'?'Punching In...':'Punching Out...'; }
  if(kind==='out'&&confirm) payload.confirm=true;
  try{
    const r=await api('/api/teacher/attendance/punch-'+kind,'POST',payload);
    if(r.need_confirm){
      // <1h punch-out: teacher ko warn karo + dobara press pe confirm
      window._punchOutArmed=true;
      toast(r.message,true);
      _geoNote('<b>Short day warning</b> — '+esc(r.message),'error');
      document.querySelectorAll('.pw-punchbtn.out').forEach(b=>{
        b.disabled=false; b.classList.add('confirm-arm');
        b.innerHTML='Confirm Punch Out — mark Present (Short)';
        b.onclick=()=>doPunch('out',true);
      });
      return;   // re-render nahi — armed button apni jagah rahe
    }
    window._punchOutArmed=false;
    toast(r.message);
    if(r.wifi) _geoNote(`Verified via <b>Office WiFi</b> — you are at <b>${esc(r.office||'office')}</b>. Punch recorded.`,'success');
    else if(r.distance!=null) _geoNote(`Location verified — you are at <b>${esc(r.office||'office')}</b> (<b>${r.distance}m</b> from office).`,'success');
  }catch(e){
    const m=String(e.message||'');
    if(m.startsWith('outside|')){
      const parts=m.split('|');
      const [,branch,dist,rad]=parts.length===4?parts:[null,'office',parts[1],parts[2]];
      _geoNote(`<b>Outside Office Area</b> — you are <b>${dist}m</b> away from <b>${esc(branch)}</b> (allowed: ${rad}m). Please move closer to the office to punch.`,'error');
      toast('Outside office area — punch failed.',true);
    } else if(payload.wifi_fallback){
      const wifiHelp='<div style="margin-top:6px">If you are on <b>office WiFi</b>: this WiFi IP is not on the list yet — <b>ask the admin</b> to add it from Office Location → "New IPs" (a one-click job).</div>';
      _geoNote((wifiWhy||esc(m))+wifiHelp,'error');
      toast(_stripTags(wifiWhy||m),true);
    } else { toast(m,true); if(m.includes('Location')||m.includes('GPS')) _geoNote(esc(m),'error'); }
  }
  if(document.getElementById('t-punch-wrap')) renderPunchCard('t-punch-wrap');
  if(document.getElementById('ta-punch-wrap')) renderPunchCard('ta-punch-wrap');
  if(document.getElementById('ta-timing')) tMyTiming();
  if(document.getElementById('ta-history')) tAttHistory();
}

// ---- Teacher Attendance page ----
let _tAttMonth='';
async function loadTAttendance(){
  const el=document.getElementById('t-attendance-content');
  if(window._tAttOff){ renderTTargetOnly(el); return; }
  _tAttMonth=_tAttMonth||curMonth();
  el.innerHTML=`<div class="sm-head"><h2>My Attendance</h2><p>Punch in / punch out daily. Your counted hours = punch gap <b>minus lunch break</b> (full time). Leaving before your assigned hours still marks you <b>Present (Short)</b>. Please take prior approval for any leave.</p></div>
    <div id="ta-timing"></div>
    <div class="att-grid">
      <div id="ta-punch-wrap"></div>
      <div class="card"><div class="card-header"><h3>Month Overview</h3><input type="month" class="form-control" style="width:auto;padding:6px 10px" id="ta-month" value="${_tAttMonth}" onchange="_tAttMonth=this.value;tAttHistory()"></div><div class="card-body" id="ta-cal"><div class="spinner"></div></div></div>
      <div class="card"><div class="card-header"><h3>Leave Requests</h3><button class="btn btn-primary btn-sm" onclick="openTLeave()">${ic('plus')} Apply Leave</button></div><div class="card-body" id="ta-leaves"><div class="spinner"></div></div></div>
    </div>
    <div class="card" style="margin-top:18px"><div class="card-header"><h3>Recent Days</h3></div><div class="card-body" id="ta-logs"><div class="spinner"></div></div></div>
    <div class="card" style="margin-top:18px"><div class="card-header"><h3>Full Month Record</h3><span id="ta-summary" style="display:flex;gap:8px;flex-wrap:wrap"></span></div><div class="card-body"><div id="ta-history"><div class="spinner"></div></div></div></div>`;
  renderPunchCard('ta-punch-wrap');
  tMyTiming();
  tAttHistory();
  tLeaveFetch();
}
// ---- My Work Timing card (teacher, read-only) ----
async function tMyTiming(){
  const box=document.getElementById('ta-timing'); if(!box) return;
  try{
    const [wp,td]=await Promise.all([api('/api/teacher/work-policy'),api('/api/teacher/attendance/today')]);
    const p=wp.policy||{};
    const wtChip=p.work_type==='part_time'?'<span class="myt-chip blue">PART TIME</span>':'<span class="myt-chip gold">FULL TIME</span>';
    const modeChip=p.mode==='flexible'?'<span class="myt-chip">FLEXIBLE · MIN 1H</span>'
      :p.mode==='fixed'?`<span class="myt-chip">FIXED · ${esc(p.entry_time||'')} – ${esc(p.exit_time||'')}</span>`
      :'<span class="myt-chip">HOURS ONLY · NO FIXED TIME</span>';
    const brkChip=(p.work_type==='full_time'&&p.break_minutes)?`<span class="myt-chip">LUNCH ${p.break_minutes}M — NOT COUNTED</span>`:'';
    const req=p.required||8;
    const net=(td&&td.net_hours!=null)?td.net_hours:null;
    const pct=net!=null?Math.min(100,Math.round(net/req*100)):0;
    const extra=(td&&td.extra_hours)||0;
    const state=net==null?'<span class="myt-chip">NOT PUNCHED IN YET</span>'
      :td.punch_out&&net>=req?'<span class="myt-chip green">DAY TARGET COMPLETE</span>'
      :td.punch_out?'<span class="myt-chip gold">PRESENT · SHORT</span>'
      :net>=req?'<span class="myt-chip green">TARGET DONE — STILL ON DUTY</span>':'<span class="myt-chip">ON DUTY</span>';
    box.innerHTML=`<div class="myt-card">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;flex-wrap:wrap">
        <div><div style="font-size:.66rem;font-weight:800;letter-spacing:.07em;color:var(--text-muted);text-transform:uppercase;margin-bottom:6px">My Work Timing — set by admin</div>
          <div class="myt-row">${wtChip}${modeChip}${brkChip}<span class="myt-chip gold">TARGET ${req}h / DAY</span></div></div>
        ${state}
      </div>
      <div class="wt-prog" style="margin-top:14px"><div class="${net!=null&&net>=req?'done':''}" style="width:${pct}%"></div></div>
      <div style="display:flex;justify-content:space-between;font-size:.74rem;font-weight:700;color:var(--text-muted);margin-top:6px">
        <span>Today: <b style="color:var(--text)">${net!=null?net+' h':'—'}</b> counted of ${req}h</span>
        ${extra>0?`<span style="color:#2563eb">+${extra}h extra today (no extra payout)</span>`:'<span>'+pct+'% of target</span>'}
      </div>
      ${p.work_type==='full_time'&&p.break_minutes?`<div class="myt-note">Lunch break of <b>${p.break_minutes} minutes</b> is skipped from your counted hours — e.g. a ${req}+${Math.round(p.break_minutes/60*10)/10}h punch gap counts as ${req}h.</div>`:''}
    </div>`;
  }catch(e){ box.innerHTML=''; }
}
// ---- Leave (teacher) ----
async function tLeaveFetch(){
  const box=document.getElementById('ta-leaves'); if(!box) return;
  try{
    const d=await api('/api/teacher/leaves/my');
    const rows=d.leaves||[];
    box.innerHTML=rows.length?rows.map(l=>{
      const pill=l.status==='approved'?'<span class="po-pill green">APPROVED</span>':l.status==='rejected'?'<span class="po-pill red">REJECTED</span>':'<span class="po-pill amber">PENDING</span>';
      return `<div class="lv-row"><div style="min-width:0"><div class="lv-d">${esc(fmtNice(l.start_date))}${l.end_date!==l.start_date?' → '+esc(fmtNice(l.end_date)):''} <span style="font-weight:600;color:var(--text-muted)">(${l.leave_type==='half'?'Half day':'Full day'})</span></div>
        <div class="lv-r">${esc(l.reason)}${l.admin_remark?` · <b>Admin:</b> ${esc(l.admin_remark)}`:''}</div></div>${pill}</div>`;
    }).join(''):`<div class="pay-empty">No leave requests yet. Need a day off? Apply first — approved leave is marked as <b>Leave</b>, not absent. Without approval, the day counts as <b>AB</b>.</div>`;
  }catch(e){ box.innerHTML=errHtml(e); }
}
function openTLeave(){
  const today=new Date().toISOString().slice(0,10);
  showModal('Apply for Leave',`
    <div class="form-grid vt-form">
      <div class="form-group"><label>From Date</label><input id="tlv-from" type="date" class="input" value="${today}" min="${today}"></div>
      <div class="form-group"><label>To Date</label><input id="tlv-to" type="date" class="input" value="${today}" min="${today}"></div>
      <div class="form-group" style="grid-column:1/-1"><label>Leave Type</label><select id="tlv-type" class="input"><option value="full">Full Day</option><option value="half">Half Day (same date)</option></select></div>
      <div class="form-group" style="grid-column:1/-1"><label>Reason</label><textarea id="tlv-reason" class="input" rows="2" placeholder="e.g. Family function, medical appointment..."></textarea></div>
    </div>
    <p style="font-size:.74rem;color:var(--text-muted)">Your request goes to the admin for approval. <b>Approved</b> leave is marked as Leave in your record; leave taken <b>without approval</b> is marked AB (absent).</p>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="tLeaveApply()">${ic('send')} Send for Approval</button>`);
}
async function tLeaveApply(){
  const payload={start_date:val('tlv-from'),end_date:val('tlv-to'),leave_type:val('tlv-type'),reason:(val('tlv-reason')||'').trim()};
  if(!payload.start_date||!payload.end_date){ toast('Please pick the leave dates'); return; }
  if(payload.reason.length<3){ toast('Please write a short reason'); return; }
  try{
    await api('/api/teacher/leaves/apply','POST',payload);
    closeModal(); toast('Leave request sent for approval.');
    tLeaveFetch(); tAttHistory();
  }catch(e){ toast(e.message||'Could not apply'); }
}
async function tAttHistory(){
  const box=document.getElementById('ta-history'); if(!box) return;
  const cal=document.getElementById('ta-cal'), logs=document.getElementById('ta-logs');
  try{
    const d=await api('/api/teacher/attendance/history?month='+encodeURIComponent(_tAttMonth||curMonth()));
    const sm=document.getElementById('ta-summary');
    if(sm) sm.innerHTML=`<span class="po-pill green">PRESENT ${d.present_days}</span><span class="po-pill blue">LEAVE ${d.leave_days||0}</span>${d.short_days?`<span class="po-pill amber">SHORT ${d.short_days} (PRESENT)</span>`:''}<span class="po-pill red">AB ${d.absent_days||0}</span><span class="po-pill gold">${d.total_hours} COUNTED HRS</span>${d.extra_hours>0?`<span class="po-pill" style="background:rgba(37,99,235,.12);color:#1d4ed8">+${d.extra_hours}H EXTRA (NO PAYOUT)</span>`:''}`;
    // ---- calendar ----
    if(cal){
      const [yy,mm]=d.month.split('-').map(Number);
      const daysIn=new Date(yy,mm,0).getDate();
      const byDate={}; d.rows.forEach(r=>byDate[r.date]=r);
      const leaves=new Set(d.leave_dates||[]);
      const now=new Date(); const isCur=(now.getFullYear()===yy&&now.getMonth()+1===mm);
      const lastEl=isCur?now.getDate():daysIn;
      const _off=(new Date(yy,mm-1,1).getDay()+6)%7;
      let cells='';
      for(let _b=0;_b<_off;_b++) cells+='<div class="cal-d blank"></div>';
      for(let day=1;day<=daysIn;day++){
        const ds=`${yy}-${String(mm).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
        const r=byDate[ds];
        let cls='';
        if(r){ cls=r.status==='present'?' on':(r.status==='short'?' sh':''); }
        else if(leaves.has(ds)) cls=' lv';
        else if(day<=lastEl&&!isCur||(isCur&&day<now.getDate())) cls=' ab';
        if(isCur&&day>now.getDate()) cls='';
        const today=isCur&&now.getDate()===day;
        cells+=`<div class="cal-d${cls}${today?' today':''}${(!cls&&isCur&&day>now.getDate())?' future':''}">${day}</div>`;
      }
      cal.innerHTML=`<div class="cal-head">
          <div class="cal-stat g"><div class="n">${d.present_days}</div><div class="l">Present</div></div>
          <div class="cal-stat" style="--x:1"><div class="n" style="color:#1d4ed8">${d.leave_days||0}</div><div class="l">Leave</div></div>
          <div class="cal-stat"><div class="n" style="color:#b45309">${d.short_days||0}</div><div class="l">Short</div></div>
          <div class="cal-stat r"><div class="n">${d.absent_days||0}</div><div class="l">AB</div></div>
          <div class="cal-stat b"><div class="n">${d.total_hours}</div><div class="l">Hours</div></div>
        </div>
        <div class="cal-wk"><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span></div>
        <div class="cal-grid">${cells}</div>
        <div class="cal-leg"><span><i style="background:rgba(16,185,129,.6)"></i>Present</span><span><i style="background:rgba(59,130,246,.55)"></i>Leave</span><span><i style="background:rgba(245,158,11,.6)"></i>Present · Short (early leave)</span><span><i style="background:rgba(220,38,38,.45)"></i>AB</span><span><i style="outline:2px solid #b8941f;outline-offset:-1px;background:transparent"></i>Today</span></div>`;
    }
    // ---- recent logs ----
    if(logs){
      const recent=d.rows.slice(0,6);
      const pill=r=>r.status==='present'?'<span class="po-pill green">PRESENT</span>':r.status==='short'?'<span class="po-pill amber">PRESENT · SHORT</span>':r.status==='working'?'<span class="po-pill blue">ON DUTY</span>':'<span class="po-pill amber">NO PUNCH</span>';
      logs.innerHTML=recent.length?recent.map(r=>`<div class="log-row">
          <div><div class="d">${esc(fmtNice(r.date))}</div><div class="t">${esc(r.punch_in||'-')} ${r.punch_out?'to '+esc(r.punch_out):''}${r.net_hours!=null?' - '+r.net_hours+' hrs counted':''}${r.extra_hours>0?` <span class="att-x">+${r.extra_hours}h extra</span>`:''}</div></div>
          ${pill(r)}
        </div>`).join(''):`<div class="pay-empty">No attendance yet this month. Punch in on any working day and it will appear here.</div>`;
    }
    // ---- full table ----
    const stPill=s=>s==='present'?'<span class="po-pill green">PRESENT</span>':s==='short'?'<span class="po-pill amber">PRESENT · SHORT</span>':s==='working'?'<span class="po-pill blue">ON DUTY</span>':'-';
    if(!d.rows.length){ box.innerHTML=`<div class="empty-state"><p>No attendance recorded in ${esc(fmtMonthLabel(d.month))} yet.</p></div>`; return; }
    box.innerHTML=`<div style="overflow-x:auto"><table class="att-table"><thead><tr><th>Date</th><th>Day</th><th>Punch In</th><th>Punch Out</th><th>Counted</th><th>Extra</th><th>Status</th></tr></thead><tbody>${
      d.rows.map(r=>`<tr><td>${esc(fmtNice(r.date))}</td><td>${esc(r.day)}</td><td>${esc(r.punch_in||'-')}</td><td>${esc(r.punch_out||'-')}</td><td>${r.net_hours!=null?`<b>${r.net_hours} h</b>`:'-'}${r.net_hours!=null&&r.hours!=null&&r.net_hours!==r.hours?`<div class="att-brk">gap ${r.hours}h − break</div>`:''}</td><td>${r.extra_hours>0?`<b style="color:#2563eb">+${r.extra_hours}h</b>`:'—'}</td><td>${stPill(r.status)}</td></tr>`).join('')
    }</tbody></table></div>`;
  }catch(e){ box.innerHTML=errHtml(e); if(cal)cal.innerHTML=''; if(logs)logs.innerHTML=''; }
}

// ---- Appointment letter (shared builder) ----
function buildLetterHTML(c){
  const today=new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});
  const jd=c.joining_date?new Date(c.joining_date).toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'}):'as mutually agreed';
  const rules=(c.rules||[]).length?`<div style="margin-top:14px"><strong>Rules and Conditions</strong><ol class="al-rules" style="margin:8px 0 0 18px">${c.rules.map(r=>`<li>${esc(r)}</li>`).join('')}</ol></div>`:'';
  const sig=c.accepted?`<div style="margin-top:6px"><span class="al-sig">${esc(c.signature_name||c.teacher_name||'')}</span><div style="font-size:.78rem;color:var(--text-muted)">Digitally signed by ${esc(c.signature_name||'')} on ${esc(c.accepted_at||'')}</div></div>`:`<div style="margin-top:22px;border-bottom:1.5px solid var(--border);width:220px"></div><div style="font-size:.78rem;color:var(--text-muted);margin-top:4px">Signature of Teacher</div>`;
  return `<div class="al-letter">
    <div class="al-lh"><div class="b">MVS FOUNDATION</div><div class="s">Manish Verma Classes - NIOS Coaching Institute, Delhi</div></div>
    <div style="display:flex;justify-content:space-between;font-size:.82rem;color:var(--text-muted)"><span>Ref: MVS/APT/${esc((c.teacher_name||'T').split(' ')[0].toUpperCase())}</span><span>Date: ${esc(today)}</span></div>
    <h2>APPOINTMENT LETTER</h2>
    <p>Dear <strong>${esc(c.teacher_name||'Teacher')}</strong>,</p>
    <p>We are pleased to appoint you as <strong>${esc(c.designation||'Subject Teacher')}</strong> at MVS Foundation (Manish Verma Classes), effective <strong>${esc(jd)}</strong>. Your terms of engagement are as follows:</p>
    <table class="terms">
      <tr><td>Designation</td><td>${esc(c.designation||'Subject Teacher')}</td></tr>
      <tr><td>Date of Joining</td><td>${esc(jd)}</td></tr>
      ${(c.breakup||[]).length?c.breakup.map(b=>`<tr><td>${esc(b.label)}</td><td>${fmtINR(b.amount)}</td></tr>`).join(''):`<tr><td>Monthly Base Salary</td><td>${fmtINR(c.base_salary)}</td></tr>
      <tr><td>Fixed Monthly Allowances</td><td>${fmtINR(c.allowances)}</td></tr>`}
      <tr><td style="font-weight:700">Gross Monthly Salary</td><td style="font-weight:700">${fmtINR(c.gross_salary||(c.base_salary+(c.allowances||0)))}</td></tr>
      <tr><td>Payable Working Days</td><td>${c.working_days} days per month</td></tr>
      <tr><td>Per Day Rate</td><td>${fmtINR(c.per_day_rate)}</td></tr>
    </table>
    <p><strong>Attendance and Payment Policy.</strong> Daily attendance is recorded through the portal Punch In and Punch Out system. For every payable working day not attended, a deduction equal to the per day rate (${fmtINR(c.per_day_rate)}) is applied. Payments for extra classes, bonuses and any deductions are always itemised with reasons in the Payout section of your portal, so you can see exactly where full payment is made and where a deduction applies.</p>
    ${rules}
    <p style="margin-top:16px">We look forward to working with you towards the success of our students.</p>
    <div style="display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;margin-top:26px">
      <div><div style="font-weight:700">Accepted by</div>${sig}</div>
      <div style="text-align:right"><div style="font-weight:700">For MVS Foundation</div><div class="al-sig" style="margin-top:6px">Manish Verma</div><div style="font-size:.78rem;color:var(--text-muted)">Director, MVS Foundation</div></div>
    </div>
  </div>`;
}
