let _aAttDate='', _aAttView='day', _aAttMonth='', _aWtOpen=false;
async function loadAAttendance(){
  const el=document.getElementById('a-attendance-content');
  _aAttDate=_aAttDate||new Date().toISOString().slice(0,10);
  _aAttMonth=_aAttMonth||curMonth();
  el.innerHTML=`<div class="sm-head"><h2>Teacher Attendance</h2><p>Smart timing per teacher — set fixed hours, hours-only or flexible (min 1h). Counted hours = punch gap <b>minus lunch break</b> (full time). Leaving early still counts <b>Present (Short)</b>; extra hours show in reports but <b>never add payout</b>.</p></div>
    <div class="card" style="margin-bottom:18px"><div class="card-header"><h3>${ic('clipboard')} Leave Requests</h3><span id="a-lv-badge"></span></div>
      <div class="card-body" id="a-leave-body"><div class="spinner"></div></div></div>
    <div class="card" style="margin-bottom:18px"><div class="card-header"><h3>Work Timings — Per Teacher</h3>
      <button class="btn btn-ghost btn-sm" id="a-wt-toggle" onclick="_aWtOpen=!_aWtOpen;loadAAttendance()">${_aWtOpen?'Hide':'Show'} Settings</button></div>
      <div class="card-body" id="a-wt-body" style="${_aWtOpen?'':'display:none'}"><div class="spinner"></div></div></div>
    <div class="card"><div class="card-header"><h3>Attendance</h3>
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">
        <button class="btn btn-primary btn-sm" onclick="openAdminPunch()">${ic('clock')} Add Punch</button>
        <button class="btn btn-ghost btn-sm" onclick="openOfficeLocation()">${ic('location')} Office Location</button>
        <div class="tt-toggle"><button class="${_aAttView==='day'?'active':''}" onclick="_aAttView='day';loadAAttendance()">Day View</button><button class="${_aAttView==='month'?'active':''}" onclick="_aAttView='month';loadAAttendance()">Month Summary</button></div>
        ${_aAttView==='day'
          ?`<input type="date" class="form-control" style="width:auto;padding:7px 12px" value="${_aAttDate}" onchange="_aAttDate=this.value;aAttFetch()">`
          :`<input type="month" class="form-control" style="width:auto;padding:7px 12px" value="${_aAttMonth}" onchange="_aAttMonth=this.value;aAttFetch()">`}
      </div></div>
    <div class="card-body"><div id="a-att-summary" style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:14px"></div><div id="a-att-body"><div class="spinner"></div></div></div></div>`;
  aAttFetch();
  aLeaveFetch();
  if(_aWtOpen) aWtFetch();
}
// ---- Work Timings settings (per-teacher cards) ----
async function aWtFetch(){
  const box=document.getElementById('a-wt-body'); if(!box) return;
  try{
    const d=await api('/api/admin/attendance/policies');
    const rows=d.teachers||[];
    if(!rows.length){ box.innerHTML='<div class="empty-state"><p>No active teachers found.</p></div>'; return; }
    window._wtRows=rows;
    box.innerHTML=`<div class="alert alert-info" style="font-size:.78rem;margin-bottom:14px">Set each teacher's timing once — reports, short-day marking and extra hours all follow it automatically. <b>Full Time</b> skips the lunch break from counted hours; <b>Part Time</b> has no break. <b>Flexible</b> = minimum 1 hour, no fixed schedule. Extra hours are shown in reports but <b>never add payout</b>. Set <b>Attendance System = Disabled</b> for teachers who punch on the other app — they only see their daily target here (no punch, payout, appointment letter or slip).</div>
      <div class="wt-grid">${rows.map((t,i)=>{
        const p=t.policy||{};
        const set=p.configured;
        return `<div class="wt-card" id="wt-card-${i}">
          <div class="wt-head"><div class="wt-av">${esc(initials(t.name||'T'))}</div>
            <div style="min-width:0"><div class="wt-name">${esc(t.name)}</div><div class="wt-sub">${esc((t.subjects||[]).slice(0,2).join(' · ')||'—')}</div></div>
            <span class="wt-chip ${set?'set':'def'}">${set?'SET':'DEFAULT'}</span>${p.disabled?'<span class="wt-chip" style="background:#fee2e2;color:#b91c1c">NO PUNCH</span>':''}</div>
          <div class="wt-now">Current: <b>${esc(p.label||'—')}</b>${p.break_minutes?` · lunch break <b>${p.break_minutes}m</b> skipped`:''} · target <b>${p.required}h/day</b>${p.disabled?' · <b style="color:#b91c1c">TARGET ONLY</b>':''}</div>
          <div class="wt-form">
            <div class="full"><span class="wt-lbl">Attendance System</span><select class="input" id="wt-off-${i}">
              <option value="0"${!p.disabled?' selected':''}>Enabled — punch in/out on this portal</option>
              <option value="1"${p.disabled?' selected':''}>Disabled — target only (punch managed on other app)</option></select></div>
            <div class="full"><span class="wt-lbl">Work Type</span><select class="input" id="wt-type-${i}" onchange="wtTypeChange(${i})">
              <option value="full_time"${p.work_type==='full_time'?' selected':''}>Full Time — lunch break skipped</option>
              <option value="part_time"${p.work_type==='part_time'?' selected':''}>Part Time — no break</option></select></div>
            <div class="full"><span class="wt-lbl">Timing Mode</span><select class="input" id="wt-mode-${i}" onchange="wtModeChange(${i})">
              <option value="fixed"${p.mode==='fixed'?' selected':''}>Fixed Timing (entry &amp; exit)</option>
              <option value="hours"${p.mode==='hours'?' selected':''}>Hours Only (daily target)</option>
              <option value="flexible"${p.mode==='flexible'?' selected':''}>Flexible (min 1 hour)</option></select></div>
            <div class="wt-t" id="wt-en-w-${i}"><span class="wt-lbl">Entry Time</span><input type="time" class="input" id="wt-en-${i}" value="${esc(p.entry_time||'09:30')}" oninput="wtCalc(${i})"></div>
            <div class="wt-t" id="wt-ex-w-${i}"><span class="wt-lbl">Exit Time</span><input type="time" class="input" id="wt-ex-${i}" value="${esc(p.exit_time||'18:30')}" oninput="wtCalc(${i})"></div>
            <div class="wt-h" id="wt-rh-w-${i}"><span class="wt-lbl">Required Hrs / Day</span><input type="number" class="input" id="wt-rh-${i}" min="1" max="16" step="0.5" value="${p.required_hours||8}" oninput="wtCalc(${i})"></div>
            <div class="wt-b" id="wt-br-w-${i}"><span class="wt-lbl">Lunch Break (min)</span><input type="number" class="input" id="wt-br-${i}" min="0" max="240" step="5" value="${p.break_minutes||0}" oninput="wtCalc(${i})"></div>
          </div>
          <div class="wt-req"><span id="wt-calc-${i}">Target: <b>${p.required}h</b> counted per day</span><span class="att-brk">break never counted</span></div>
          <button class="btn btn-primary btn-sm wt-save" onclick="wtSave(${t.teacher_id},${i})">${ic('check')} Save Timing</button>
        </div>`;
      }).join('')}</div>`;
    rows.forEach((t,i)=>wtModeChange(i,true));
  }catch(e){ box.innerHTML=errHtml(e); }
}
function wtTypeChange(i){ wtModeChange(i,true); }
function wtModeChange(i,silent){
  const mode=(document.getElementById('wt-mode-'+i)||{}).value||'hours';
  const wt=(document.getElementById('wt-type-'+i)||{}).value||'full_time';
  const show=(id,on)=>{ const el=document.getElementById(id); if(el) el.style.display=on?'':'none'; };
  show('wt-en-w-'+i, mode==='fixed'); show('wt-ex-w-'+i, mode==='fixed');
  show('wt-rh-w-'+i, mode==='hours');
  show('wt-br-w-'+i, wt==='full_time'&&mode!=='flexible');
  wtCalc(i);
}
function wtCalc(i){
  const mode=(document.getElementById('wt-mode-'+i)||{}).value||'hours';
  const wt=(document.getElementById('wt-type-'+i)||{}).value||'full_time';
  const gv=id=>{ const el=document.getElementById(id); return el?el.value:''; };
  const brk=(wt==='full_time'&&mode!=='flexible')?(parseInt(gv('wt-br-'+i))||0):0;
  let txt='';
  if(mode==='flexible') txt='Target: <b>min 1h</b> — fully flexible';
  else if(mode==='fixed'){
    const en=gv('wt-en-'+i), ex=gv('wt-ex-'+i);
    const pm=s=>{ const p=String(s||'').split(':'); return p.length===2?(+p[0])*60+(+p[1]):null; };
    const a=pm(en), b=pm(ex);
    if(a!=null&&b!=null&&b>a){ const h=((b-a-brk)/60); txt=`Target: <b>${Math.round(h*100)/100}h</b> counted (${en} – ${ex}${brk?` − ${brk}m break`:''})`; }
    else txt='Target: set valid entry & exit times';
  } else txt=`Target: <b>${gv('wt-rh-'+i)||8}h</b> counted per day${brk?` (− ${brk}m break)`:''}`;
  const el=document.getElementById('wt-calc-'+i); if(el) el.innerHTML=txt;
}
async function wtSave(tid,i){
  const gv=id=>{ const el=document.getElementById(id); return el?el.value:''; };
  const payload={teacher_id:tid, work_type:gv('wt-type-'+i)||'full_time', mode:gv('wt-mode-'+i)||'hours',
    entry_time:gv('wt-en-'+i), exit_time:gv('wt-ex-'+i),
    required_hours:parseFloat(gv('wt-rh-'+i))||0, break_minutes:parseInt(gv('wt-br-'+i))||0,
    disabled:(gv('wt-off-'+i)==='1')};
  const btn=document.querySelector('#wt-card-'+i+' .wt-save');
  if(btn){ btn.disabled=true; btn.textContent='Saving...'; }
  try{
    const r=await api('/api/admin/attendance/policy','POST',payload);
    toast(r.message); aWtFetch(); aAttFetch();
  }catch(e){ toast(e.message||'Could not save',true); if(btn){ btn.disabled=false; btn.innerHTML=ic('check')+' Save Timing'; } }
}
// ---- Admin manual punch (teacher punch karna bhool gaya ho) ----
async function openAdminPunch(){
  let ts=[];
  try{ const d=await api('/api/admin/attendance/policies'); ts=d.teachers||[]; }catch(e){}
  if(!ts.length){ toast('No active teachers found.',true); return; }
  const today=new Date().toISOString().slice(0,10);
  showModal('Add Punch — Admin Entry',
 `<div class="alert alert-info" style="font-size:.78rem">Teacher present tha par <b>punch karna bhool gaya</b>? Date aur in/out time daal kar entry kar dein — present/short apne aap policy ke hisaab se calculate hoga, aur teacher ko notification chali jayegi.</div>
  <div class="form-group"><label>Teacher</label><select class="form-control" id="ap-t">${ts.map(t=>`<option value="${t.teacher_id}">${esc(t.name)}</option>`).join('')}</select></div>
  <div class="form-group"><label>Date</label><input type="date" class="form-control" id="ap-d" max="${today}" value="${_aAttDate||today}"></div>
  <div class="ex-grid2">
   <div><label class="ex-lbl">Punch In</label><input type="time" class="form-control" id="ap-in" value="09:30"></div>
   <div><label class="ex-lbl">Punch Out</label><input type="time" class="form-control" id="ap-out" value="18:30"></div>
  </div>`,
 `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" id="ap-btn" onclick="submitAdminPunch()">${ic('check')} Save Punch</button>`);
}
async function submitAdminPunch(){
  const body={teacher_id:parseInt(val('ap-t'))||0, date:val('ap-d'), punch_in:val('ap-in'), punch_out:val('ap-out')};
  if(!body.teacher_id||!body.date||!body.punch_in){ toast('Teacher, date and punch-in time are required.',true); return; }
  const btn=document.getElementById('ap-btn'); btn.disabled=true; btn.textContent='Saving...';
  try{
    const r=await api('/api/admin/attendance/punch','POST',body);
    closeModal(); toast(`Punch saved — In ${r.punch_in}${r.punch_out?', Out '+r.punch_out:''}.`);
    aAttFetch();
  }catch(e){ toast(e.message,true); btn.disabled=false; btn.textContent='Save Punch'; }
}
// ---- Leave approvals (admin) ----
async function aLeaveFetch(){
  const box=document.getElementById('a-leave-body'); if(!box) return;
  try{
    const d=await api('/api/admin/leaves');
    const rows=d.leaves||[];
    const badge=document.getElementById('a-lv-badge');
    if(badge) badge.innerHTML=d.pending_count?`<span class="po-pill amber">${d.pending_count} PENDING</span>`:`<span class="po-pill green">ALL CLEAR</span>`;
    if(!rows.length){ box.innerHTML=`<div class="pay-empty">No leave requests yet. When a teacher applies for leave, it will appear here for approval.</div>`; return; }
    const pend=rows.filter(l=>l.status==='pending');
    const done=rows.filter(l=>l.status!=='pending').slice(0,6);
    const pill=l=>l.status==='approved'?`<span class="po-pill green">APPROVED${l.paid?' · PAID':' · UNPAID'}</span>`:'<span class="po-pill red">REJECTED</span>';
    box.innerHTML=(pend.length?pend.map(l=>`<div class="lv-card pend">
        <div class="lv-head"><div><div class="lv-name">${esc(l.teacher)}</div><div class="lv-dates">${esc(fmtNice(l.start_date))}${l.end_date!==l.start_date?' → '+esc(fmtNice(l.end_date)):''} · ${l.days} day${l.days>1?'s':''} · ${l.leave_type==='half'?'Half day':'Full day'} · applied ${esc(l.created_at)}</div></div><span class="po-pill amber">PENDING</span></div>
        <div class="lv-reason">${esc(l.reason)}</div>
        <div class="lv-actions"><button class="btn btn-primary btn-sm" onclick="aLeaveApproveOpen(${l.id})">${ic('check')} Approve</button><button class="btn btn-ghost btn-sm" style="border-color:rgba(220,38,38,.5);color:#b91c1c" onclick="aLeaveReject(${l.id})">Reject</button></div>
      </div>`).join(''):'')
      +(done.length?`<div style="font-size:.68rem;font-weight:800;color:var(--text-muted);text-transform:uppercase;letter-spacing:.06em;margin:12px 0 4px">Recently reviewed</div>`:'')
      +done.map(l=>`<div class="lv-row"><div style="min-width:0"><div class="lv-d">${esc(l.teacher)} — ${esc(fmtNice(l.start_date))}${l.end_date!==l.start_date?' → '+esc(fmtNice(l.end_date)):''}</div>
        <div class="lv-r">${esc(l.reason)}${l.admin_remark?` · Remark: ${esc(l.admin_remark)}`:''}</div></div>${pill(l)}</div>`).join('');
  }catch(e){ box.innerHTML=errHtml(e); }
}
function aLeaveApproveOpen(id){
  showModal('Approve Leave',`
    <div class="alert alert-info" style="font-size:.78rem">Approve karte waqt choose karein ki ye leave <b>paid</b> hai ya <b>unpaid</b>. Unpaid leave complete salary ke per-day rate se katti hai; paid pe koi deduction nahi. Approved full-day leave ki us-din ki classes time table me apne aap aage move ho jayengi (teacher ke reschedule count pe asar nahi) aur students ko notification chali jayegi.</div>
    <div class="form-group"><label>Leave Type (pay)</label><select class="form-control" id="alv-paid">
      <option value="unpaid" selected>Unpaid Leave — per-day salary deduction hogi</option>
      <option value="paid">Paid Leave — payout pe koi asar nahi</option>
    </select></div>
    <div class="form-group"><label>Remark (optional)</label><input class="form-control" id="alv-remark2" placeholder="e.g. Approved — classes auto-moved"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="aLeaveApproveSubmit(${id})">${ic('check')} Approve Leave</button>`);
}
async function aLeaveApproveSubmit(id){
  const paid=val('alv-paid')==='paid';
  const remark=(val('alv-remark2')||'').trim();
  try{
    const r=await api('/api/admin/leaves/'+id+'/review','POST',{action:'approved',paid,remark});
    toast(`Leave approved (${paid?'PAID':'UNPAID'}).`+(r.classes_moved?` ${r.classes_moved} class(es) auto-moved — students notified.`:''));
    closeModal(); aLeaveFetch(); aAttFetch();
  }catch(e){ toast(e.message||'Could not review'); }
}
async function aLeaveReview(id,action,remark){
  try{
    await api('/api/admin/leaves/'+id+'/review','POST',{action,remark:remark||''});
    toast(action==='approved'?'Leave approved.':'Leave rejected.');
    closeModal(); aLeaveFetch(); aAttFetch();
  }catch(e){ toast(e.message||'Could not review'); }
}
function aLeaveReject(id){
  showModal('Reject Leave',`
    <div class="form-group"><label>Reason for rejection (shown to the teacher)</label><textarea id="alv-remark" class="input" rows="2" placeholder="e.g. Exam week — classes cannot be cancelled"></textarea></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="aLeaveReview(${id},'rejected',(document.getElementById('alv-remark')||{}).value||'')">Reject Leave</button>`);
}
async function aAttFetch(){
  const body=document.getElementById('a-att-body'), sum=document.getElementById('a-att-summary');
  if(!body) return;
  try{
    if(_aAttView==='day'){
      const d=await api('/api/admin/attendance?day='+encodeURIComponent(_aAttDate));
      const nLeave=(d.teachers||[]).filter(t=>t.status==='leave').length;
      const nShort=(d.teachers||[]).filter(t=>t.status==='short').length;
      sum.innerHTML=`<span class="po-pill green">PRESENT ${d.present} / ${d.total}</span>${nLeave?`<span class="po-pill blue">ON LEAVE ${nLeave}</span>`:''}${nShort?`<span class="po-pill amber">PRESENT (SHORT) ${nShort}</span>`:''}<span class="po-pill slate">${esc(d.day).toUpperCase()}, ${esc(fmtNice(d.date)).toUpperCase()}</span>`;
      if(!d.teachers.length){ body.innerHTML='<div class="empty-state"><p>No active teachers found.</p></div>'; return; }
      const pill=t=>t.status==='offsite'?'<span class="po-pill slate">TARGET ONLY</span>':t.status==='working'?'<span class="po-pill green">ON DUTY</span>':t.status==='done'?'<span class="po-pill gold">DAY COMPLETE</span>':t.status==='leave'?'<span class="po-pill blue">ON LEAVE</span>':t.status==='short'?'<span class="po-pill amber">PRESENT · SHORT</span>':'<span class="po-pill red">NOT PUNCHED</span>';
      window._aAttRows={}; d.teachers.forEach(t=>window._aAttRows[t.teacher_id]=t);
      const _chip=(dist,office)=>dist==null?'':(dist===0&&office)?` <span style="font-size:.62rem;font-weight:800;color:#059669" title="Office WiFi/PC se punch (network verified)">(WiFi)</span>`:` <span style="font-size:.62rem;font-weight:800;color:${dist<=50?'#059669':'#d97706'}" title="Office se punch distance">(${dist}m)</span>`;
      const _hrs=t=>{
        if(t.net_hours==null&&t.hours==null) return '-';
        const main=t.net_hours!=null?t.net_hours:t.hours;
        const lnk=`<a href="javascript:void(0)" onclick="openAttDayStatus(${t.teacher_id})" title="View location status" style="font-weight:800;color:var(--primary,#b8941f);text-decoration:underline dotted">${main} h</a>`;
        const sub=t.net_hours!=null&&t.hours!=null&&t.net_hours!==t.hours?`<div class="att-brk">gap ${t.hours}h − break · target ${t.required_hours}h</div>`:(t.required_hours?`<div class="att-brk">target ${t.required_hours}h</div>`:'');
        return lnk+(t.extra_hours>0?`<span class="att-x">+${t.extra_hours}h extra</span>`:'')+sub;
      };
      body.innerHTML=`<div style="overflow-x:auto"><table class="att-table"><thead><tr><th>Teacher</th><th>Work Timing</th><th>Punch In</th><th>Punch Out</th><th>Counted Hours</th><th>Status</th><th></th></tr></thead><tbody>${
        d.teachers.map(t=>`<tr><td style="font-weight:600">${esc(t.name)}</td><td><span class="att-pol" title="${t.policy_set?'Custom timing set':'Default timing (Full Time · 8h/day)'}">${esc(t.policy_label||'—')}</span></td><td>${esc(t.punch_in||'-')}${_chip(t.in_dist,t.in_office)}</td><td>${esc(t.punch_out||'-')}${_chip(t.out_dist,t.out_office)}</td><td>${_hrs(t)}</td><td>${pill(t)}</td><td><button class="btn btn-ghost btn-sm" onclick="openTeacherAttDetail(${t.teacher_id},'${esc((t.name||'').replace(/'/g,''))}')">History</button></td></tr>`).join('')
      }</tbody></table></div>`;
    } else {
      const d=await api('/api/admin/attendance/month?month='+encodeURIComponent(_aAttMonth));
      sum.innerHTML=`<span class="po-pill slate">${esc(fmtMonthLabel(d.month)).toUpperCase()}</span><span class="po-pill gold">ELAPSED ${d.elapsed_days||0} DAYS</span><span class="po-pill green">SHORT DAYS COUNT AS PRESENT</span>`;
      if(!d.teachers.length){ body.innerHTML='<div class="empty-state"><p>No active teachers found.</p></div>'; return; }
      body.innerHTML=`<div style="overflow-x:auto"><table class="att-table"><thead><tr><th>Teacher</th><th>Work Timing</th><th>Present</th><th>Short</th><th>Leave</th><th>AB</th><th>Counted Hours</th><th>Extra Hours</th><th></th></tr></thead><tbody>${
        d.teachers.map(t=>`<tr><td style="font-weight:600">${esc(t.name)}</td><td><span class="att-pol">${esc(t.policy_label||'—')}</span></td><td><b style="color:#059669">${t.present_days}</b><span class="att-brk"> (full ${t.full_days||0})</span></td><td><b style="color:#b45309">${t.short_days||0}</b></td><td><b style="color:#1d4ed8">${t.leave_days||0}</b></td><td>${t.disabled?'<span class="po-pill slate">TARGET ONLY</span>':`<b style="color:#b91c1c">${t.absent_days||0}</b>`}</td><td><span class="att-net">${t.total_hours} h</span></td><td>${t.extra_hours>0?`<b style="color:#2563eb">+${t.extra_hours} h</b><div class="att-brk">no extra payout</div>`:'—'}</td><td><button class="btn btn-ghost btn-sm" onclick="openTeacherAttDetail(${t.teacher_id},'${esc((t.name||'').replace(/'/g,''))}')">History</button></td></tr>`).join('')
      }</tbody></table></div>`;
    }
  }catch(e){ body.innerHTML=errHtml(e); }
}
// ---- Day punch location status (hours click) ----
async function openAttDayStatus(tid){
  const t=(window._aAttRows||{})[tid]; if(!t) return;
  if(!window._aOffices){ try{ const d=await api('/api/admin/office-location'); window._aOffices=d.offices||[]; }catch(e){ window._aOffices=[]; } }
  const limOf=name=>{ const o=(window._aOffices||[]).find(x=>x.name===name); return o?o.radius+20:null; };   // GPS margin samet
  const row=(lbl,time,office,dist)=>{
    if(!time) return `<div style="display:flex;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px dashed var(--border)"><span style="color:var(--text-muted)">${lbl}</span><span>-</span></div>`;
    let loc='';
    if(office&&dist===0) loc=`<div style="font-size:.78rem;margin-top:3px">${ic('location')} <b>${esc(office)}</b> · <span style="color:#059669;font-weight:700">Punched via Office WiFi/PC</span> (network verified)</div>`;
    else if(office&&dist!=null){ const lim=limOf(office); const out=lim!=null&&dist>lim;
      loc=`<div style="font-size:.78rem;margin-top:3px">${ic('location')} <b>${esc(office)}</b> · <b style="color:${out?'#dc2626':(dist<=50?'#059669':'#d97706')}">${dist}m</b> from office${out?' <span style="color:#dc2626;font-weight:700">(outside the radius!)</span>':''}</div>`; }
    else loc=`<div style="font-size:.78rem;color:var(--text-muted);margin-top:3px">location not recorded (geofence was off)</div>`;
    return `<div style="padding:10px 0;border-bottom:1px dashed var(--border)"><div style="display:flex;justify-content:space-between;gap:10px"><span style="color:var(--text-muted)">${lbl}</span><b>${esc(time)}</b></div>${loc}</div>`;
  };
  showModal(`${esc(t.name)} — Punch Location Status`,
   `<div style="font-size:.78rem;color:var(--text-muted);margin-bottom:6px">${esc(fmtNice(_aAttDate))}</div>`+
   row('Punch In', t.punch_in, t.in_office, t.in_dist)+
   row('Punch Out', t.punch_out, t.out_office, t.out_dist)+
   `<div style="display:flex;justify-content:space-between;gap:10px;padding:12px 0 2px"><span style="color:var(--text-muted)">Total Hours</span><b style="font-size:1.05rem">${t.hours!=null?t.hours+' h':'-'}</b></div>
    <div class="alert alert-info" style="font-size:.76rem;margin-top:12px;margin-bottom:0">When geofencing is ON, punches are allowed <b>only from within the office radius</b> — every punch records the branch name and the distance from the office.</div>`,
   `<button class="btn btn-primary" onclick="closeModal()">Close</button>`);
}

async function openTeacherAttDetail(tid,name){
  showModal('Attendance - '+name,
    `<div class="form-group"><label>Month</label><input type="month" class="form-control" id="tad-month" value="${_aAttMonth||curMonth()}" onchange="tadFetch(${tid})"></div><div id="tad-body"><div class="spinner"></div></div>`,
    `<button class="btn btn-primary" onclick="closeModal()">Close</button>`);
  tadFetch(tid);
}
async function tadFetch(tid){
  const b=document.getElementById('tad-body'); if(!b) return;
  try{
    const d=await api('/api/admin/attendance/teacher/'+tid+'?month='+encodeURIComponent(val('tad-month')));
    const lvs=(d.leave_dates||[]);
    const polNote=d.policy?`<div style="margin-bottom:10px"><span class="att-pol">${esc(d.policy.label)}</span> <span class="att-brk">target ${d.required_hours}h/day${d.policy.break_minutes?` · ${d.policy.break_minutes}m break skipped`:''}</span></div>`:'';
    const lvNote=lvs.length?`<div style="margin-bottom:10px"><span class="po-pill blue">LEAVE: ${lvs.map(x=>esc(fmtNice(x))).join(', ')}</span></div>`:'';
    const stPill=s=>s==='present'?'<span class="po-pill green">PRESENT</span>':s==='short'?'<span class="po-pill amber">PRESENT · SHORT</span>':s==='working'?'<span class="po-pill blue">ON DUTY</span>':'-';
    if(!d.rows.length){ b.innerHTML=polNote+lvNote+'<div class="empty-state"><p>No attendance in this month.</p></div>'; return; }
    b.innerHTML=polNote+lvNote+`<div style="overflow-x:auto"><table class="att-table"><thead><tr><th>Date</th><th>Day</th><th>In</th><th>Out</th><th>Counted</th><th>Extra</th><th>Status</th></tr></thead><tbody>${
      d.rows.map(r=>`<tr><td>${esc(fmtNice(r.date))}</td><td>${esc(r.day)}</td><td>${esc(r.punch_in||'-')}</td><td>${esc(r.punch_out||'-')}</td><td>${r.net_hours!=null?`<b>${r.net_hours} h</b>`:'-'}${r.net_hours!=null&&r.hours!=null&&r.net_hours!==r.hours?`<div class="att-brk">gap ${r.hours}h − break</div>`:''}</td><td>${r.extra_hours>0?`<b style="color:#2563eb">+${r.extra_hours}h</b>`:'—'}</td><td>${stPill(r.status)}</td></tr>`).join('')
    }</tbody></table></div>`;
  }catch(e){ b.innerHTML=errHtml(e); }
}

// ---- Admin Payouts ----
let _aPayMonth='';
// ---------- ADMIN: Earnings overview + pay structure editor ----------
async function loadAPayouts(){
  const el=document.getElementById('a-payouts-content');
  _aEarnMonth=_aEarnMonth||curMonth();
  el.innerHTML=`<div class="sm-head" style="display:flex;justify-content:space-between;align-items:flex-end;gap:12px;flex-wrap:wrap"><div><h2>Payouts \u00B7 Earnings Model</h2><p>Live earnings per teacher — appointment-letter rule, auto-calculated from portal activity.</p></div><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><input type="month" class="form-control" style="width:auto;padding:7px 12px" value="${_aEarnMonth}" onchange="_aEarnMonth=this.value;aEarnFetch()"></div></div>
  <div class="ae-stats" id="ae-stats"></div>
  <div id="ae-body" style="margin-top:6px"><div class="spinner"></div></div>`;
  aEarnFetch();
}
async function aEarnFetch(){
  const body=document.getElementById('ae-body'), stats=document.getElementById('ae-stats');
  if(!body) return;
  try{
    const d=await api('/api/admin/earnings?month='+encodeURIComponent(_aEarnMonth));
    _aEarnData=d;
    const _st=(icn,val,lbl)=>`<div class="ae-stat"><div class="ae-stat-ic">${ic(icn)}</div><div><div class="ae-stat-v">${val}</div><div class="ae-stat-l">${lbl}</div></div></div>`;
    // v89: decided monthly salary ka total (max potential sum) — monthly kitna ja sakta hai
    const totSal=d.teachers.reduce((a,x)=>a+(x.target_only?0:((x.earnings&&x.earnings.max_potential)||0)),0);
    if(stats) stats.innerHTML=_st('users',d.teachers.length,'Teachers')+_st('trophy',_inr(totSal),'Monthly Salary (Total)')+_st('wallet',_inr(d.total_net),'Total Net Payable')+_st('chart',d.avg_perf+'%','Average Performance')+_st('calendar',esc(fmtMonthLabel(d.month)),'Pay Month');
    body.innerHTML=(d.total_net===0?`<div class="alert alert-info" style="margin-bottom:14px">The month has just begun — earnings build here automatically as teacher activity is recorded on the portal. There is no activity yet, so all figures show ₹0 (never demo numbers).</div>`:'')
     +((d.target_only_count||0)>0?`<div class="alert alert-info" style="margin-bottom:14px">${d.target_only_count} target-only teacher${d.target_only_count>1?'s':''}: payout runs on the assigned target via the other app — shown here only as an <b>estimated % of salary</b>, never as amounts.</div>`:'')
     +`<div class="ae-grid">${d.teachers.map(x=>{
       const e=x.earnings, pc=_pfCol(e.perf_score);
       const incent=e.gross_earned-e.class_earned;
       // v91: appointment letter sign status — card pe turant update dikhta hai
       const ltr=x.letter||{};
       const lchip=ltr.accepted
        ?`<span title="Appointment letter digitally signed${ltr.signed_at?' on '+esc(ltr.signed_at):''}${ltr.signature_name?' as '+esc(ltr.signature_name):''}" style="display:inline-flex;align-items:center;gap:4px;padding:3px 9px;border-radius:20px;font-weight:800;font-size:.6rem;letter-spacing:.04em;color:#047857;background:#04785714;border:1px solid #04785733">${ic('check')} LETTER SIGNED</span>`
        :`<span title="Appointment letter not signed yet" style="display:inline-flex;align-items:center;gap:4px;padding:3px 9px;border-radius:20px;font-weight:800;font-size:.6rem;letter-spacing:.04em;color:#b45309;background:#b4530914;border:1px solid #b4530933">${ic('clock')} LETTER PENDING</span>`;
       // v104: target-only teacher — payment amounts kabhi nahi; target + estimated % only
       if(x.target_only){
         const sp=(e.salary_pct!=null?e.salary_pct:e.perf_score);
         const spc=sp>=85?'#15803d':sp>=65?'#b45309':'#b91c1c';
         const dedT=e.est_ded_total||0, dedN=(e.est_deductions||[]).length;
         const tl=(x.policy_target&&x.policy_target.label)||'set by admin';
         return `<div class="card ae-tcard" style="border:1.5px solid rgba(184,148,31,.45)"><div class="card-body" style="padding:16px 18px">
          <div style="display:flex;align-items:center;gap:12px">
           <div class="ae-ava" id="aephot-${x.teacher.id}">${esc(initials(x.teacher.name))}</div>
           <div style="flex:1;min-width:0">
            <div style="font-weight:800;font-size:.98rem">${esc(x.teacher.name)}</div>
            <div style="font-size:.7rem;color:var(--text-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(x.teacher.employee_code)} \u00B7 ${(x.teacher.subjects||[]).slice(0,2).map(esc).join(', ')||'\u2014'}</div>
           </div>
           <div style="display:flex;flex-direction:column;align-items:flex-end;gap:5px">
            <span title="Estimated share of the monthly salary — amounts are never shown for target-only teachers" style="display:inline-block;min-width:52px;text-align:center;padding:4px 10px;border-radius:20px;font-weight:800;font-size:.8rem;color:${spc};background:${spc}18">est. ${sp}%</span>
            <span style="display:inline-flex;align-items:center;gap:4px;padding:3px 9px;border-radius:20px;font-weight:800;font-size:.6rem;letter-spacing:.04em;color:#b91c1c;background:#b91c1c14;border:1px solid #b91c1c33">TARGET ONLY</span>
           </div>
          </div>
          <div style="display:flex;align-items:center;gap:7px;margin:11px 0 3px;padding:7px 11px;border-radius:10px;background:linear-gradient(135deg,rgba(22,163,74,.1),rgba(22,163,74,.04));border:1px solid rgba(22,163,74,.3);font-size:.74rem;font-weight:700;color:#15803d">${ic('check')} Assigned target ${esc(tl)} — fully met this month</div>
          <div class="ae-mini">
           <div><b style="color:${spc}">est. ${sp}%</b><span>Of Salary</span></div>
           <div><b style="color:${dedT>0?'#b91c1c':'#15803d'}">${dedT>0?'\u2212'+dedT+'%':'0%'}</b><span>Est. Deductions${dedN?' ('+dedN+')':''}</span></div>
           <div><b>${esc(tl)}</b><span>Target · Fully Met</span></div>
          </div>
          <div style="display:flex;gap:6px;flex-wrap:wrap">
           <button class="btn btn-ghost btn-sm" onclick="openEarnDetail(${x.teacher.id})">View</button>
           <button class="btn btn-primary btn-sm" onclick="openPayConfig(${x.teacher.id})">${ic('edit')} Pay Structure</button>
          </div>
         </div></div>`;
       }
       return `<div class="card ae-tcard"><div class="card-body" style="padding:16px 18px">
        <div style="display:flex;align-items:center;gap:12px">
         <div class="ae-ava" id="aephot-${x.teacher.id}">${esc(initials(x.teacher.name))}</div>
         <div style="flex:1;min-width:0">
          <div style="font-weight:800;font-size:.98rem">${esc(x.teacher.name)}</div>
          <div style="font-size:.7rem;color:var(--text-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(x.teacher.employee_code)} \u00B7 ${(x.teacher.subjects||[]).slice(0,2).map(esc).join(', ')||'—'}</div>
         </div>
         <div style="display:flex;flex-direction:column;align-items:flex-end;gap:5px">
          <span style="display:inline-block;min-width:52px;text-align:center;padding:4px 10px;border-radius:20px;font-weight:800;font-size:.8rem;color:${pc};background:${pc}18">${e.perf_score}%</span>
          ${lchip}
         </div>
        </div>
        <div class="ae-mini">
         <div><b>${_inr(e.class_earned)}</b><span>Retainer</span></div>
         <div><b>${_inr(incent)}</b><span>Incentives</span></div>
         <div><b style="color:var(--primary)">${_inr(e.net_payable)}</b><span>Net Payable</span></div>
        </div>
        <div style="display:flex;gap:6px;flex-wrap:wrap">
         <button class="btn btn-ghost btn-sm" onclick="openEarnDetail(${x.teacher.id})">View</button>
         <button class="btn btn-primary btn-sm" onclick="openPayConfig(${x.teacher.id})">${ic('edit')} Pay Structure</button>
         <button class="btn btn-ghost btn-sm" onclick="adminSlip(${x.teacher.id})">Slip</button>
         <button class="btn btn-ghost btn-sm" onclick="adminLetter(${x.teacher.id})">Letter</button>
        </div>
       </div></div>`;}).join('')}</div>`;
    // v89: payout cards pe teacher photos (auth-header fetch → blob)
    d.teachers.filter(x=>x.teacher&&x.teacher.has_photo).forEach(x=>loadImgInto('aephot-'+x.teacher.id,'/api/admin/teacher/'+x.teacher.id+'/photo'));
  }catch(e){ body.innerHTML=`<div class="card"><div class="card-body"><div class="empty-state"><p>${esc(e.message)}</p></div></div></div>`; }
}
function _aEarnRow(tid){ return (_aEarnData&&_aEarnData.teachers||[]).find(x=>x.teacher.id===tid); }

function openEarnDetail(tid){
  const x=_aEarnRow(tid); if(!x){ toast('Load the list first.',true); return; }
  const e=x.earnings, a=x.activity;
  if(x.target_only){
    showModal('Estimated Earnings \u00B7 '+x.teacher.name+' ('+fmtMonthLabel(x.month)+')',
     _earnTargetOnlyHTML(x)+_activityStripHTML(x),
     `<button class="btn btn-primary" onclick="openPayConfig(${tid})">${ic('edit')} Pay Structure</button>
      <button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
    return;
  }
  showModal('Earnings — '+x.teacher.name+' ('+fmtMonthLabel(x.month)+')',
   _earnHeroHTML(x)+'<div style="margin-top:4px">'+_earnComponentsHTML(x)+'</div>'+_activityStripHTML(x),
   `<button class="btn btn-primary" onclick="openPayConfig(${tid})">${ic('edit')} Pay Structure</button>
    <button class="btn btn-ghost" onclick="adminSlip(${tid})">${ic('download')} Earnings Slip</button>
    <button class="btn btn-ghost" onclick="adminLetter(${tid})">${ic('book')} Appointment Letter</button>
    <button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
}

function openPayConfig(tid){
  const x=_aEarnRow(tid); if(!x){ toast('Load the list first.',true); return; }
  const p=x.pay, g=x.targets, t=x.teacher;
  const num=(id,lbl,v,hint)=>`<div><label style="font-size:.7rem;color:var(--text-muted);font-weight:700;display:block;margin-bottom:4px">${lbl}</label><input type="number" min="0" class="form-control" id="${id}" value="${v}" oninput="_pcSum()">${hint?`<div style="font-size:.64rem;color:var(--text-muted);margin-top:3px">${hint}</div>`:''}</div>`;
  const txt=(id,lbl,v,ph)=>`<div><label style="font-size:.7rem;color:var(--text-muted);font-weight:700;display:block;margin-bottom:4px">${lbl}</label><input class="form-control" id="${id}" value="${esc(v||'')}" placeholder="${ph||''}"></div>`;
  const _tgL=g.labels||{};
  const tgRow=(key,defName,count)=>`<div class="pct-row"><input class="form-control pct-name" id="pc_lbl_${key}" value="${esc(_tgL[key]||defName)}" maxlength="60" placeholder="Target name"><input type="number" min="0" class="form-control pct-num" id="pc_${key}" value="${count}"><span class="pct-tag">CORE</span></div>`;
  window._pcCustom=(g.custom||[]).map(c=>({name:c.name,count:c.count}));
  showModal('Pay Structure — '+x.teacher.name,
   `<div class="alert alert-info">Full control: amounts, monthly targets, designation and bank details. Saving updates this teacher's live earnings and documents immediately.</div>
    <div style="background:linear-gradient(135deg,#faf6e8,#f6efdb);border:1px solid #e6d9ac;border-radius:12px;padding:12px 16px;margin-bottom:12px">
     <label style="font-size:.7rem;color:#7a5c00;font-weight:800;display:block;margin-bottom:5px;letter-spacing:.04em">TOTAL MONTHLY SALARY — AUTO-SPLIT</label>
     <input type="number" min="0" class="form-control" id="pc_total" placeholder="e.g. 63000" style="font-weight:800;font-size:1rem" oninput="_pcSplit(this.value)">
     <div style="font-size:.66rem;color:#8a6d1a;margin-top:5px">As you enter the total, components split automatically — Classes <b>60%</b> · Tasks & Content <b>24%</b> · Notes/DPP/Tests <b>8%</b> · Doubts <b>4%</b> · Quality <b>4%</b> (classes first, then tasks, notes/DPP, doubts, quality). Every field can still be edited individually after the split.</div>
    </div>
    <div style="font-weight:800;font-size:.8rem;margin:4px 0 8px;color:var(--primary)">EARNINGS COMPONENTS (per month)</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(150px,100%),1fr));gap:10px">
     ${num('pc_retainer','Class Retainer (60%)',p.class_retainer)}
     ${num('pc_quality','Class Quality',p.class_quality)}
     ${num('pc_notesdpp','Notes + DPP + Tests',p.notes_dpp)}
     ${num('pc_doubt','Doubt Resolution',p.doubt_resolution)}
     ${num('pc_project','Project & Content',p.project_delivery)}
    </div>
    <div style="display:flex;justify-content:space-between;align-items:center;background:var(--hover);border-radius:10px;padding:9px 14px;margin-top:10px">
     <span style="font-size:.76rem;font-weight:700">Maximum Monthly Potential</span><b id="pc_max" style="font-size:1rem"></b>
    </div>
    <div id="pc_60" style="font-size:.68rem;color:var(--text-muted);margin-top:4px"></div>
    <div style="font-weight:800;font-size:.8rem;margin:14px 0 8px;color:var(--primary)">MONTHLY TARGETS</div>
    <div style="font-size:.7rem;color:var(--text-muted);margin:-3px 0 10px">Core targets drive the earnings calculation — rename them anytime. Add your own extra targets below; they appear on the appointment letter.</div>
    <div style="display:flex;flex-direction:column;gap:8px">
     ${tgRow('tests','Weekly Tests',g.tests_target)}
     ${tgRow('videos','Videos (One Shot/Revision)',g.videos_target)}
     ${tgRow('live','YouTube Live',g.live_target)}
     ${tgRow('shorts','Shorts',g.shorts_target)}
    </div>
    <div id="pc_tg_custom" style="margin-top:8px"></div>
    <div style="font-weight:800;font-size:.8rem;margin:14px 0 8px;color:var(--primary)">PROFILE & BANK (for letter & slip)</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(160px,100%),1fr));gap:10px">
     ${txt('pc_desig','Designation',t.designation==='Subject Teacher'?'':t.designation,'Subject Teacher')}
     ${txt('pc_dept','Department',t.department,'Academic — NIOS Coaching')}
     ${txt('pc_emp','Employee Code',t.employee_code,'MVS-T-000')}
     ${txt('pc_bank','Bank Name',t.bank,'HDFC Bank')}
     ${txt('pc_acct','Account No.',t.account_no)}
     ${txt('pc_ifsc','IFSC',t.ifsc)}
    </div>`,
   `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="submitPayConfig(${tid})">${ic('check')} Save Pay Structure</button>`);
  _pcSum();
  _pcCustomRender();
}
function _pcCustomRender(){
  const box=document.getElementById('pc_tg_custom'); if(!box) return;
  const rows=(window._pcCustom||[]).map((c,i)=>`<div class="pct-row"><input class="form-control pct-name" id="pc_c_name_${i}" value="${esc(c.name)}" maxlength="60" placeholder="Target name" oninput="_pcCustom[${i}].name=this.value"><input type="number" min="0" class="form-control pct-num" value="${c.count}" oninput="_pcCustom[${i}].count=this.value"><button class="btn btn-ghost btn-sm pct-del" title="Remove this target" onclick="_pcCustomDel(${i})">×</button></div>`).join('');
  box.innerHTML=rows+`<button class="btn btn-ghost btn-sm" onclick="_pcCustomAdd()">${ic('plus')} Add Target</button>`;
}
function _pcCustomAdd(){ window._pcCustom.push({name:'',count:4}); _pcCustomRender(); setTimeout(()=>{ const n=document.getElementById('pc_c_name_'+(window._pcCustom.length-1)); if(n) n.focus(); },60); }
function _pcCustomDel(i){ window._pcCustom.splice(i,1); _pcCustomRender(); }
function _pcSum(){
  const v=id=>parseInt((document.getElementById(id)||{}).value)||0;
  const mx=v('pc_retainer')+v('pc_quality')+v('pc_notesdpp')+v('pc_doubt')+v('pc_project');
  const el=document.getElementById('pc_max'); if(el) el.textContent=_inr(mx);
  const tt=document.getElementById('pc_total'); if(tt && document.activeElement!==tt) tt.value=mx||'';
  const r=document.getElementById('pc_60');
  if(r){ const pct=mx>0?Math.round(v('pc_retainer')/mx*100):0;
    r.textContent='Retainer is '+pct+'% of maximum '+(pct===60?'— matches the 60% rule.':pct<60?'— below the 60% rule ('+_inr(Math.round(mx*0.6))+' would be 60%).':'— above 60% (rule: 60%).'); }
}
function _pcSplit(total){
  total=Math.max(0,parseInt(total)||0);
  const s=(id,v)=>{const e=document.getElementById(id);if(e)e.value=v;};
  const r=Math.round(total*0.60), p=Math.round(total*0.24), n=Math.round(total*0.08), d=Math.round(total*0.04);
  s('pc_retainer',r); s('pc_project',p); s('pc_notesdpp',n); s('pc_doubt',d); s('pc_quality',total-r-p-n-d);
  _pcSum();
}
async function submitPayConfig(tid){
  const v=id=>(document.getElementById(id)||{}).value;
  const body={teacher_id:tid,
    class_retainer:v('pc_retainer'),class_quality:v('pc_quality'),notes_dpp:v('pc_notesdpp'),
    doubt_resolution:v('pc_doubt'),project_delivery:v('pc_project'),
    tests_target:v('pc_tests'),videos_target:v('pc_videos'),live_target:v('pc_live'),shorts_target:v('pc_shorts'),
    target_labels:{tests:v('pc_lbl_tests'),videos:v('pc_lbl_videos'),live:v('pc_lbl_live'),shorts:v('pc_lbl_shorts')},
    custom_targets:(window._pcCustom||[]).map(c=>({name:(c.name||'').trim(),count:parseInt(c.count)||0})).filter(c=>c.name),
    designation:v('pc_desig'),department:v('pc_dept'),employee_code:v('pc_emp'),
    bank_name:v('pc_bank'),account_no:v('pc_acct'),ifsc:v('pc_ifsc')};
  try{ const r=await api('/api/admin/earnings/config','POST',body); toast(r.message); closeModal(); aEarnFetch(); }
  catch(e){ toast(e.message,true); }
}
function adminSlip(tid){
  const x=_aEarnRow(tid); if(!x){ toast('Load the list first.',true); return; }
  _printDocHTML(_slipHTML(x));
}
function adminLetter(tid){
  const x=_aEarnRow(tid); if(!x){ toast('Load the list first.',true); return; }
  _printDocHTML(_letterHTML(x));
}

// ---- Office Locations (geofence, multi-branch) setup ----
window._olOffices=[]; window._olIps=[]; window._olUnknown=[];
async function openOfficeLocation(){
  try{ const d=await api('/api/admin/office-location'); window._olOffices=(d.offices||[]).map(o=>({name:o.name,lat:o.lat,lng:o.lng,radius:o.radius})); window._olIps=(d.ips||[]).slice(); window._olUnknown=(d.unknown_ips||[]).slice(); }
  catch(e){ window._olOffices=[]; window._olIps=[]; window._olUnknown=[]; }
  showModal('Office Locations (Geofence)',
   `<div class="alert alert-info" style="font-size:.82rem">Add each branch's <b>name + location + radius</b>. A teacher can punch from within the radius of <b>any branch</b> — the <b>branch name and distance</b> are recorded with every punch. Punching from outside is <b>blocked</b>.</div>
    <div id="ol-list"></div>
    <div style="border:1px dashed var(--border);border-radius:12px;padding:14px;margin-top:6px">
      <div style="font-weight:700;font-size:.85rem;margin-bottom:8px">Add a New Branch</div>
      <div class="form-group"><label>Branch name</label><input class="form-control" id="ol-name" placeholder="e.g. Head Office / Sector 15 Branch"></div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
        <div class="form-group"><label>Latitude</label><input class="form-control" id="ol-lat" placeholder="28.613900"></div>
        <div class="form-group"><label>Longitude</label><input class="form-control" id="ol-lng" placeholder="77.209000"></div>
      </div>
      <div class="form-group"><label>Radius (meter)</label><input class="form-control" id="ol-radius" type="number" min="5" max="500" value="30">
      <div style="font-size:.72rem;color:var(--text-muted);margin-top:4px">Mobile GPS typically has a 5-20m error — <b>20-30m is practical</b>; max 500m.</div></div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <button class="btn btn-ghost btn-sm" onclick="olUseCurrent()">${ic('location')} Use My Current Location</button>
        <button class="btn btn-primary btn-sm" onclick="olAddBranch()">+ Add Branch</button>
      </div>
      <div id="ol-note" style="margin-top:8px"></div>
    </div>
    <div style="border:1px dashed var(--border);border-radius:12px;padding:14px;margin-top:10px">
      <div style="font-weight:700;font-size:.85rem;margin-bottom:4px">Office WiFi / PC Punch</div>
      <div style="font-size:.76rem;color:var(--text-muted);margin-bottom:8px">A <b>PC, laptop or phone</b> connected to the office broadband/WiFi can punch <b>without location</b>. <b>Have 7–8 WiFis?</b> If they all run on one broadband line, <b>a single IP</b> is enough; if they are on separate lines, add each line's IP separately (connect to that WiFi and tap "Add this PC's IP", or use the unknown list below). <b>Never add a home IP</b> — that would allow punching from home!</div>
      <div id="ol-ip-list"></div>
      <div id="ol-unknown"></div>
      <button class="btn btn-ghost btn-sm" onclick="olAddMyIp()">${ic('location')} Add This PC's IP</button>
      <div id="ol-ip-note" style="margin-top:6px"></div>
    </div>`,
   `${window._olOffices.length?`<button class="btn btn-danger" onclick="olClear()">Remove All (Geofence OFF)</button>`:''}<button class="btn btn-primary" onclick="saveOfficeLocation()">Save (${window._olOffices.length} branch)</button>`);
  _olRenderList(); _olRenderIps();
}
function _olRenderIps(){
  const el=document.getElementById('ol-ip-list'); if(!el) return;
  const ips=window._olIps;
  if(!ips.length){
    el.innerHTML='<div style="font-size:.76rem;color:var(--text-muted);margin-bottom:8px">No WiFi IPs yet — punching from PC/4G will ask for GPS location.</div>';
  } else {
    const rows=ips.map((ip,i)=>`<div class="pc-task"><div class="t"><div class="tt">${esc(ip)}</div><div class="td">Office WiFi — punching on this network works without GPS</div></div>
      <button class="btn btn-ghost btn-sm" onclick="olDelIp(${i})">Remove</button></div>`).join('');
    // v121: 5 se zyada IPs ho to scroll-box (5 rows dikhte hain) + Hide/Show toggle
    el.innerHTML=ips.length>5
      ? `<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:5px">
          <div style="font-size:.74rem;color:var(--text-muted)"><b>${ips.length}</b> WiFi IPs — scroll to see all</div>
          <button class="btn btn-ghost btn-sm" style="padding:3px 10px;font-size:.72rem" id="ol-ip-toggle" onclick="olToggleIps()">Hide list</button></div>
        <div id="ol-ip-scroll" style="max-height:332px;overflow-y:auto;padding-right:2px">${rows}</div>`
      : rows;
  }
  const un=document.getElementById('ol-unknown');
  if(un){
    const list=(window._olUnknown||[]).filter(x=>!window._olIps.includes(x.ip));
    un.innerHTML=list.length?`<div style="font-size:.78rem;font-weight:700;margin:10px 0 6px">New IPs — punches were attempted from these (add them if they are office WiFi):</div>`+list.map((x,i)=>`<div class="pc-task"><div class="t"><div class="tt">${esc(x.ip)}</div><div class="td">last try: ${esc(x.at||'-')}</div></div>
      <button class="btn btn-primary btn-sm" onclick="olAddUnknown(${i})">Add</button></div>`).join(''):'';
  }
}
function olAddUnknown(i){
  const list=(window._olUnknown||[]).filter(x=>!window._olIps.includes(x.ip));
  const x=list[i]; if(!x) return;
  window._olIps.push(x.ip); _olRenderIps();
  const n=document.getElementById('ol-ip-note');
  if(n) n.innerHTML=`<div class="alert alert-success" style="font-size:.8rem;margin-bottom:0">IP <b>${esc(x.ip)}</b> added — don't forget to Save.</div>`;
}
async function olAddMyIp(){
  const n=document.getElementById('ol-ip-note');
  try{
    const d=await api('/api/admin/my-ip');
    const ip=String(d.ip||'').trim();
    if(!ip){ if(n) n.innerHTML='<div class="alert alert-danger" style="font-size:.8rem;margin-bottom:0">Could not detect the IP.</div>'; return; }
    if(window._olIps.includes(ip)){ if(n) n.innerHTML=`<div class="alert alert-info" style="font-size:.8rem;margin-bottom:0">IP ${esc(ip)} is already on the list.</div>`; return; }
    window._olIps.push(ip); _olRenderIps();
    if(n) n.innerHTML=`<div class="alert alert-success" style="font-size:.8rem;margin-bottom:0">This PC's IP <b>${esc(ip)}</b> added — don't forget to Save.</div>`;
  }catch(e){ if(n) n.innerHTML=`<div class="alert alert-danger" style="font-size:.8rem;margin-bottom:0">${esc(e.message)}</div>`; }
}
function olDelIp(i){ window._olIps.splice(i,1); _olRenderIps(); }
// v121: IP list collapse/expand (5+ IPs pe)
function olToggleIps(){
  const sc=document.getElementById('ol-ip-scroll'), t=document.getElementById('ol-ip-toggle');
  if(!sc||!t) return;
  const hid=sc.style.display==='none';
  sc.style.display=hid?'':'none';
  t.textContent=hid?'Hide list':`Show list (${window._olIps.length})`;
}
function _olRenderList(){
  const el=document.getElementById('ol-list'); if(!el) return;
  if(!window._olOffices.length){ el.innerHTML='<div class="alert alert-warning" style="font-size:.82rem">No branches yet — <b>geofence is OFF</b>; teachers can punch from anywhere (including home).</div>'; return; }
  el.innerHTML=window._olOffices.map((o,i)=>`<div class="pc-task"><div class="t"><div class="tt">${ic('location')} ${esc(o.name)}</div><div class="td">${o.lat}, ${o.lng} · radius <b>${o.radius}m</b></div></div>
    <button class="btn btn-ghost btn-sm" onclick="olDelBranch(${i})">Remove</button></div>`).join('');
  const sv=[...document.querySelectorAll('#modal button')].find(b=>b.textContent.startsWith('Save ('));
  if(sv) sv.textContent=`Save (${window._olOffices.length} branch)`;
}
function olUseCurrent(){
  const n=document.getElementById('ol-note');
  if(!navigator.geolocation){ if(n) n.innerHTML='<div class="alert alert-danger" style="font-size:.8rem">This device/browser does not support location — enter it manually.</div>'; return; }
  if(n) n.innerHTML='<div class="alert alert-info" style="font-size:.8rem;margin-bottom:0">Fetching your location... (please keep GPS on)</div>';
  navigator.geolocation.getCurrentPosition(
    pos=>{ document.getElementById('ol-lat').value=pos.coords.latitude.toFixed(6);
           document.getElementById('ol-lng').value=pos.coords.longitude.toFixed(6);
           if(n) n.innerHTML=`<div class="alert alert-success" style="font-size:.8rem;margin-bottom:0">Location filled (GPS accuracy ~${Math.round(pos.coords.accuracy||0)}m). Now type the branch name and tap Add.</div>`; },
    err=>{ if(n) n.innerHTML='<div class="alert alert-danger" style="font-size:.8rem;margin-bottom:0">Could not get the location — allow permission in the browser or enter it manually.</div>'; },
    {enableHighAccuracy:true,timeout:15000,maximumAge:0});
}
function olAddBranch(){
  const name=(document.getElementById('ol-name').value||'').trim();
  const lat=parseFloat(document.getElementById('ol-lat').value), lng=parseFloat(document.getElementById('ol-lng').value);
  const radius=parseInt(document.getElementById('ol-radius').value)||30;
  const n=document.getElementById('ol-note');
  const err=t=>{ if(n) n.innerHTML=`<div class="alert alert-danger" style="font-size:.8rem;margin-bottom:0">${t}</div>`; };
  if(!name) return err('Please enter the branch name.');
  if(window._olOffices.some(o=>o.name.toLowerCase()===name.toLowerCase())) return err(`A branch named '${esc(name)}' already exists.`);
  if(isNaN(lat)||isNaN(lng)) return err('Please fill in the latitude/longitude (or tap Use My Current Location).');
  if(radius<5||radius>500) return err('Please keep the radius between 5-500 metres.');
  if(window._olOffices.length>=6) return err('You can add a maximum of 6 branches.');
  window._olOffices.push({name,lat,lng,radius});
  document.getElementById('ol-name').value=''; document.getElementById('ol-lat').value=''; document.getElementById('ol-lng').value='';
  if(n) n.innerHTML='';
  _olRenderList();
}
function olDelBranch(i){ window._olOffices.splice(i,1); _olRenderList(); }
async function saveOfficeLocation(){
  if(!window._olOffices.length){ toast('Add at least 1 branch (or use Clear All to turn geofence OFF).',true); return; }
  try{ const r=await api('/api/admin/office-location','POST',{offices:window._olOffices,ips:window._olIps}); window._aOffices=null; toast(r.message); closeModal(); }
  catch(e){ toast(e.message,true); }
}
async function olClear(){
  if(!confirm('Removing all branches will turn geofencing OFF — teachers will be able to punch from anywhere. Are you sure?')) return;
  try{ const r=await api('/api/admin/office-location','POST',{clear:true}); window._aOffices=null; toast(r.message); closeModal(); }
  catch(e){ toast(e.message,true); }
}

/* ---- ADMIN: finalize / paid ---- */
async function payoutFinalize(tid,name){
  if(!confirm('FINALIZE the payout for '+fmtMonthLabel(_aEarnMonth||curMonth())+'? The calculation snapshot will now be frozen.')) return;
  try{ const r=await api('/api/admin/teacher/'+tid+'/payout-finalize','POST',{month:_aEarnMonth||curMonth()}); toast(r.message); if(window.aEarnFetch) aEarnFetch(); }
  catch(e){ toast(e.message,true); }
}
async function payoutPaid(tid,name){
  if(!confirm('Mark this payout as PAID?')) return;
  try{ const r=await api('/api/admin/teacher/'+tid+'/payout-paid','POST',{month:_aEarnMonth||curMonth()}); toast(r.message); if(window.aEarnFetch) aEarnFetch(); }
  catch(e){ toast(e.message,true); }
}

